P.entries["zone:razorfenkraul"] = {n="剃刀沼泽",s="剃刀沼泽坐落在贫瘠之地遥远的南部，是卡利姆多野猪人的祖居心脏地带。这些凶猛的部落将这片由巨型荆棘构成的密集迷宫视为他们始祖——陨落的半神阿迦玛甘的神圣安息之地。如今，在野猪人女族长卡尔加·刺肋的暴政下，剃刀沼泽变得极具侵略性，她所进行的黑暗勾当威胁到了整个地区。",h="剃刀沼泽坐落在贫瘠之地遥远的南部，是卡利姆多野猪人的祖居心脏地带。这些凶猛的部落将这片由巨型荆棘构成的密集迷宫视为他们始祖——陨落的半神阿迦玛甘的神圣安息之地。如今，在野猪人女族长卡尔加·刺肋的暴政下，剃刀沼泽变得极具侵...",kw={"阿迦玛甘","贫瘠之地","卡尔加","哈尔玛","沼泽","野猪人","拉姆塔斯","剃刀","刺肋","天灾军团"},ang={["class:Shaman"]="野猪人的地卜术围绕着阿迦玛甘之血扭曲大地与元素，展示了以野蛮意图所施展的原始萨满力量。",["faction:Horde"]="遏制剃刀沼泽内部的侵略行径对于保护贫瘠之地南部广袤区域的补给马车和新兴定居点至关重要。",["race:Tauren"]="野猪人长期与莫高雷的边界发生冲突，而他们通过黑暗结盟对大地的亵渎，使得净化剃刀沼泽成为部落防御的当务之急。",["race:Undead"]="幽暗城的药剂师们对荆棘丛中发现的奇异试剂、蝙蝠粪便以及关于天灾军团入侵的传闻产生了浓厚的兴趣。"},sec={{t="野猪神之血",b="一万年前的上古之战中，伟大的荒野半神阿迦玛甘投身于对抗燃烧军团的战斗。这位伟大的野猪最终战死沙场，但他的牺牲保全了艾泽拉斯的生命。传说他的血渗入大地之处，都会长出覆盖着巨大荆棘的藤蔓，在南方的平原上形成了厚重的防御性迷宫。野猪人将阿迦玛甘视为他们神圣的先祖，并将这些巨大的荆棘丛据为圣地，其中最宏伟的一片便是剃刀沼泽。"},{t="老巫婆的野心",b="剃刀沼泽由老巫婆卡尔加·刺肋以铁腕统治。在她的专制领导下，崇尚萨满教的野猪人放弃了传统的领地小规模冲突，转而对敌对部落、区域贸易路线和新兴的部落定居点发动了侵略性的协同战争。更糟糕的是，令人不安的低语和侦察报告显示，有亡灵恶魔在荆棘丛附近游荡。人们担心卡尔加已经开始与可怕的天灾军团的使者进行谈判，试图利用禁忌的通灵术来增强她部落的野蛮行径。"}},faq={{q="什么是剃刀沼泽？",a="剃刀沼泽位于南贫瘠之地，是一片由巨型荆棘藤蔓构成的古老地下网络。它是野猪人的精神心脏和堡垒，他们将这个错综复杂的迷宫视为祖居之地。",al={"什么是剃刀沼泽","剃刀沼泽介绍","剃刀沼泽概览"}},{q="巨型荆棘是如何产生的？",a="这些巨大的荆棘是在一万年前的上古之战期间从大地中萌发的，它们直接源自陨落的野猪半神阿迦玛甘所流下的鲜血。",al={"为什么有巨型荆棘","荆棘丛的来历","阿迦玛甘荆棘"}},{q="谁统治着剃刀沼泽？",a="剃刀沼泽由卡尔加·刺肋统治，她是一位冷酷的野猪人巫婆兼萨满，指挥着剃刀沼泽部落，并策划了对周边村庄和旅行者的袭击。",al={"剃刀沼泽的首领是谁","卡尔加·刺肋","剃刀沼泽的老巫婆"}},{q="为什么部落会关注剃刀沼泽？",a="除了野猪人不断对贫瘠之地的新兴定居点进行袭击外，部落侦察兵还在荆棘丛附近发现了亡灵潜伏，这引起了令人恐惧的担忧，即卡尔加正在与天灾军团结盟。",al={"为什么部落关注这里","部落对剃刀沼泽的关注","贫瘠之地的威胁"}},{q="为什么联盟军队会对剃刀沼泽感兴趣？",a="卡尔加部落的侵略性扩张威胁到了靠近菲拉斯和千针石林的哨所，促使萨兰纳尔的联盟指挥官和侦察兵寻求除掉这位巫婆，以稳定边境。",al={"联盟剃刀沼泽任务","为什么联盟会去那里","萨兰纳尔任务"}},{q="击败大地召唤者哈尔玛对剧情意味着什么？",a="击败潜藏在荆棘丛深处的一位稀有且有影响力的大地塑形师——大地召唤者哈尔玛，是对野猪人大地塑造祭司阶层的一次打击。剥夺剃刀沼泽这种强大的元素召唤者，会破坏卡尔加·刺肋的防御工事，并阻碍野猪人操控阿迦玛甘圣洁荆棘的能力。",al={"大地召唤者哈尔玛死后会发生什么","大地召唤者哈尔玛背景故事","哈尔玛被击败"}}},fp="14,218,21.427.0,20.423.1,23.142.0,34.156.0,25.170.0,48.182.0,48.157.0,59.248.0"}
P.entries["zone:redridge"] = {n="赤脊山",s="艾尔文森林的东部，赤脊山拥有湍急的河流、树木繁茂的山坡以及宁静广阔的止水湖。尽管这里风景秀丽，但该地区正遭到敌对的影牙豺狼人的围攻，以及来自黑铁部落的黑石兽人的侵犯。由于王国的军队被暴风城的内乱所牵制，湖畔镇必须依靠游荡的雇佣兵来坚守防线。",h="艾尔文森林的东部，赤脊山拥有湍急的河流、树木繁茂的山坡以及宁静广阔的止水湖。尽管这里风景秀丽，但该地区正遭到敌对的影牙豺狼人的围攻，以及来自黑铁部落的黑石兽人的侵犯。由于王国的军队被暴风城的内乱所牵制，湖畔镇必须依靠游荡...",kw={"黑石兽人","止水湖","湖畔镇","所罗门镇长","治安官马瑞斯","赤脊山","撕裂者山谷","影牙豺狼人","石堡","石堡要塞","弗纳·奥斯古"},ang={["faction:Alliance"]="湖畔镇是联盟年轻士兵磨练技能以对抗有组织的兽人和豺狼人部队的重要前线枢纽。",["faction:Horde"]="盘踞在赤脊山的黑石兽人属于敌对的黑铁部落，他们不仅是湖畔镇人类的敌人，也是萨尔的部落的敌人。",["profession:Herbalism"]="温和的山坡上生长着稳定的石南草、跌打草、魔皇草和迅蓟叶。",["profession:Mining"]="止水湖周围的岩石峭壁和山谷蕴藏着丰富的铜矿、锡矿和稀有的银矿脉，特别是在瑞斯班洞穴附近。"},sec={{t="被围困的堡垒",b="赤脊山脉曾经是王国最宁静的角落之一，为暴风城提供木材、淡水鱼和农作物。今天，那种宁静的生活已经不复存在。湖畔镇时刻都在加固防御，以抵御咄咄逼人的入侵。在东部，曾经是王国引以为傲的堡垒——石堡要塞，如今已落入叛变的黑石兽人手中，他们切断了道路，并扬言要彻底淹没东部的河谷。"},{t="分裂的山脉",b="从地理上讲，这些山峰构成了贯穿艾泽拉斯次大陆的山脊的一部分。几个世纪前，这条山脉向北延伸得更远，直到黑铁部族无意中召唤了炎魔之王拉格纳罗斯，撕裂了大地，形成了黑石山炽热的火山口。那场大灾变将北部的山峰截断，形成了灰烬弥漫的燃烧平原，只留下南部的赤脊山谷依旧郁郁葱葱，却也更易受到从上方山坡俯冲而下的攻击。"},{t="被王权忽视的地区",b="尽管所罗门镇长和治安官马瑞斯不断请求增援，但暴风城的摄政委员会实际上已经放弃了湖畔镇，任其自生自灭。寄往哨兵岭和夜色镇的绝望请求也如石沉大海，因为这两个姊妹定居点本身也陷入了各自的危机之中。由于迟迟不见增援，当地的镇长们只能雇佣任何有能力的雇佣兵，只要他们愿意冒险走上湖边大道，扫荡豺狼人营地，并击退笼罩在止水湖上的阴影。"},{t="隐藏的忠诚",b="流氓术士摩根斯最初与黑石兽人结盟夺取了石堡要塞，随后又背叛了他们，并从伊尔加拉之塔控制了影牙豺狼人为他效力。在黑石调查期间发现的报告还揭露了兽人与黑龙军团之间的联盟。"}},faq={{q="为什么暴风城不派士兵支援湖畔镇？",a="在失去石堡要塞后，湖畔镇幸存的皇家士兵人数处于严重劣势。所罗门镇长已经呼吁提供部队、武器、粮食和补给，但暴风城的兵力捉襟见肘，邻近的定居点也自顾不暇。因此，驻军只能依靠冒险者来协助守卫该地区。",al={"为什么没有暴风城守卫","为什么赤脊山被遗弃","暴风城军队在哪里"}},{q="谁控制了石堡要塞？",a="石堡要塞已经被隶属于黑铁部落的黑石兽人占领。他们盘踞在这个坚固的山中据点，威胁着东部的河谷以及沿湖边大道的交通。他们在调查过程中被揭露与其他当地威胁有着千丝万缕的联系。",al={"谁在石堡要塞","石堡要塞的敌人","石堡要塞发生了什么"}},{q="止水湖里有什么威胁？",a="虽然从岸边看去波澜不惊，但止水湖的水域中到处都是敌对的鱼人部落，他们经常袭击附近的码头和废墟。游泳者还必须面对潜伏在水面之下的掠食性深水食人鱼，这也引发了关于深处潜伏着水怪的传言。",al={"止水湖的怪物","赤脊山湖泊的危险","止水湖鱼人"}},{q="赤脊山有部落的前哨站吗？",a="没有。赤脊山没有任何部落的定居点、商人或飞行点。路过该地区的部落旅行者通常是在北部的燃烧平原和东南部的悲伤沼泽之间往返，他们必须在联盟控制的道路和危险的荒野中穿行。",al={"赤脊山的部落城镇","赤脊山属于部落还是联盟","赤脊山的部落飞行点"}},{q="三角路口是什么地方？",a="三角路口是赤脊山西南角的一个重要十字路口。它连接着湖边大道、艾尔文森林的东部边界以及通往暮色森林的道路，这使其成为了一个重要的交通枢纽，经常成为游荡的豺狼人和野生动物的目标。",al={"三角路口","赤脊山交叉路口"}},{q="为什么通往燃烧平原的北部道路如此危险？",a="穿过撕裂者营地向北的道路直通燃烧平原，那是一片荒凉的火山荒地，遍布强大的黑石兽人、火元素和龙人。这种危险程度的突然转变，使得这条北部山口成为艾泽拉斯南部最致命的地理险道之一。",al={"赤脊山北路","燃烧平原和赤脊山边界","赤脊山北部山口"}}},fp="18,271,21.379.0,17.453.0,22.430.0,22.309.1,52.324.0,29.235.0,37.186.0,41.258.0,26.229.0,60.279.0"}
P.entries["zone:riverglades"] = {n="河林",s="河林是一片位于燃烧平原和荒芜之地以东的争议河谷，历史上曾被暴风王国宣称拥有。在第一次战争期间，该地区被旧部落占领并遭王室遗弃，如今这里仍是战场，当地的人类忠诚派与现代部落的前哨站以及当地的野生生物在此不断冲突。它西南接壤赤脊山，南邻悲伤沼泽，隔海与塔纳利斯相望。",h="河林是一片位于燃烧平原和荒芜之地以东的争议河谷，历史上曾被暴风王国宣称拥有。在第一次战争期间，该地区被旧部落占领并遭王室遗弃，如今这里仍是战场，当地的人类忠诚派与现代部落的前哨站以及当地的野生生物在此不断冲突。它西南接壤...",kw={"黑石小径","铁马兄弟会","德玛尔·布兰特","法霍德要塞","克罗多克要塞","爆破引线港","赤脊山小径","河林","洛格玛","阳光林地"},ang={["faction:Alliance"]="联盟士兵在河林中看到了旧日的伤痕，铁马兄弟会的残部在这里继续着一场未被歌颂的十字军东征，试图收复暴风城在第一次战争期间遗弃的土地。",["faction:Horde"]="对于部落来说，建立像洛格玛这样的前哨站确保了一个安全的沿海据点，并使那些残留在赤脊山以东的人类旧要塞持续承受压力。",["race:Human"]="人类旅行者在阳光林地见证了他们自身历史中悲惨的一章，这提醒着人们第一次战争对王国东部边境造成的沉重代价。"},sec={{t="被遗忘的边境",b="河林历史上曾是暴风王国的一部分，在第一次战争中，当旧部落横扫该地区时，河林陷入了毁灭。其中心定居点阳光林地被兽人洗劫，兽人留下了一座法师塔，仅仅是为了研究人类的魔法，同时奴役了幸存的镇民。尽管暴风城的士兵曾努力解救俘虏并重建，但王国最终认定整个山谷已失守，并将资源转移到保卫核心领土上。多年来，该地区在很大程度上失去了王室的正式支持。"},{t="法霍德要塞之争",b="尽管被暴风城的高层遗弃，人类守军从未完全放弃他们的家园。在传说中的铁马兄弟会的骑士指挥官德玛尔·布兰特的领导下，残余的忠诚派坚守着法霍德要塞，以此作为抵御荒野和敌对入侵者的堡垒。与此同时，现代部落也在附近的洛格玛和博尔德罗克等前哨站保持着强大的存在，确保了围绕这片林地的古老冲突持续发酵。"},{t="地理与旅行",b="河林沿禁忌之海海岸延伸，两侧是多山的地形和蜿蜒的水道。步行者可以向西穿过黑石小径前往燃烧平原，向西南蜿蜒经过赤脊山小径前往赤脊山，向南进入悲伤沼泽，或者向西北穿过暮光之帷前往荒芜之地。在海岸线上，爆破引线港提供横跨海洋直接连接塔纳利斯的热砂港的海上航线。"}},faq={{q="什么是河林？",a="河林是一个位于荒芜之地和燃烧平原以东，面朝禁忌之海的争议地区。它曾经是暴风城的一片繁荣领土，现在则是一个活跃的前线，由法霍德要塞的联盟和洛格玛的部落在此争夺。",al={"河林概览","这是一个什么区域","关于河林"}},{q="阳光林地发生了什么？",a="阳光林地在第一次战争期间遭到了旧部落的袭击和摧毁。兽人将幸存的村民俘虏为奴隶，并保留了一座当地的法师塔以破译人类的魔法。尽管暴风城的士兵解救了俘虏并试图重建，但王国最终放弃了该地区，转而专注于其西部边境。",al={"阳光林地的历史","阳光林地的陷落","这个城镇发生了什么"}},{q="谁控制着法霍德要塞？",a="法霍德要塞由铁马兄弟会的骑士指挥官德玛尔·布兰特领导的联盟忠诚派所控制。在暴风城最初将该领土视为失地后，他的部队多年来一直在此战斗，试图收复河林。",al={"谁领导法霍德要塞","河林的联盟","铁马兄弟会"}},{q="如何从河林前往塔纳利斯？",a="一艘沿海船只定期往返于河林东岸的爆破引线港和塔纳利斯的热砂港之间，提供了一条横跨海洋的直接海上航线。",al={"前往塔纳利斯的船只","爆破引线港的船","如何前往塔纳利斯"}},{q="哪些山口通往其他区域？",a="你可以向西南穿过赤脊山小径到达赤脊山，或者向南直接穿过前往悲伤沼泽。向西，黑石小径经过刺毛丘陵通往燃烧平原，而暮光之帷北部的道路则直接通往荒芜之地。",al={"如何前往赤脊山","从河林出发的山口","河林的出口"}},{q="克罗多克要塞是什么？",a="克罗多克要塞是河林内的一座防御严密的地下城建筑群，代表了这片争议领土上敌对势力的一个主要据点。",al={"克罗多克要塞","河林的地下城","这里有什么地下城"}}},fp="11,291,22.431.0,25.415.0,20.414.0,24.187.0,28.295.0,27.212.0,46.146.0,34.266.0,28.127.0"}
P.entries["zone:ruinsoflordaeron"] = {n="洛丹伦废墟",s="洛丹伦废墟坐落在幽暗城地下结构的的正上方，是曾经强大的人类北方王国残留的空洞遗迹。在第三次战争期间，这座城市陷落于天灾军团和阿尔萨斯王子之手，如今其地表的街道和破碎的广场上爬满了游荡的怪物、复仇的幽灵和邪恶的实验者。联盟和部落都会派遣冒险者深入这座遭受重创的堡垒，以找回往昔的遗物，或清除潜伏在被遗忘者首都上方的恐怖生物。",h="洛丹伦废墟坐落在幽暗城地下结构的的正上方，是曾经强大的人类北方王国残留的空洞遗迹。在第三次战争期间，这座城市陷落于天灾军团和阿尔萨斯王子之手，如今其地表的街道和破碎的广场上爬满了游荡的怪物、复仇的幽灵和邪恶的实验者。联盟...",kw={"比约克","洛丹伦队长","新的瘟疫","拉索马尔","洛丹伦废墟","被遗弃者","男爵","提瑞斯法林地","幽暗城","维克多·维尔","枯牙"},ang={["class:Paladin"]="洛丹伦是白银之手骑士团的摇篮；走过它那被亵渎的大厅以清除恐怖并让不安的队长们安息，是圣光的一项神圣职责。",["faction:Alliance"]="深入洛丹伦让联盟得以在被遗忘者首都的门槛上进行打击，同时为他们被屠杀的北方兄弟的灵魂带来正义与安宁。",["race:Human"]="人类冒险者将这座废墟化的首都视为被背叛所窃取的圣地，寻求找回失落的传家宝并祭奠阵亡的同胞。",["race:Undead"]="对于被遗忘者来说，上方的废墟是他们曾经的家园和永恒的墓地。清理废墟可以确保他们的前门安全，并为药剂师们开发新的瘟疫提供所需的材料。"},sec={{t="陷落帝国的庭院",b="曾经的洛丹伦王城是东部王国的璀璨明珠，是泰瑞纳斯·米奈希尔二世国王的王座所在地，也是人类文明跳动的心脏。当阿尔萨斯王子从诺森德归来时，他在王座大厅弑父，并向市民释放了亡灵。今天，尽管被遗忘者居住在下方的幽暗城墓穴中，但地表的废墟依然是一个被遗忘的暮光地带。破碎的拱门和杂草丛生的鹅卵石路成了枯牙这类野兽以及往昔疯狂残影的庇护所。"},{t="折磨与瘟疫",b="废墟内的危险远不止那些不安的亡灵。药剂师和像维克多·维尔这样险恶的人物在阴影中测试着新的瘟疫，而像“被遗弃者”这样扭曲的实验品则在自由游荡。像拉索马尔这样愤怒的灵魂和像男爵这样受诅咒的侍从在坍塌的走廊中徘徊，陷入无尽的折磨，并攻击任何闯入他们领地的生者或亡灵。"},{t="皇家卫队的幽灵",b="上层废墟中最令人心酸的危险莫过于这座城市守卫者的幽灵残影，他们以一位洛丹伦队长幽魂的形象出现。这些幻影依然固执地坚守着他们破碎的誓言，将任何接近王座的人都视为入侵者。让这位队长和他的士兵安息，为这自从首都陷落之日起就从未中断的守望带来了一丝苦涩的终结。"}},faq={{q="洛丹伦废墟地下城位于何处？",a="该地下城位于提瑞斯法林地王城的地表，正位于通往被遗忘者首都幽暗城的入口网络上方。",al={"洛丹伦废墟位置","洛丹伦地下城在哪里","幽暗城地下城入口"}},{q="为什么部落和联盟都对这个地方感兴趣？",a="对于联盟来说，进入洛丹伦是一场神圣的朝圣之旅，旨在找回失落的家族传家宝、收集皇家徽章，并让战死的先祖获得最终的平静。对于部落，尤其是被遗忘者而言，清理上层废墟对于确保幽暗城的周边安全以及获取用于皇家药剂师协会新瘟疫的实验样本至关重要。",al={"为什么要去洛丹伦废墟","联盟洛丹伦任务","部落洛丹伦任务"}},{q="维克多·维尔是谁？",a="维克多·维尔是利用废墟无法律状态作恶的邪恶人物之一，他进行着污秽的实验，并导致了此处滋生腐败，使得上层王城至今仍被扭曲的憎恶所侵扰。",al={"维克多·维尔背景","维克多·维尔是谁"}},{q="在废墟中遇到的“被遗弃者”是什么？",a="“被遗弃者”是一个残留在废墟中的怪诞亡灵怪物。正如天灾军团征服期间及其后创造的许多缝合恐怖生物一样，它在废弃的房间里漫无目的地游荡，攻击它遇到的任何东西。",al={"被遗弃者首领","被遗弃者是谁"}},{q="击败洛丹伦队长对故事意味着什么？",a="击败幽灵状态的洛丹伦队长，将一位高级皇家卫士从永恒而疯狂的职责中解脱了出来。自从天灾军团最初的大屠杀以来，他因荣誉的束缚，多年来一直守卫着一个已毁灭的王国，抵御所有接近的人。让这位队长安息打破了痛苦的幻影侍奉循环，并使他们的染血的徽记得以被回收。",al={"击败洛丹伦队长","洛丹伦队长意义","队长死后会发生什么"}},{q="洛丹伦废墟与幽暗城是分开的吗？",a="是的。虽然被遗忘者在下方的幽暗城洞穴中安家，但地表废墟是一个充满不安的幽灵、凶猛的捕食者和实验威胁的活跃战斗区域，被遗忘者尚未完全肃清此处。",al={"幽暗城在这个地下城里吗","废墟与幽暗城的区别"}}},fx={["1b77984b"]={q="洛丹伦废墟是什么地方？",a="你正站在洛丹伦首都的残垣断壁之间。这里曾是人类文明的明珠，也是洛丹伦王国的核心。第三次战争期间，阿尔萨斯王子背叛了王国，在上方的王座大厅杀害了自己的父亲泰瑞纳斯国王，并将亡灵天灾释放到街道上。如今，破碎的拱门和被烧焦的高塔矗立于地下幽暗城之上，成为这个覆灭王国令人痛心的纪念。",al={"洛丹伦废墟是什么","洛丹伦废墟的背景故事","这里曾经是什么地方"}},["0a975308"]={q="大家总在说的瘟疫是什么？",a="他们说的是亡灵瘟疫，这是一种由巫妖王及其亡灵法师研制的可怕生化魔法传染病。诅咒神教将受感染的谷物散布到洛丹伦各地，食用者会在数小时内死亡，尸体随即复活，成为天灾军团听命驱使、腐烂不堪的奴仆。",al={"什么是亡灵瘟疫","提到的是什么瘟疫","洛丹伦瘟疫"}},["290f94a8"]={q="最初的瘟疫是谁制造的？",a="最初的瘟疫由燃烧军团的恐惧魔王设计，并由巫妖王耐奥祖加以完善。当时他被囚禁在诺森德冰封王座之巅。为了将瘟疫散布到洛丹伦，他招揽了叛离达拉然的大法师克尔苏加德。克尔苏加德创立了诅咒神教，并污染了粮食储备。",al={"谁创造了亡灵瘟疫","最初瘟疫的制造者","谁制造了瘟疫"}},["89f62638"]={q="希尔瓦娜斯正在制造一种新瘟疫吗？",a="是的。希尔瓦娜斯女王已命令皇家药剂师协会研制一种“新瘟疫”。她的目标是打造一种足以消灭天灾军团和所有生者的生化武器，以确保被遗忘者得以存续，并向阿尔萨斯复仇。他们此刻正在下方的炼金房秘密进行测试。",al={"希尔瓦娜斯在制造瘟疫吗","被遗忘者的新瘟疫","幽暗城的新瘟疫"}},dcb566d2={q="巫妖王是谁？他想要什么？",a="巫妖王是天灾军团的最高统治者，由兽人萨满耐奥祖饱受折磨的灵魂制成，并被封存在冰封王座之巅的冰块中。他原本想为燃烧军团削弱艾泽拉斯，但他也怀有自己可怕的野心：消灭所有凡人，并以绝对的精神控制建立一个永恒统一的亡灵帝国，取代所有生者。",al={"巫妖王是谁","巫妖王想要什么","巫妖王的动机"}},["3a9893a7"]={q="巫妖王现在在哪里？",a="他在遥远冰封大陆诺森德的冰冠冰川之巅，坐镇冰封王座。伊利丹的袭击撼动了他的冰牢后，巫妖王召回阿尔萨斯前往诺森德，让两人的灵魂合而为一，以保全自己的力量。如今他远离了洛丹伦的残破王国。",al={"巫妖王在哪里","巫妖王的位置","冰封王座在哪里"}},["0138c577"]={q="他仍然控制着被遗忘者吗？",a="不。伊利丹施法击裂冰封王座后，巫妖王的心灵控制开始瓦解。希尔瓦娜斯和许多其他亡灵恢复了自由意志，脱离了他的集体意识。尽管他仍想重新控制他们，被遗忘者如今强烈抵抗他的低语，奋力维护自己的自主权。",al={"巫妖王控制被遗忘者吗","巫妖王能命令被遗忘者吗","被遗忘者的自由意志"}},["6a523c60"]={q="血色十字军是什么组织？他们为什么憎恨亡灵？",a="血色十字军是一个由洛丹伦骑士和白银之手的残部组成的人类宗教狂热组织。瘟疫摧毁了他们的家园，他们因此深受创伤，陷入偏执。在他们眼中，所有亡灵无一例外都是怪物；任何与亡灵来往的生者也被视为遭到污染，必须处决。",al={"血色十字军是什么组织","血色十字军为何憎恨亡灵","血色十字军的背景"}},b59db3a3={q="他们和银色黎明是同一个组织吗？",a="不是。他们有着共同的根源，却是势不两立的对手。两者都源自白银之手骑士团，但血色十字军陷入盲目的狂热和排外主义后，温和派圣骑士脱离该组织，建立了银色黎明。银色黎明欢迎所有种族加入，专注于抵御天灾军团，而非不加区分地清除一切。",al={"血色十字军与银色黎明","血色十字军和银色黎明是同一组织吗","血色十字军与银色黎明的区别"}},ca88b6f6={q="他们也会攻击生者玩家吗？",a="会。血色十字军认为，凡是不穿猩红色战袍的人，都在暗中携带瘟疫或与亡灵勾结。无论你是兽人、牛头人、暗夜精灵，还是来自暴风城的人类士兵，他们的狂热分子都会认定你是腐化的传播者，并一见面就发动攻击。",al={"血色十字军会攻击联盟吗","血色十字军会攻击生者吗","血色十字军敌视生者吗"}},["861c7602"]={q="皇家药剂师协会在下面做什么？",a="这个由被遗忘者炼金师和前法师组成的邪恶行会驻扎在幽暗城的炼金房，在希尔瓦娜斯女王的命令下不知疲倦地工作。他们的首要任务是研制一种灾难性的“新瘟疫”，以消灭天灾军团和生者种族。他们不择手段地进行实验，以确保被遗忘者称霸。",al={"皇家药剂师协会做什么","皇家药剂师协会的目的","幽暗城的药剂师"}},["3c47ce18"]={q="他们在拿人做实验吗？",a="在炼金房深处，被俘的血色十字军战士、天灾食尸鬼和各种野兽被关在铁笼里。药剂师给这些囚犯使用痛苦的混合药剂和强效瘟疫菌株，评估肉体腐烂的速度，以及传染病对活体和死灵生理的影响。",al={"药剂师在拿人做实验吗","皇家药剂师协会的实验","幽暗城的药剂师在折磨人吗"}},f7d23701={q="阿尔萨斯还活着吗？我有机会和他战斗吗？",a="从凡人的意义上说，阿尔萨斯并未死去，但他已彻底堕落，成为天灾军团的死亡骑士勇士。他远在海的另一端、诺森德深处，洛丹伦的任何人都无法触及他。你现在要面对的是仍在此地肆虐的威胁：当地的天灾军团指挥官、血色十字军，以及侵扰这些废墟的狂暴野兽。",al={"我能和阿尔萨斯战斗吗","阿尔萨斯还活着吗","我们会遇到阿尔萨斯吗"}},["9fc2648e"]={q="他现在是巫妖王吗？",a="北方传来的低语声称，阿尔萨斯登上了冰冠尖塔，前去从伊利丹的围攻中解救巫妖王。他击碎冰块，戴上统御之盔，并与耐奥祖的灵魂合而为一。对于世人而言，诺森德的确切情况仍笼罩在冰冷的谜团中，但他的黑暗气息依然笼罩着所有亡灵。",al={"阿尔萨斯是巫妖王吗","阿尔萨斯成为巫妖王了吗","阿尔萨斯和巫妖王的身份"}},["89a21402"]={q="我是怎么来到洛丹伦废墟的？",a="你穿过了提瑞斯法林地中这座沦陷都城摇摇欲坠的外门，来到幽暗城升降梯上方。无论你是响应军事召集、追查有关王国遗骸中潜伏着失控恐怖的传闻，还是穿越敌对区域、试图寻回往昔的神圣遗物，你的旅程都将你带进了戒备森严、争夺不断的庭院。天灾军团的阴影和古老人类的亡魂仍在此徘徊。",al={"我是怎么来到这里的","我为什么在洛丹伦废墟","我是怎么抵达这里的"}},bb4abd7f={q="我在洛丹伦废墟应该做什么？",a="你来到这里，是为了清除被遗忘者首都上方地表废墟中滋生的恐怖。对部落而言，这意味着搜剿脱离控制的天灾野兽、寻回遗失的徽记，并为皇家药剂师协会测试致命药剂。对联盟而言，这是一场秘密突袭，目的是净化祖先的土地、取回洛丹伦徽记等神圣遗物，并抚慰那些至今不得安息、四处游荡且饱受折磨的亡魂。",al={"我在这里做什么","我在这里的任务是什么","我在废墟里该做什么","我在这里的目标是什么"}},eb89374f={q="这里被毁之前住着谁？",a="这座城市曾是人类北方最强大王国的家园，由米奈希尔王朝统治。贵族、圣光牧师、士兵和数十万平民曾行走在这些铺砌的街道上。可悲的是，许多昔日市民并未真正离去：他们死于瘟疫后又被复活，尸体如今组成了徘徊在瘟疫之地的无脑天灾，也组成了如今居住在下方洞窟中的被遗忘者。",al={"这里以前住着谁","洛丹伦原住民","谁最早住在这里"}},["6e6195fd"]={q="这里为什么全都破败焦黑了？",a="阿尔萨斯王子携霜之哀伤归来后，杀死了泰瑞纳斯国王，并将这座城市交给了天灾军团。亡灵怪物横冲直撞地穿过大街小巷，焚烧建筑，屠杀所有试图抵抗的人。后来，在亡灵之间的内战期间，希尔瓦娜斯·风行者和她的被遗忘者在这些庭院中与恐惧魔王及残存的天灾军团展开战斗，将城市宏伟建筑的残骸也毁去了。",al={"洛丹伦为何被毁","洛丹伦是怎么被烧毁的","这里为何沦为废墟"}},dd470a5c={q="是谁毁灭了洛丹伦？",a="在巫妖王腐化心智的低语影响下，王国被自己的王储阿尔萨斯·米奈希尔从内部摧毁。他奉命阻止诅咒神教及其亡灵瘟疫，却变得冷酷无情，在冰封的北方拿起受诅咒的符文剑霜之哀伤，并交出了自己的灵魂。他化为死亡骑士回到故乡，杀死父亲，将这座城市送入天灾军团的魔爪。",al={"是谁毁了洛丹伦","谁摧毁了洛丹伦","洛丹伦的毁灭者"}},f5a9164f={q="阿尔萨斯现在在哪里？",a="多年前，阿尔萨斯离开了洛丹伦这片废墟遍布的大陆。当恶魔猎手伊利丹·怒风威胁到巫妖王时，他横渡无尽之海，返回诺森德。他一路杀上冰封王座所在的冰冷尖塔，此后便消失在冰封荒原的众人视线中，只留下一个四分五裂的王国，以及彼此对立的亡灵与幸存者势力。",al={"阿尔萨斯去了哪里","阿尔萨斯王子在哪里","阿尔萨斯的位置"}},["2fe0baef"]={q="有人逃出了这座城市吗？",a="少数幸运者逃过了屠杀。在王国彻底覆灭之前，女巫吉安娜·普罗德摩尔听从了一位神秘先知的警告，带领数千名人类难民渡海前往卡利姆多，并在那里建立了塞拉摩港。还有人向南逃往暴风王国，或拿起圣洁的武器奋起反抗，组成了狂热的血色十字军和警戒森严的银色黎明。",al={"洛丹伦的居民幸存了吗","有人在洛丹伦覆灭后幸存吗","洛丹伦的幸存者"}},["9cf7434f"]={q="为什么废墟下面有一座亡灵之城？",a="巫妖王的力量衰退时，希尔瓦娜斯·风行者摆脱了对众多亡灵的精神控制。他们自称被遗忘者，推翻了控制王城的恶魔恐惧魔王。上方的废墟暴露在敌人的视线之下，还不断遭受血色十字军的攻击，因此希尔瓦娜斯决定将庞大的地下墓穴和下水道改造成戒备森严的堡垒。",al={"幽暗城为何存在","幽暗城为何建在洛丹伦地下","废墟下的亡灵之城"}},["55ddf3da"]={q="幽暗城是谁建造的？",a="幽暗城的根基始于王城之下，由洛丹伦的人类修建了皇家地牢、下水道和深层墓穴。第三次战争期间，阿尔萨斯和天灾军团开始扩建这些地下通道，打造一座意图成为天灾势力中心的复杂网络。从恐惧魔王瓦里玛萨斯手中夺回控制权后，希尔瓦娜斯和被遗忘者继续开凿，最终将幽暗城建成他们永久的首都。",al={"谁建造了幽暗城","幽暗城的建造","谁挖掘了幽暗城"}},c0ee4f6f={q="幽暗城一直都在地下吗？",a="现代幽暗城并非一直如此庞大。在泰瑞纳斯国王统治时期，地下区域只有城堡地牢、引水渠、下水道和家族墓穴。王国覆灭后，天灾憎恶和被遗忘者劳工才挖掘出如今所见的巨大环形区域和各区，将功能性隧道改造成庞大的亡者地下堡垒。",al={"幽暗城一直都在那里吗","幽暗城以前就存在吗","旧幽暗城"}},dc41e367={q="这里由谁掌权？",a="女妖之王希尔瓦娜斯·风行者统领着这些废墟及其下方的幽暗城。她曾是银月城的游侠将军，被阿尔萨斯杀死后又被复活为复仇女妖，最终夺回了自己的肉身。凭借坚强的意志和狡诈的手段，她解放了亡灵同胞，建立被遗忘者，并在皇家区的王座上以冷酷的决心领导他们。",al={"谁统治洛丹伦废墟","幽暗城的首领","谁控制这里"}},["3d3094f9"]={q="希尔瓦娜斯算是女王吗？",a="她的族人尊称她为女妖之王和被遗忘者女士，但她并非洛丹伦的世袭王族。这个头衔映照了她被阿尔萨斯王子杀害的悲惨命运。阿尔萨斯将她的灵魂从躯体中撕出，使她成为哀嚎的女妖。这个头衔虽带有王权的意味，她的权威却源于解放、求生以及对军队的绝对掌控。",al={"希尔瓦娜斯是女王吗","女妖之王头衔","希尔瓦娜斯的头衔是什么"}},ac534dbb={q="希尔瓦娜斯听从萨尔的命令吗？",a="名义上，希尔瓦娜斯承认大酋长萨尔是部落的最高统帅，也同意与部落结成互利同盟。实际上，女妖之王对被遗忘者及其北方领地保持完全的自主权。她尊重萨尔的意见，被遗忘者的使节也出现在奥格瑞玛，但希尔瓦娜斯女士首先考虑的始终是自身的生存和族人的抱负。",al={"希尔瓦娜斯与萨尔的关系","希尔瓦娜斯服从萨尔吗","希尔瓦娜斯受萨尔管辖吗"}},["6b51523d"]={q="楼梯上方那个王座大厅发生过什么？",a="王座大厅见证了那场导致王国覆灭的灾难性背叛。阿尔萨斯王子刚从诺森德归来，穿过夹道欢迎的市民和响彻的钟声，走进了这个大厅。他的父亲泰瑞纳斯国王从王座上起身迎接时，阿尔萨斯拔出霜之哀伤，宣称自己将继承父亲的王位，随后将受诅咒的符文剑刺入老国王的心脏。",al={"王座大厅发生了什么","洛丹伦王座大厅的故事","王座大厅的历史"}},["6e83c082"]={q="泰瑞纳斯是在那个地方被杀的吗？",a="是的。站在破碎的高台前，你脚下正是泰瑞纳斯·米奈希尔二世国王咽下最后一口气的石板。石地板上仍能看见一处淡淡的黑色污渍，据说那是老国王遇害时渗入石墙的血迹。直到如今，大厅里仍隐约回荡着幽灵的低语和钟声。",al={"泰瑞纳斯在哪里遇害","那是泰瑞纳斯的血吗","泰瑞纳斯国王遇害地点"}},ea8d978d={q="泰瑞纳斯的王冠后来怎么样了？",a="阿尔萨斯在王座大厅杀死泰瑞纳斯时，泰瑞纳斯的金色王冠掉落在地。王冠坠地，标志着他的统治终结，也象征着降临洛丹伦的灾难。",al={"王冠为何掉在地上","废墟里的泰瑞纳斯王冠","泰瑞纳斯王冠上的血"}},bb044bc8={q="被遗忘者真的是部落的一员吗？",a="是的，不过这主要是一份互相求生的盟约。被血色十字军、敌对的人类和残存的天灾军团包围后，被遗忘者派遣使者渡海寻求盟友。部落需要在东部王国立足，以抗衡联盟，于是同意接纳他们，给予被遗忘者急需的军事支持和国际地位。",al={"被遗忘者与部落的盟约","亡灵属于部落吗","被遗忘者为何加入部落"}},["50000697"]={q="萨尔为什么接纳亡灵加入部落？",a="萨尔主要是在大德鲁伊哈缪尔·符文图腾和牛头人的斡旋下受到影响。他们认为被遗忘者是悲惨的受害者，终有一天或许能得到救赎，或找到治愈自身苦难的方法。此外，萨尔也意识到，在东部王国建立稳固据点十分必要，才能阻止联盟毫无阻碍地控制北方大陆。",al={"萨尔为何允许亡灵加入","萨尔接纳被遗忘者的原因","部落为何接纳被遗忘者"}},["9af0f393"]={q="兽人和牛头人信任他们吗？",a="并非完全信任。牛头人对他们深感怜悯，希望治愈他们的状况；许多兽人则对黑暗魔法、通灵术以及幽暗城阴森的气息深感疑虑。萨尔密切关注希尔瓦娜斯的行动，驻守的使节也对皇家药剂师协会实验室里的秘密活动保持警惕。",al={"兽人信任被遗忘者吗","牛头人信任被遗忘者吗","部落信任亡灵吗"}},["849f698a"]={q="我站在这里安全吗？",a="这完全取决于你的阵营。如果你为部落而战，被遗忘者和他们的憎恶会把你视为盟友，不过上方的阴影中仍藏着游荡的生物和残留的灵魂。如果你追随联盟的旗帜，那你就身处敌境深处；被遗忘者哨兵和恐惧卫士一旦发现你，就会将你击倒。",al={"洛丹伦废墟安全吗","我在这里安全吗","站在洛丹伦有危险吗"}},aac358a1={q="守卫会攻击我吗？",a="驻守在废墟周围的被遗忘者死亡卫士和皇家憎恶会无视或保护部落旅人，但会对联盟勇士极其敌视。此外，上方废墟中偏僻的通道和地牢区域还潜伏着敌对的叛徒和怪物；无论属于哪个阵营，任何人只要经过它们面前都会遭到攻击。",al={"幽暗城守卫会攻击吗","废墟守卫有敌意吗","守卫会攻击我吗"}},e9ec8c01={q="附近还有天灾军团吗？",a="有。希尔瓦娜斯虽然将天灾军团的大部分势力逐出了王城，但西瘟疫之地边境之外仍盘踞着大量天灾军团。即使在这些废墟幽暗的角落和被遗忘的地下层里，也仍有无脑亡灵和天灾残余徘徊，等待撕碎任何误入其地盘的活人。",al={"洛丹伦废墟里的天灾军团","幽暗城附近有天灾军团吗","附近还有天灾军团吗"}}},fp="18,278,27.503.0,22.413.0,25.302.1,48.174.0,61.277.0,23.179.0,49.228.0,61.384.1,54.227.0"}
P.entries["zone:scarlet"] = {n="血色修道院",s="血色修道院坐落在提瑞斯法林地东北部的山丘之上，曾是圣光教会一处宁静的避难所和学术中心。洛丹伦陷落后，它被血色十字军夺取并进行了重兵加固，成为他们在西部的主要前线基地。如今，这里已成为一座四分五裂的庞大要塞，狂热的信徒们在此训练、拷问俘虏，并对外来者发起毫不妥协的战争。",h="血色修道院坐落在提瑞斯法林地东北部的山丘之上，曾是圣光教会一处宁静的避难所和学术中心。洛丹伦陷落后，它被血色十字军夺取并进行了重兵加固，成为他们在西部的主要前线基地。如今，这里已成为一座四分五裂的庞大要塞，狂热的信徒们在...",kw={"军械库","大教堂","杜安","墓地区","赫洛德","图书馆","莫格莱尼","血色十字军","血色修道院","提瑞斯法林地","怀特迈恩"},ang={["class:Mage"]="图书馆收藏着珍稀的历史和神学典籍，由十字军首席奥术师奥法师杜安把守。",["class:Paladin"]="这座修道院曾是洛丹伦祭司的神圣驻地，它沦为猩红狂热的渊薮，也成了信仰如何扭曲为疯狂的一则悲剧警示。",["class:Priest"]="它最初是圣光教会的驻地，其宏伟的礼拜堂展示了即便是在被仇恨和复仇扭曲的凡人手中，圣光之力依然可以被挥舞。",["race:Undead"]="血色修道院坐落在提瑞斯法林地的边缘，对被遗忘者构成了生存威胁，他们派遣间谍潜入丧钟镇，并在地牢中拷问被捕的亡灵。"},sec={{t="堕落的圣所",b="在第三次战争之前，这座修道院曾是洛丹伦祭司们引以为傲的驻地，也是学习和启迪的中心。天灾军团的蹂躏过后，幸存的十字军清理了大厅内残存的亡灵和蜘蛛，将原本宁静的档案馆和庭院改造成了一座戒备森严的要塞。在妄想与悲痛的驱使下，血色十字军开始将所有的外来者——无论是生者还是亡灵，人类还是其他种族——都视为瘟疫的携带者，必须用火焰将他们净化。"},{t="四个侧厅",b="穿过修道院的Grand Vestibule，便是四个迥然不同的区域。墓地区是一个不洁的露天平台，堕落的十字军在那里转化为亡灵憎恶，拷问者们在此从囚犯口中逼供。图书馆收藏着珍贵的神学文献和历史典籍，由叛逃法师奥法师杜安和他的猎犬看守。军械库是训练场，赫洛德等血色十字军武器大师在这里将狂热的新兵操练成披甲战士。最深处则是大教堂，这座要塞的宏伟心脏，十字军的领导层正是在此指挥他们横跨凋零北地的圣战。"},{t="大检察官的陨落",b="大教堂的The Inner Sanctum由血色十字军指挥官莫格莱尼和修道院真正的主宰——大检察官怀特迈恩所统领。击败怀特迈恩将对十字军在提瑞斯法林地的指挥中枢造成沉重打击。她引导盲目圣光并复活堕落勇士的能力，使得该要塞在信徒眼中显得坚不可摧。击杀她将粉碎支撑修道院狂热信仰的神圣光环，揭露十字军领袖身为凡人的真相，并严重削弱他们针对被遗忘者及周边地区的攻势。"}},faq={{q="为什么血色十字军会对身为生者的联盟冒险者怀有敌意？",a="十字军已经陷入了极端的疯狂和偏执。在他们眼中，任何没有穿上那件猩红战袍的人，都是天灾瘟疫的潜在携带者。他们不再区分敌友，将所有外来者视为受污染的存在，必须在他们传播腐化之前将其净化。",al={"为什么血色十字军攻击人类","血色十字军对联盟的敌意","为什么他们会发疯"}},{q="击败大检察官怀特迈恩后会发生什么？",a="击败大检察官怀特迈恩等于斩首了血色十字军在西部的军事领导层。作为修道院的精神领袖，她那奇迹般的复活能力维系了部队的士气，并让指挥官莫格莱尼能与她并肩作战。她的死亡消除了十字军在提瑞斯法林地最具威胁的牧师，使要塞陷入混乱，并严重降低了他们对周边地区构成的威胁。",al={"击杀怀特迈恩的意义","怀特迈恩的结局","大教堂的结局"}},{q="血色十字军钥匙是什么，在哪里可以找到？",a="血色十字军钥匙存放在修道院图书馆深处，位于奥法师杜安私人书房后的保险箱内。持有这把钥匙是开启军械库和大教堂区域外门的必要条件。",al={"血色十字军钥匙在哪里","如何打开军械库和大教堂的门","修道院钥匙"}},{q="奥法师杜安为什么会在血色修道院？",a="奥法师杜安是一位强大的血色十字军人类法师，他坚信奥术魔法是清除洛丹伦天灾瘟疫的必要武器。他负责看管修道院庞大的图书馆，并在书房中守护着血色十字军钥匙。",al={"奥法师杜安是谁","杜安背景故事","图书馆里的法师"}},{q="亚历山德罗斯·莫格莱尼是谁，他与这里有什么联系？",a="亚历山德罗斯·莫格莱尼即著名的灰烬使者，曾是白银之手骑士团的传奇圣骑士，也是与大将军阿比迪斯和大检察官伊森利恩一同创建血色十字军的创始人之一。他的儿子雷诺如今正与大检察官怀特迈恩一同统领大教堂。",al={"莫格莱尼与修道院的历史","灰烬使者与修道院","雷诺·莫格莱尼的父亲"}},{q="墓地区与其他修道院区域有什么不同？",a="当修道院的其他部分还维持着表面上那纯洁虔诚的假象时，墓地区却是十字军狂热信仰从内部腐烂的地方。这里设有审讯员韦沙斯主持的残酷刑讯室，而被遗弃的墓穴和躁动不安的死者则被像血法师萨尔诺斯这样的堕落施法者所收割或操纵。",al={"为什么墓地区有亡灵","萨尔诺斯背景故事","审讯员韦沙斯"}}},fx={["1402011d"]={q="我为什么要攻击一座满是圣骑士的教堂？",a="尽管修道院的指挥官身着圣职者的装束、运用圣光，他们却已沦为暴力极端分子。无论你是响应虔诚的莱雷恩的号召，净化这个组织中堕落的领导层，还是代表幽暗城的瓦里玛萨斯出手，消除他家门口咄咄逼人的邻居，你的目的都是瓦解他们的军事力量。",al={"为什么要进攻血色修道院","为什么要在这里杀圣骑士","攻打血色修道院的理由"}},["18e8d4ac"]={q="血色十字军真的是邪恶的吗？",a="他们起初怀有崇高的目标——将亡灵天灾从洛丹伦彻底清除。然而，创伤与偏执彻底扭曲了他们的宗旨。如今，他们折磨无辜的旅人，把所有外来者都视为染疫者，还屠杀任何不佩戴他们臂章的人。为了所谓的净化，他们已彻底丧失了道德理智。",al={"血色十字军是邪恶的吗","他们是坏人吗","十字军是邪恶的吗"}},fe2faadd={q="联盟支持血色十字军吗？",a="官方并不支持。暴风城的一些人或许同情洛丹伦幸存的圣职战士，但血色十字军不分青红皂白的敌意已经断绝了双方的正式关系。虔诚的莱雷恩等冒险者和联盟人士认为，他们如今的指挥官是一群疯狂的狂热分子，他们的暴行玷污了圣光的荣誉。",al={"联盟支持血色十字军吗","血色十字军属于联盟吗","联盟与血色十字军的关系"}},fbd0569e={q="谁在统领血色修道院？",a="这座要塞的军事驻军听命于血色十字军指挥官雷诺·莫格莱尼，他麾下有一支忠诚的战士部队。然而，这座建筑群真正的精神与教义领袖是大检察官怀特迈恩。她是一位强大的女祭司，能够让阵亡者复生，为她而战。",al={"谁领导血色修道院","谁在管理修道院","血色修道院的领袖"}},ae07147f={q="修道院的首领在大教堂里面吗？",a="是的。血色十字军指挥官莫格莱尼和大检察官怀特迈恩都住在大教堂区域深处的十字军礼拜堂，身边有一支狂热的卫队守护。",al={"怀特迈恩在哪里","怀特迈恩在大教堂吗","大教堂首领的位置"}},["11700a05"]={q="血色十字军为什么如此憎恨被遗忘者？",a="在血色十字军看来，所有亡灵都是瘟疫催生的怪物，而那场瘟疫摧毁了他们的家人与故土。他们不区分天灾那些没有心智的爪牙和占据主城的自由意志被遗忘者；在他们眼中，两者都是腐朽的篡夺者，必须用圣火彻底净化。",al={"血色十字军与被遗忘者","血色十字军为何憎恨亡灵","血色十字军与被遗忘者的仇怨"}},["38169c8a"]={q="血色十字军和被遗忘者曾经是同一群人吗？",a="是的。第三次战争之前，大多数血色十字军成员和被遗忘者都曾是洛丹伦王国的居民、士兵或祭司。瘟疫席卷而来时，死后复生的人变成了亡灵，而饱受创伤的生者则逃离或团结起来，昔日的邻居与亲人就此变成了不共戴天的仇敌。",al={"血色十字军和被遗忘者以前认识吗","他们以前都是洛丹伦居民吗","洛丹伦的幸存势力"}},["80c0e472"]={q="血色十字军从何而来？",a="血色十字军由白银之手骑士团的幸存者和洛丹伦士兵组成，领导者是大领主亚历山德罗斯·莫格莱尼和将军阿班迪斯。王国覆灭令幸存的领袖们不堪重负，最终分道扬镳：主张毫不妥协、坚持不懈地狂热行动者建立了血色十字军，而温和派则分离出去，创立了银色黎明。",al={"血色十字军的起源","血色十字军是如何建立的","谁创立了血色十字军"}},c4a70323={q="白银之手是什么？",a="白银之手骑士团是一个传奇的圣骑士组织，由大主教阿隆苏斯·法奥和光明使者乌瑟尔在第二次战争期间创立。在天灾入侵并由阿尔萨斯王子击溃他们之前，他们一直是联盟和洛丹伦的先锋勇士。",al={"白银之手是什么","白银之手骑士团","白银之手圣骑士"}},d5472427={q="血色十字军为什么也杀活着的人类？",a="深重的偏执已经侵蚀了血色十字军对现实的判断。他们认为，任何外来者都可能暗中携带亡灵瘟疫。凡是不穿他们的制服、不服从他们严苛管束的人，都会被指为堕落者，遭受折磨或处死。",al={"为什么要攻击活着的人类","血色十字军杀害人类","他们为什么杀害同族"}},b6568619={q="血色十字军会威胁到暴风城吗？",a="如果指的是地理上的征服，他们并没有直接威胁，因为他们的行动范围集中在洛丹伦北部的废墟一带。然而，他们已经疯狂到会杀害任何旅人，因此，前往其领地附近的联盟居民、使节和冒险者都会受到他们的直接威胁。",al={"血色十字军会威胁联盟吗","血色十字军与暴风城","血色十字军的威胁"}},["6889160e"]={q="为什么人人都要我去血色修道院？",a="双方势力都在提瑞斯法林地有切身利益。被遗忘者无法容忍首都门外驻扎着一座全副武装的狂热者要塞；联盟人士则希望取回圣典、平息危险的叛乱者，并让已经疯狂的领导层受到惩罚。",al={"为什么我被派去血色修道院","谁想除掉修道院","血色修道院任务缘由"}},["0c6b4a7d"]={q="血色修道院图书馆有什么用途？",a="图书馆包括雅典图书馆和珍宝陈列室，收藏着洛丹伦的古代典籍、历史记录和奥术知识。这里既是知识档案馆，也是隐秘的研究圣地，由奥法师杜安主持。",al={"图书馆区域的用途","他们在图书馆里做什么","血色修道院的雅典图书馆"}},["29dc31ee"]={q="军械库和大教堂区域分别有什么用途？",a="军械库是血色十字军的军事核心，设有训练场、兵营和武器库，由血色勇士赫洛德监管。大教堂则是最高圣所和指挥所，莫格莱尼在此训练精锐部队，怀特迈恩则在此布道并统筹血色十字军在提瑞斯法地区的行动。",al={"军械库和大教堂有什么用途","血色修道院军械库的用途","血色修道院大教堂的用途"}},f04a1b7f={q="我是怎么来到血色修道院的？",a="你前往提瑞斯法林地最东北部的丘陵，穿过迷雾笼罩的林地，抵达血色十字军的要塞。无论你是奉部落之命从幽暗城出发，前来铲除家门口的狂热势力，还是响应心灰意冷的十字军成员的号召，从希尔斯布莱德丘陵向北进发，准备清除修道院中狂热的领导层，这条路最终都会把你带到这座戒备森严的建筑群前。",al={"我是怎么到这里的","我是怎么来到血色修道院的","我为什么来这里"}},be779d1d={q="我在血色修道院应该做什么？",a="你要攻入血色十字军的四个区域，瓦解他们对这片地区的控制。具体任务取决于派你前来的人：你可能要追捕血色十字军指挥官莫格莱尼和大检察官怀特迈恩等堕落领袖，在图书馆中寻找失落的典籍与知识，为皇家药剂师协会收集狂热之心，或是取回圣物并铲除那些将所有组织外的人都视作染疫亡灵的堕落领袖。",al={"我在这里做什么","我为什么在这里","我在这里的任务是什么"}},["3ffc247b"]={q="血色修道院是什么地方？",a="血色修道院坐落于提瑞斯法林地东北部，是一座戒备森严的圣所，也是血色十字军在该地区的主要据点。这里曾是一片宁静的大教堂建筑群，致力于传播圣光、研习教义；如今却已被改造成武装森严的总部、训练场，以及血色十字军狂热发动反亡灵战役的思想堡垒。",al={"血色修道院是什么地方","血色修道院的背景","关于血色修道院"}},fd7417a7={q="血色修道院一直都属于他们吗？",a="不是。洛丹伦沦陷前，这里只被称作旧修道院。它最初由高贵的戈德温家族资助，是一座大主教驻地和修道院学校，由大主教阿隆索斯·法奥尔主持。第三次战争造成毁灭性打击后，幸存的圣骑士从残存的天灾军团手中夺回了修道院，并将其更名为血色修道院。",al={"血色修道院一直属于血色十字军吗","血色修道院的历史","血色修道院以前属于谁"}},e7b85043={q="血色修道院是谁建造的？",a="旧修道院是在高贵的戈德温家族资助下，作为圣光教会的圣所建造的。数代档案管理员，例如布莱克·戈德温，负责整理这里的图书馆和档案。王国覆灭前，它一直是洛丹伦牧师团体和圣骑士训练的重要中心，令洛丹伦引以为傲。",al={"谁建造了修道院","修道院的起源"}},["0c05301c"]={q="血色十字军是什么组织？",a="血色十字军是一支由白银之手骑士团残部组成的人类狂热军事组织，麾下有圣战士和牧师。洛丹伦遭受天灾瘟疫后，他们沉浸在悲痛与仇恨之中，一心要消灭亡灵，并以极其残酷和偏执的手段贯彻使命。",al={"血色十字军是什么组织","血色十字军是什么","血色十字军的背景"}},b0ef06b1={q="血色十字军是人类吗？",a="是的，他们的成员全都是来自沦陷王国洛丹伦的人类。无论其他种族是否属于联盟，或过去与他们有何渊源，他们都对所有非人类种族抱有强烈的排斥，认为外来者不配与他们为伍，或天生就受到了瘟疫污染。",al={"血色十字军只有人类吗","血色十字军的种族","血色十字军是人类吗"}}},fp="17,291,18.495.0,14.492.0,31.517.1,66.284.0,55.301.1,46.170.0,46.213.0,57.280.1,74.218.0"}
P.entries["zone:searinggorge"] = {n="灼热峡谷",s="灼热峡谷是一道位于卡兹莫丹南部，北接洛克莫丹，南临黑石山的焦灼荒凉的峡谷。它曾经是赤脊山脉一片郁郁葱葱的广袤地带，但在两百多年前，随着炎魔拉格纳罗斯被召唤降临，这片土地化为焦土。如今，黑铁矮人在此大肆开采，他们在“大熔炉”中有着规模庞大的奴隶矿坑，而从黑铁矮人中分裂出来的瑟银兄弟会则在密切注视着他们。",h="灼热峡谷是一道位于卡兹莫丹南部，北接洛克莫丹，南临黑石山的焦灼荒凉的峡谷。它曾经是赤脊山脉一片郁郁葱葱的广袤地带，但在两百多年前，随着炎魔拉格纳罗斯被召唤降临，这片土地化为焦土。如今，黑铁矮人在此大肆开采，他们在“大熔炉...",kw={"黑石山","大熔炉","黑铁部族","拉格纳罗斯","灼热峡谷","熔渣之池","石坝小径","瑟银兄弟会","瑟银哨塔"},ang={["class:Rogue"]="拥有精湛开锁技巧的潜行者在这里是非常受欢迎的旅伴，因为他们可以绕过连接洛克莫丹和峡谷的石坝小径封闭大门。",["faction:Alliance"]="联盟将石坝小径的大门锁住，旨在将黑铁矮人与洛克莫丹的和平矮人定居点隔离开来，尽管勇敢的冒险者仍被授权突入峡谷。",["faction:Horde"]="以卡加斯作为集结地，部落开辟了一条陆路进入峡谷，以收集关于黑石山的情报并扰乱黑铁矮人在卡兹莫丹的行动。",["profession:Mining"]="火山景观和熔渣之池中的深度挖掘使灼热峡谷成为获取秘银矿脉、真银矿脉和令人垂涎的黑铁矿石的主要猎场之一。",["race:Dwarf"]="对于铁炉堡的矮人来说，灼热峡谷是对三锤之战以及黑铁矮人灾难性愚行的苦涩提醒，他们的挖掘行动如今威胁到了卡兹莫丹的南大门。"},sec={{t="焦灼的荒原",b="在三锤之战前，如今灼热峡谷所在的这片土地曾经是一片苍翠起伏的山区，与赤脊山脉相连。两百三十多年前，当索瑞森大帝在绝望中试图扭转败局，从世界深处召唤出拉格纳罗斯时，这片葱郁的景象便不复存在了。炎魔灾难性的降临撕裂了大地，升起了黑石山，将宏伟的黑铁矮人城市索瑞森化为一片焦烟废墟，并将北部的山谷烧成了布满灰烬、硫磺和火山玻璃的龟裂荒原。"},{t="大熔炉与熔渣之池",b="在失去了旧都之后，为了给战争机器补充原材料，黑铁矮人占据了这片荒凉的峡谷。峡谷中央便是大熔炉，这是一个向岩石深处延伸的巨型露天挖掘场。在其下方坐落着熔渣之池，那是一个残酷的地下采矿场。在这里，黑铁工头和笨重的战争傀儡驱赶着俘虏从事极其艰苦的奴隶劳动，在熔岩浪潮和游荡野兽的不断威胁下，将铁矿、秘银以及珍贵的黑铁矿石从燃烧之石中挖掘出来。"},{t="瑟银兄弟会与争夺中的道路",b="在俯瞰挖掘场的北侧峭壁上坐落着瑟银哨塔，这是瑟银兄弟会的防御前哨站。这些技艺精湛的工匠已经与黑石山中的同族决裂，为那些愿意破坏黑铁矮人行动或向他们提供稀有冶炼材料的旅行者提供中立的庇护所。前往峡谷的通道受到严格限制：联盟将通往洛克莫丹的石坝小径用沉重的铁门封锁起来，而附近的部落远征队则从卡加斯出发，在东部的荒野中开辟了一条狭窄的小径来侦察该地区。"}},faq={{q="为什么灼热峡谷会被烧毁并覆盖着灰烬？",a="两百三十多年前，在三锤之战期间，黑铁矮人的索瑞森大帝试图召唤一股超自然力量来避免战败。然而，他召唤出的是炎魔拉格纳罗斯。这次灾难性的爆发粉碎了赤脊山脉南部，创造了黑石山火山，并将周围的山谷焚烧殆尽，形成了灼热峡谷和燃烧平原。",al={"为什么这里是焦土","灼热峡谷背景故事","灼热峡谷的起源"}},{q="居住在瑟银哨塔的矮人是谁？",a="他们属于瑟银兄弟会，这是一个独立的黑铁矮人派系，他们断绝了与黑石山中帝国同族的关系。从他们位于瑟银哨塔的营地出发，他们以大师级铁匠和技师的身份，与任何协助他们对抗下方黑铁势力的旅行者交换知识和锻造秘籍。",al={"瑟银哨塔的矮人","谁是瑟银兄弟会","瑟银兄弟会背景"}},{q="大熔炉里发生了什么？",a="大熔炉是一个由黑铁矮人控制的大型露天挖掘场，包含地下深处的熔渣之池。黑铁工头和战争傀儡利用被俘的奴隶进行苦役，挖掘包括珍贵的黑铁矿石在内的各类矿石，以供应黑石山内部巨大的熔炉。",al={"什么是大熔炉","熔渣之池背景","黑铁矮人在挖什么"}},{q="如何从洛克莫丹进入灼热峡谷？",a="从洛克莫丹穿过石坝小径的通道被一扇由铁炉堡登山者守卫的沉重铁门封锁。旅行者必须通过索里奥斯馆长的正式任务获得通往灼热峡谷的大门钥匙，或是拥有精通开锁技能的潜行者开启机关，又或者完全绕过大门，走荒野中卡加斯南部的开放小径。",al={"石坝小径大门","如何打开灼热峡谷的大门","通往灼热峡谷的大门钥匙"}},{q="为什么部落对灼热峡谷感兴趣？",a="部落指挥官以荒野中附近的卡加斯要塞为基地，开辟了一条通往峡谷的山路，以便侦察黑铁矮人的部队动向，并确保通往具有巨大战略意义的黑石山的战术路线。",al={"部落为什么在这里","卡加斯与峡谷的连接","部落的存在"}},{q="灼热峡谷内有地下城或团队副本入口吗？",a="峡谷本身没有直接的副本入口，但南部的入口直通黑石山。那座山里坐落着黑石深渊、黑石塔，以及通往熔火之心的深邃通道。",al={"灼热峡谷的副本","灼热峡谷的地下城","熔火之心在哪里"}}},fp="13,249,20.456.0,29.498.0,39.549.0,51.376.0,44.359.0,33.260.0,50.303.0,45.225.0,62.207.0"}
P.entries["zone:shadowfang"] = {n="影牙城堡",s="影牙城堡耸立在焚木村上方的崎岖峭壁之上，这里是肯瑞托叛逃法师阿鲁高大法师阴暗的堡垒。这座堡垒曾是席瓦莱恩男爵的祖传领地，如今却充斥着野性的狼人，以及那些被屠杀的守卫者们痛苦的幽灵。对于穿越银松森林南部的冒险者来说，这座城堡是这个地区被野兽天灾所侵蚀的黑暗中心。",h="影牙城堡耸立在焚木村上方的崎岖峭壁之上，这里是肯瑞托叛逃法师阿鲁高大法师阴暗的堡垒。这座堡垒曾是席瓦莱恩男爵的祖传领地，如今却充斥着野性的狼人，以及那些被屠杀的守卫者们痛苦的幽灵。对于穿越银松森林南部的冒险者来说，这座城...",kw={"阿鲁高","芬鲁斯","焚木村","影牙城堡","影牙","席瓦莱恩","银松森林","斯普林瓦尔","狼人"},ang={["class:Mage"]="影牙城堡的悲剧是一个残酷的警示，告诉我们当肯瑞托法师干预凡人无法控制的异维度召唤时会发生什么。",["class:Paladin"]="指挥官斯普林瓦尔那不得安息的灵魂，是一个悲伤的提醒，诉说着那些神圣誓言被死亡扭曲的阵亡圣骑士守卫者们。",["class:Warlock"]="城堡内的黑暗能量、虚空行者和邪恶魔法吸引了那些希望找回如索兰鲁克宝珠这类古代遗物的修行者。",["faction:Horde"]="被遗忘者将阿鲁高不断扩张的狼群视为对其在银松森林新领地的直接威胁，这使得这座城堡成为死亡猎手特工和皇家药剂师学会的首要目标。"},sec={{t="席瓦莱恩王朝的陨落",b="在被梦魇笼罩之前，影牙城堡被称为席瓦莱恩城堡，那是一座由虔诚的指挥官斯普林瓦尔驻守的贵族领地。当第三次战争中天灾军团横扫洛丹伦时，达拉然的法师们成批地倒下。为了阻止亡灵的崛起，阿鲁高大法师不顾肯瑞托的领导，一头扎进了法师乌尔的研究中，召唤出异维度的狼人来扭转战局。这些被召唤的野兽虽然重创了亡灵，但很快便失去了凡人的控制，冲入银松森林南部并强攻了这座堡垒。席瓦莱恩男爵和他的整个宫廷惨遭屠杀，注定要和那些践踏他们家园的野兽一起，在石砌大厅中徘徊。"},{t="阿鲁高的孩子们",b="受尽负罪感和疯狂折磨的阿鲁高退缩到沾满鲜血的城垛内，将这些贪婪的狼人收养为他挚爱的“孩子们”，并将这座城堡命名为影牙城堡。在深处的石制巢穴中，狼群和暗影猎犬在狼王南多斯的驯化下茁壮成长，并受到阿鲁高巨大的狼兽——吞噬者芬鲁斯的看守。城墙之外，诅咒并未停止；附近的焚木村仍然被困在一个恐怖的昼夜循环之中，居民们白天是人，夜晚则变身为月光下贪婪的狼人，正如阿鲁高囚禁在那高处一样，他们与那位疯狂的大法师紧紧相连，无法逃脱。"},{t="被遗忘者的打击",b="女妖之王希尔瓦娜斯·风行者意识到阿鲁高对他们在银松森林的统治构成了极大的威胁，于是派遣皇家药剂师学会和精锐的死亡猎手去铲除狼人诅咒的源头。渗透小队在地牢中伤亡惨重，但回应瑟伯切尔号召的部落英雄最终攻破了最高的塔楼。击杀这位大法师正式终结了狼群的头领，切断了指挥野兽在荒野中肆虐的思想，并取下他的头颅作为洛丹伦复仇的证明。"}},faq={{q="当阿鲁高大法师被击败后会发生什么？",a="击杀阿鲁高斩断了控制银松森林南部狼群的核心力量。部落冒险者在女妖之王希尔瓦娜斯·风行者的命令下，将他的头颅带给了瑟伯切尔的达拉尔·道恩维沃尔。虽然他的死亡打破了指引影牙狼群的直接意志，但在城堡和周边森林中徘徊的野兽和幽灵残余，对旅行者来说仍然是一个持续存在的危险。",al={"击杀阿鲁高的结果","阿鲁高之死背景","阿鲁高死后发生了什么"}},{q="阿鲁高为什么要召唤狼人？",a="在第三次战争期间，达拉然的军队在天灾军团面前节节败退。阵亡的法师不断复活成为巫妖王的亡灵士兵。为了寻找扭转战局的武器，阿鲁高利用法师乌尔的奥术研究召唤了异维度的狼人，相信他们的野性可以阻止天灾军团。",al={"为什么要召唤狼人","阿鲁高的动机","达拉然狼人召唤"}},{q="席瓦莱恩男爵是谁？",a="席瓦莱恩男爵是一位人类贵族，在第三次战争前统治着这座城堡，并管理着附近的焚木村。当阿鲁高召唤的野兽失去控制时，它们强攻了堡垒，屠杀了男爵、他的家人和守卫。席瓦莱恩那充满怨念的鬼魂至今仍徘徊在宴会大厅中，被诅咒与杀害他的怪物一同游荡。",al={"席瓦莱恩男爵背景","影牙城堡的原领主"}},{q="为什么焚木村的村民在白天很友好？",a="阿鲁高对附近焚木村的居民施加了他的黑暗魔法。白天，他们保持着人类的形态、思想，并对联盟旅行者表现出平和的态度。入夜后，诅咒便会显现，将全村人转化为忠于城堡里那位疯狂大法师的野性狼人。",al={"焚木村人类","焚木村诅咒","为什么焚木村会变身狼人"}},{q="指挥官斯普林瓦尔是谁？",a="指挥官斯普林瓦尔是一位圣骑士，也是负责保卫席瓦莱恩城堡的军官。当狼人攻占堡垒时，他战斗到了最后一刻。他那不得安息的灵魂依然在楼上的走廊巡逻，即便是在死后依然坚守着军事职责。",al={"斯普林瓦尔背景","幽灵圣骑士首领"}},{q="什么是《乌尔之书》？",a="《乌尔之书》是一部记载了达拉然大法师乌尔研究成果的著作，他曾研究过包括狼人在内的异维度实体。阿鲁高利用乌尔的著作进行了那场灾难性的召唤。幽暗城的皇家药剂师学会正在寻找这本书，以了解这些狼类生物及其怪异魔法的本质。",al={"乌尔之书任务","乌尔背景"}}},fp="15,249,31.608.0,17.575.0,19.531.1,46.300.1,33.314.0,26.353.0,59.258.0,28.263.0,23.300.0"}
P.entries["zone:shendralas"] = {n="辛德拉",s="辛德拉是一片崎岖且处于争夺之中的荒野，坐落在菲拉斯、莫高雷和凄凉之地东南部之间。这片区域被古老的暗夜精灵遗迹和动荡不安的边境所占据，是一个极为不稳定的十字路口，半人马、流亡者和刺背野猪人在此不断发生冲突。",h="辛德拉是一片崎岖且处于争夺之中的荒野，坐落在菲拉斯、莫高雷和凄凉之地东南部之间。这片区域被古老的暗夜精灵遗迹和动荡不安的边境所占据，是一个极为不稳定的十字路口，半人马、流亡者和刺背野猪人在此不断发生冲突。",kw={"刺背避难所","凄凉之地","暮影眺望台","菲拉斯","杜蒙特湖","玛格拉姆前线","莫高雷","流放者隐匿处","辛德拉","白骨之谷"},ang={["faction:Alliance"]="一片偏远且处于争夺之中的荒野，为菲拉斯和卡利姆多中部之间提供了替代路线，但这片区域充满了需要高度警惕的危险。",["faction:Horde"]="这里位于莫高雷南端之外，将玛格拉姆半人马和野猪人限制在此对于保护部落边境至关重要。",["race:NightElf"]="这个名字让人联想到埃雷萨拉斯的古老上层精灵传说，引起了那些警惕卡利姆多南部鲁莽奥术行为的哨兵们的注意。",["race:Tauren"]="由于该地区与莫高雷和凄凉之地接壤，野猪人和半人马在这些山脊上的侵略行为对附近的祖传狩猎场构成了直接威胁。"},sec={{t="动荡的边境之地",b="辛德拉隐蔽在凄凉之地东南方的高地中，与莫高雷和菲拉斯接壤，是一片远离各大阵营主城的原始边境。这里崎岖的山道和隐秘的飞地收容着那些试图在卡利姆多荒野边缘求生的绝望之徒。从如暮影眺望台这样偏僻的观景点，到像流放者隐匿处这样无法无天的避难所，这个地区由那些希望不被发现或保持隐姓埋名的人们所定义。"},{t="半人马、野猪人与古老遗迹",b="这片土地带有赋予其名称的古老上层精灵留下的独特印记，但这并不意味着它和平安宁。玛格拉姆前线的半人马冲突不断，使其边境地区的古老血仇一直延续至今。与此同时，入侵的野猪人在此维持着诸如刺背避难所这样的防御工事，将每一处阴暗的峡谷都变成了过路旅者需要争夺的领地。"},{t="白骨之谷",b="白骨之谷位于向西北通往凄凉之地的出口处，是一条阴森的走廊，也是进入辛德拉的主要陆路通道。这条通道在阳光和风的侵蚀下变得惨白，作为这一地区山岭间持续不断的暴力冲突的残酷见证。"}},faq={{q="辛德拉在哪里？",a="辛德拉位于凄凉之地东南方，坐落在菲拉斯和莫高雷的边界之间。徒步前来的旅者通常会穿过白骨之谷，从凄凉之地进入该区域。",al={"辛德拉在哪里","辛德拉的位置","如何前往辛德拉"}},{q="辛德拉是由联盟还是部落控制？",a="没有阵营在这里拥有主权。辛德拉是一个充满流窜的半人马、敌对的野猪人、流亡者和零星营地的争夺边境。",al={"辛德拉是部落的吗","辛德拉是联盟的吗","谁拥有辛德拉"}},{q="这里有哪些主要定居点或地标？",a="显著的地标包括白骨之谷、刺背避难所、暮影眺望台、玛格拉姆前线、流放者隐匿处以及辛德拉本身的中心区域。",al={"辛德拉的子区域","辛德拉的地标","辛德拉的兴趣点"}},{q="为什么这里会有半人马？",a="半人马的领土战争从凄凉之地的平原一直延伸到玛格拉姆前线沿线的这一地区，该部落在此与当地的守军和敌对派系进行着激烈的战斗。",al={"辛德拉的半人马","玛格拉姆前线","为什么玛格拉姆在这里"}},{q="什么是刺背避难所？",a="刺背避难所是一个由刺背野猪人占据的防御前哨，他们已经在该区域边缘建立了稳固的据点。",al={"刺背避难所","辛德拉的野猪人"}},{q="该地区与杜蒙特湖有什么联系？",a="从地理上讲，辛德拉的荒野横跨了杜蒙特湖所在的群山地带，而杜蒙特湖隐秘地隐藏在旧时的勘测地图中。",al={"杜蒙特湖","辛德拉地图历史"}}},fp="11,141,23.322.0,36.313.0,19.222.0,29.144.0,55.152.0,45.155.0,27.159.0,28.132.0,57.115.0"}
P.entries["zone:silithus"] = {n="希利苏斯",s="希利苏斯是一片荒凉、风沙侵蚀的沙漠，位于卡利姆多大陆的西南远端。在干旱的沙层之下，潜伏着广袤的虫群聚落，以及一千年前被封印在宏伟的甲虫之墙后的古老废墟——安其拉。如今，塞纳里奥议会的德鲁伊们在此坚守，对抗着不断蔓延的虫群和末日教派。",h="希利苏斯是一片荒凉、风沙侵蚀的沙漠，位于卡利姆多大陆的西南远端。在干旱的沙层之下，潜伏着广袤的虫群聚落，以及一千年前被封印在宏伟的甲虫之墙后的古老废墟——安其拉。如今，塞纳里奥议会的德鲁伊们在此坚守，对抗着不断蔓延的虫群...",kw={"安其拉","塞纳里奥要塞","亚什虫巢","雷戈虫巢","佐拉虫巢","甲虫之台","甲虫之墙","希利苏斯虫族","希利苏斯","暮光之锤"},ang={["class:Druid"]="作为塞纳里奥议会在南卡利姆多行动的核心，希利苏斯召唤着德鲁伊们去遏制大地的腐化，直面威胁自然平衡的诡异虫群。",["profession:Herbalism"]="尽管地形是严酷的沙漠，但这里仍生长着珍稀的植物奇迹，包括山鼠草、梦叶草、太阳草，以及极其珍贵的黑莲花。",["profession:Mining"]="希利苏斯的贫瘠岩石和虫穴中蕴藏着世界上最丰富的钍矿矿脉，其中还包括隐藏在虫巢内、附着着稀有软泥的矿脉。",["race:NightElf"]="希利苏斯是一片阴森的安息地，在流沙之战中，你的先辈们曾在此浴血奋战，牺牲了数千人的生命才将安其拉之门封印。"},sec={{t="沙漠前线",b="想要到达希利苏斯，必须穿过安戈洛环形山的原始丛林，并沿其西北角一条宽阔的岩石通道攀登而上。这里的环境反差极其强烈：郁郁葱葱的原始植被转瞬即逝，取而代之的是广袤的移动沙丘、崎岖的岩石，以及怪异高耸的虫巢。这里几乎没有水源，风中回荡着昆虫翅膀的嗡嗡声和沙粒的低语。塞纳里奥议会在沙漠中央设立了塞纳里奥要塞，它是这片充满敌意的荒原上唯一的文明堡垒，为冒险者、研究人员和战士们提供庇护。"},{t="流沙之战的回响",b="一千年前，这片干旱的旷野曾是流沙之战的战场。暗夜精灵与伟大的巨龙军团联手，拼死抵御由古老的亚基文明衍生而来的阴险虫族帝国——其拉虫人。当彻底的胜利变得遥不可及，守卫者们利用甲虫之墙和受过魔法加持的甲虫之台，将这些虫群封锁在了它们的据点之内。尽管宏伟的大门维持了封闭，地下的隧道仍让野兽般的希利苏斯虫族得以钻出，并在沙漠各处建立了诸如亚什虫巢、佐拉虫巢和雷戈虫巢等庞大的聚落。"},{t="汇聚的风暴",b="世界末日般的暮光之锤教派已在多处要塞化据点盘踞，他们在此召唤元素恐怖，并崇拜着沉睡在安其拉之下的黑暗力量。塞纳里奥议会的观察员正密切监视着沙漠中不断扩张的希利苏斯虫群，以及甲虫之墙后的远古威胁。"}},faq={{q="我该如何徒步前往希利苏斯？",a="前往安戈洛环形山的西北角。在蜿蜒的河湾附近，两根突出的天然石柱之间，有一条倾斜的土路，沿着它向上穿过环形山的岩壁，即可直接进入希利苏斯沙漠。",al={"希利苏斯入口","如何前往希利苏斯","希利苏斯路径"}},{q="什么是甲虫之墙？",a="甲虫之墙是位于希利苏斯南部的一道巨大且带有魔法的屏障。它由暗夜精灵和巨龙军团在流沙之战期间建造，旨在将邪恶的其拉帝国囚禁在安其拉之中，至今已有一千年历史。",al={"安其拉之门","甲虫之墙","希利苏斯的大墙"}},{q="谁在管理塞纳里奥要塞？",a="塞纳里奥要塞是由塞纳里奥议会建立并管理的岗哨。其德鲁伊和同盟守护者们在此观察入侵的希利苏斯虫群，调查古老废墟，并欢迎来自联盟和部落的中立旅行者。",al={"塞纳里奥要塞里有什么人","塞纳里奥要塞阵营","塞纳里奥要塞友善度"}},{q="遍布全地区的巨型虫穴是什么？",a="它们是希利苏斯虫族的主要地下巢穴：亚什虫巢、佐拉虫巢和雷戈虫巢。每一个虫巢都是一个庞大的隧道网络，栖息着听命于安其拉封印意志的各类虫形生物阶级。",al={"希利苏斯虫巢","希利苏斯的虫穴","亚什虫巢佐拉虫巢"}},{q="暮光之锤在这里做什么？",a="暮光之锤教派在希利苏斯维持着多个要塞化基地，包括暮光营地和暮光岗哨。他们进行邪恶的仪式来召唤元素生物，并崇拜着被封印在甲虫之墙后的古老邪恶存在。",al={"希利苏斯的暮光教徒","希利苏斯的暮光前哨站","为什么暮光之锤在希利苏斯"}}},fp="8,245,19.408.0,28.509.0,18.272.0,33.207.0,24.219.0,23.205.0,49.212.0,41.243.0"}
P.entries["zone:silverpine"] = {n="银松森林",s="银松森林是一片阴森、雾气弥漫的林地，沿着洛丹伦西海岸延伸，位于提瑞斯法林地和封闭的格雷迈恩之墙之间。这里深受天灾瘟疫留下的创伤所困扰，是亡灵族的南部交战前线。来到这里的旅行者会面对徘徊在阴影中的野性狼人、染病的豺狼人以及敌对的人类据点。",h="银松森林是一片阴森、雾气弥漫的林地，沿着洛丹伦西海岸延伸，位于提瑞斯法林地和封闭的格雷迈恩之墙之间。这里深受天灾瘟疫留下的创伤所困扰，是亡灵族的南部交战前线。来到这里的旅行者会面对徘徊在阴影中的野性狼人、染病的豺狼人以及...",kw={"安伯米尔","阿鲁高","芬里斯岛","格雷迈恩之墙","焚木村","烂苔豺狼人","瑟伯切尔","影牙城堡","银松森林"},ang={["class:Mage"]="安伯米尔的存在，以及大法师阿鲁高陷入狼性疯狂，使银松森林成为了肯瑞托魔法酿成灾难性后果的残酷警示。",["faction:Alliance"]="联盟探险者会发现这里是一片极为敌对的森林，只有安伯米尔那摇摇欲坠的达拉然驻军，以及焚木村那些悲惨的被诅咒村民，是这片土地上仅有的点缀。",["race:Undead"]="银松森林代表着亡灵族在提瑞斯法林地以南扩张的最前线，皇家药剂师协会在这里测试新的药剂，而死亡卫士则在此与天灾余部交战。"},sec={{t="阴森的前线",b="银松森林曾是洛丹伦一片郁郁葱葱的奇景，高贵的旅人们曾穿行于此前往洛丹伦王都，如今却在第三次战争的影响下凋零。鬼魅般的浓雾在濒死的银松树间穿梭，荒废的农舍被遗弃在荒野之中。北部是提瑞斯法林地，东部海岸则毗邻洛丹米尔湖。南部矗立着宏伟而紧闭的格雷迈恩之墙，将孤立主义的吉尔尼斯王国与周遭的混乱隔绝开来。亡灵族在瑟伯切尔维持着他们的中央哨所，努力从各方敌人手中守护这片森林。"},{t="敌对据点与天灾军团",b="亡灵族对银松森林的主权遭到了生者与亡灵阵营的激烈争夺。在东部的芬里斯岛上，图勒·鸦爪统领着一支天灾余部，并指挥着瘟疫肆虐的烂苔豺狼人，骚扰着北部的农田。在南部，来自达拉然的人类法师占据着加固的安伯米尔定居点，进行神秘学研究并阻挠亡灵族的扩张。皇家药剂师协会和瑟伯切尔的高级执行官哈德瑞克正展开一场残酷的多面战争，旨在消除这些威胁并测试全新的致命瘟疫。"},{t="狼人与影牙",b="银松森林最臭名昭著的威胁是狼人诅咒。西南部林地上方矗立着影牙城堡，那里曾是席瓦莱恩男爵的宅邸，如今被疯狂的达拉然大法师阿鲁高所占据。为了在第三次战争中抵御天灾军团，阿鲁高召唤了异维度的狼兽。这些生物反过来攻击了它们的召唤者，将狼人诅咒散布到了南部林地。在焚木村，外表看起来与常人无异的人类村民白天照常劳作，但一到夜幕降临，他们就会变身为凶残的狼人。"}},faq={{q="南界线的格雷迈恩之墙是什么？",a="格雷迈恩之墙是一道由吉恩·格雷迈恩国王建造的巨大石墙，旨在将他的吉尔尼斯王国与洛丹伦的其他地区完全隔离开来。当第三次战争中天灾军团蹂躏这片大陆时，吉尔尼斯锁上了大门，拒绝了外界的援助，使得墙北部的土地——包括银松森林南部——只能自生自灭。",al={"为什么会有巨大的墙","格雷迈恩之墙背景故事","通往吉尔尼斯的大门"}},{q="为什么焚木村的村民会在夜间发起攻击？",a="焚木村的居民深受大法师阿鲁高的狼人诅咒之苦。白天，他们保持人类形态并维持日常生活，对联盟保持友好。当月亮升起时，诅咒便会发作，使全村人都变身为凶残、嗜血的狼人，疯狂攻击附近的任何人。",al={"焚木村之谜","焚木村狼人","为什么焚木村人类在晚上有敌意"}},{q="图勒·鸦爪是谁？",a="图勒·鸦爪是一位效力于天灾军团的强大死灵法师。他以洛丹米尔湖中芬里斯岛上的芬里斯城堡为基地，指挥着亡灵军团，并控制着整个银松森林东部的烂苔豺狼人，直接威胁着亡灵族的东部侧翼。",al={"谁领导芬里斯岛","图勒·鸦爪背景故事","芬里斯岛上的天灾军团"}},{q="为什么达拉然会占据安伯米尔？",a="安伯米尔由大法师阿泰瑞克领导的达拉然法师所把持。这些人类法师以村庄为据点，监视着亡灵族的动向，研究肆虐森林的魔法苦难，并试图遏制附近从影牙城堡蔓延开来的狼人疫情。",al={"安伯米尔法师","为什么联盟在安伯米尔","达拉然在银松森林"}},{q="瑟伯切尔是什么？",a="瑟伯切尔是亡灵族在银松森林的主要军事前哨和交通枢纽。在高级执行官哈德瑞克的指挥下，它是死亡卫士巡逻队、死亡猎手侦察兵和皇家药剂师协会在努力保卫这片森林时的作战基地。",al={"银松森林的部落城镇","飞行点在哪里","瑟伯切尔背景故事"}},{q="联盟玩家能在银松森林进行任务吗？",a="银松森林没有联盟的任务中心或友好城镇；所有本地任务均为部落专属。联盟探险者通常只有在从南海镇出发探索影牙城堡或对抗敌对的亡灵势力时才会进入这片森林。",al={"银松森林是部落专属吗","银松森林的联盟任务","联盟能去银松森林吗"}}},fp="17,230,18.551.0,30.531.1,25.482.1,49.319.0,57.270.1,23.261.1,35.243.0,22.247.0,48.232.0"}
P.entries["zone:stockade"] = {n="监狱",s="监狱是暴风城的高安全级别监狱，位于城市运河区法师区附近。这里关押着王国最危险的凶徒、政治叛乱分子和被俘的国家公敌，但最近该设施已陷入了暴力的混乱之中。典狱官塞尔沃特被迫退守到门口，迫切地招募有能力的冒险者，在暴乱蔓延到首都之前将其平定。",h="监狱是暴风城的高安全级别监狱，位于城市运河区法师区附近。这里关押着王国最危险的凶徒、政治叛乱分子和被俘的国家公敌，但最近该设施已陷入了暴力的混乱之中。典狱官塞尔沃特被迫退守到门口，迫切地招募有能力的冒险者，在暴乱蔓延到首...",kw={"巴基尔·斯瑞德","布鲁高·铁拳","运河","迪菲亚","迪克斯特·瓦德","哈姆霍克","卡姆·深怒","暴乱","监狱","暴风城","塔格尔","典狱官塞尔沃特"},ang={["class:Mage"]="监狱位于法师区的运河边上，里面关押着容易受到减速法术影响的近战格斗家，而食人魔术士哈姆霍克则会施放闪电链。",["class:Rogue"]="监狱的布局呈现出锁闭的铁窗和迪菲亚关联错综复杂的网络，提供了独特的开锁练习，并能让人深入了解巴基尔·斯瑞德的地下黑帮组织。",["faction:Alliance"]="这场叛乱威胁到了首都的核心；平定起义不仅维护了暴风城的内部安全，还完成了赤脊山、暮色森林和铁炉堡的非官方悬赏任务。",["race:Dwarf"]="卡姆·深怒关在暴风城的牢房里是对丹莫德的侮辱；铁炉堡王国要求取下他的首级，以祭奠在湿地丧生的矮人生命。"},sec={{t="被围困的监狱",b="在暴风城宁静的运河之下，监狱已然沦为战区。当正规军开赴遥远的前线作战时，人手不足的监狱被迫依靠缺乏经验的年轻人——包括十四岁的新兵——来维持秩序。这显然行不通。囚犯们发动了血腥而有组织的叛乱，他们将羊毛毯撕成帮派头巾，屠杀了剩余的卫兵。典狱官塞尔沃特勉强控制住了入口，而监舍、走廊和关押区则落入了冷酷的罪犯手中。"},{t="贵族与刺客",b="这场暴乱暴露了暴风城政治机器丑陋的一面。外围领地对贵族议会为了自身筹码而中止死刑的做法早已感到沮丧。赤脊山的卫兵伯尔顿希望处决被俘的兽人可怕的塔格尔以惩戒其暴行，却眼睁睁看着贵族们冻结了判决。夜色镇的议员米尔斯迪普看着掘墓人迪克斯特·瓦德尽管为通灵师摩尔本·奈尔亵渎坟墓，却仍逃脱了绞刑。就连丹莫德的矮人们也发信要求处死黑铁破坏者卡姆·深怒。随着监狱陷入混乱，地方当局悄悄雇佣了冒险者，去执行那些首都法庭拒绝执行的死刑。"},{t="幕后黑手与暴乱者",b="在监狱协同崩溃的背后是巴基尔·斯瑞德，一名与迪菲亚潜行者有直接联系的狡诈重犯，他在自己的监房里策划了这场起义。暴乱者中包括危险的矮人格斗家布鲁高·铁拳。他是冒险者在帮助塞尔沃特夺回监狱时可能会遇到的几名顽固罪犯之一。"}},faq={{q="监狱为何发生公开叛乱？",a="迪菲亚潜行者在监狱严重人手不足时策划了一场全狱范围的暴乱。随着暴风城军队部署到遥远的前线，十几岁的志愿者被留下来看守冷酷的杀手。罪犯们伏击了工作人员，夺取了武器，并将典狱官塞尔沃特赶出了监舍区。",al={"暴乱原因","监狱里发生了什么","监狱暴乱起因"}},{q="谁在监狱内部领导起义？",a="起义背后的策划者是巴基尔·斯瑞德，一名关押在东部监舍区、颇具影响力的迪菲亚重犯。其他危险的囚犯包括布鲁高·铁拳、哈姆霍克和卡姆·深怒。",al={"监狱首领","谁领导了暴乱","谁在管理监狱"}},{q="像可怕的塔格尔和迪克斯特·瓦德这样的囚犯为何还活着？",a="两人都被判处死刑，但贵族议会中腐败的政客对他们的死刑执行进行了官僚式的搁置，以便将其作为政治筹码。这种干预激怒了湖畔镇和夜色镇的盟友，促使他们派遣冒险者在混乱中除掉这些囚犯。",al={"为什么没处决塔格尔","迪克斯特·瓦德判决","贵族议会腐败"}},{q="击败布鲁高·铁拳对监狱意味着什么？",a="布鲁高·铁拳是暴乱者中危险的矮人格斗家。在冒险者努力平定暴乱的同时，击败他可以消除监狱内的一个威胁。",al={"布鲁高·铁拳背景故事","击杀布鲁高","布鲁高是谁"}},{q="为什么人类监狱里会有黑铁矮人和兽人？",a="监狱是关押高价值战俘的最高安全级别拘留所。可怕的塔格尔曾领导黑石兽人在赤脊山发动攻击，而卡姆·深怒在被捕并转移到首都之前，曾为湿地的黑铁部族进行过破坏活动。",al={"为什么会有黑铁矮人","卡姆·深怒背景故事","塔格尔监狱"}},{q="部落玩家能进入监狱吗？",a="可以，但非常危险。地下城入口直接位于暴风城内的法师区运河附近。部落潜入者必须潜行穿过城市卫兵和首都守卫才能到达传送门。",al={"部落能打监狱吗","暴风城监狱里的部落"}}},fp="12,345,20.476.0,20.680.1,30.277.1,38.302.0,35.174.0,60.285.0,60.151.0,61.253.0,37.213.0"}
P.entries["zone:stonetalon"] = {n="石爪山脉",s="石爪山脉是一片崎岖、被风雕琢的险峻山峰，与灰谷、贫瘠之地和凄凉之地接壤。这片区域被暗夜精灵和牛头人共同奉为神圣的避难所，其神圣的高地与下方峡谷中充斥的烟雾和机械形成了鲜明的对比。如今，山脉因森林砍伐、不稳定的元素破坏和日益激化的边境冲突而满目疮痍。",h="石爪山脉是一片崎岖、被风雕琢的险峻山峰，与灰谷、贫瘠之地和凄凉之地接壤。这片区域被暗夜精灵和牛头人共同奉为神圣的避难所，其神圣的高地与下方峡谷中充斥的烟雾和机械形成了鲜明的对比。如今，山脉因森林砍伐、不稳定的元素破坏和日...",kw={"焦炭谷","格雷苏","玛拉卡金","石爪山脉","石爪峰","烈日石居","塔伦迪普小径","狂风峭壁"},ang={["class:Druid"]="狂风峭壁的亵渎和焦炭谷的焦灼腐化，是对那些寻求安抚狂怒自然之灵并保护神圣栖息地的德鲁伊发出的严峻召唤。",["class:Shaman"]="遭受地精钻探机袭击的山灵哀鸣远至奥格瑞玛都能听到，这召唤着萨满祭司们去平息狂暴的岩石元素，并恢复山峰的平衡。",["faction:Alliance"]="联盟驻扎在石爪峰之巅和狂风峭壁周围的隐蔽营地中，保护着古老的卡多雷墓穴，抵御地精机器和不断逼近的领土竞争对手。",["faction:Horde"]="部落冒险者依靠烈日石居这处僻静的避难所和南部的玛拉卡金巨魔哨站，来遏制荆棘谷地精的工业污染，并铲除奸诈的恐怖图腾不法之徒。"},sec={{t="恶风与山峰",b="石爪山脉从卡利姆多中部拔地而起，截住了从西海漂来的水汽，引发了突如其来的暴雨，形成了湿滑险峻的砂岩小径。低谷地区的主要特征是被称为“恶风”的持续强风，它能用沙砾遮蔽旅行者的双眼，或将不留神的行人直接吹下悬崖。在高处，常青森林覆盖着环绕石爪峰的山脊，暗夜精灵们在那里照料着古老的墓穴和林地，守护着沿着暗色湖筑巢的双足飞龙和角鹰兽的神圣栖息地。"},{t="工业与入侵",b="山脉的宁静祥和因荆棘谷地精的到来而遭到了粗暴的破坏。这些地精在狂风峭壁建立了庞大的伐木场并挖掘深层露天矿坑，在疯狂的麻风侏儒格雷苏的协助下，他们砍伐了原始森林，用炉烟熏黑了天空，并将工业废料倾倒入山涧溪流中。他们的贪婪引发了迅速的报复：来自奥格瑞玛的当地萨满祭司回应了山灵痛苦的哀鸣，而驻扎在附近的联盟小营地也奋起反抗污染者，以保护高地仅存的一切。"},{t="往昔的伤痕",b="南面是焦炭谷，这片曾经繁茂的荒野如今已沦为覆盖着灰烬的废土，到处是游荡的火元素、黑龙幼龙和鹰身人。虽然这些山峰曾是部落和联盟在神秘的神谕者指引下，于第三次战争期间达成不安停战协定的历史遗址，但目前双方的关系正在破裂。叛变的恐怖图腾牛头人从被占领的营地中发动袭击，而玛拉卡金的暗矛巨魔则与从贫瘠之地和灰谷向外推进的联盟军队发生冲突。"}},faq={{q="我该如何前往石爪山脉？",a="大多数旅行者通过塔伦迪普小径进入，这是一条从灰谷西南部切入山脉的山路。此外还有通往南方凄凉之地的高海拔小径，以及直接向东下降进入贫瘠之地北部地区的路线。",al={"石爪山脉入口","如何前往石爪山脉","石爪山脉道路"}},{q="为什么焦炭谷会被烧毁并化为废墟？",a="焦炭谷曾经是一片郁郁葱葱的避风港，但一场灾难性的毁灭将整个山谷吞没在火焰之中。如今它已沦为冒着烟的废墟，到处爬满了狂暴的火元素、流浪的幼龙和致命的鹰身人。",al={"焦炭谷火灾","焦炭谷发生了什么","为什么焦炭谷被烧毁"}},{q="荆棘谷地精在狂风峭壁做什么？",a="荆棘谷地精正在无情地砍伐树木，并深入山体开采矿产资源。他们的作业用引擎机油污染了峭壁湖，剥光了山谷的植被，并激怒了当地的灵魂和土著居民。",al={"石爪山脉荆棘谷地精","狂风峭壁地精","为什么地精要砍伐树木"}},{q="主要的飞行管理员在哪里？",a="联盟英雄使用位于北部石爪峰高处圣所的飞行管理员，而部落冒险者则以中央山脉村庄烈日石居为基地。",al={"石爪山脉飞行点","石爪山脉飞行点在哪里"}},{q="第三次战争期间在石爪峰发生了什么？",a="在先知麦迪文幻象的指引下，萨尔和吉安娜·普罗德摩尔攀登了石爪峰的洞穴，寻找神谕者。在那里，两位阵营领袖缔结了历史性的临时联盟，联合起来共同对抗海加尔山的燃烧军团。",al={"石爪峰传说","石爪山脉神谕者","第三次战争石爪山脉"}},{q="石爪山脉的恐怖图腾是谁？",a="恐怖图腾是一个残忍的、敌视外来势力的叛变牛头人部族。在石爪山脉，他们占领了靠近贫瘠之地边界的一个山头哨站，恐吓当地旅行者并俘虏人员。",al={"恐怖图腾岗哨","石爪山脉恐怖图腾"}}},fp="20,167,27.462.0,22.461.0,17.474.0,41.202.0,42.194.0,52.224.0,42.161.0,54.229.0,36.181.0"}
P.entries["zone:stormwind"] = {n="暴风城",s="白墙环绕的暴风城是人类最伟大的庇护所，也是联盟的心脏。然而，国王已经失踪。如今，王冠落在一个年仅十岁的男孩头上。",h="白墙环绕的暴风城是人类最伟大的庇护所，也是联盟的心脏。然而，国王已经失踪。如今，王冠落在一个年仅十岁的男孩头上。",kw={"安度因","伯瓦尔","大教堂","矿道地铁","普瑞斯托","石匠","暴风城","范克里夫","乌瑞恩"},ang={["class:Paladin"]="身为圣骑士，你可以前往光明大教堂，那是南方最重要的信仰圣所。这里培养白银之手的骑士，维护正义。",["class:Rogue"]="身为潜行者，你可以在旧城区的石板街道下找到SI:7的总部。这里掌管着联盟最主要的情报与间谍网络。",["faction:Alliance"]="身为联盟的一员，你可以倚重暴风城的海军力量、精神支柱地位，以及至关重要的外交领导作用。它是Grand Alliance人口最多的大都市。",["race:Dwarf"]="身为矮人，你可以乘坐矿道地铁，前往矮人区探访同胞。他们与这个人类王国保持着密切的贸易和军事联系。",["race:Human"]="身为人类，在北方的洛丹伦、奥特兰克和达拉然陷落后，暴风城便是你的族人最后一座拥有独立主权的伟大都城。"},sec={{t="从废墟中崛起",b="暴风城历史悠久。一千多年前，阿拉希的后裔建立了这座城市。此后许多代人间，这个王国繁荣昌盛，无须任何外援。后来，部落穿过黑暗之门而来。南方大陆惨遭蹂躏，这座城市也在第一次兽人战争中被夷为平地。\n\n幸存者追随安杜因·洛萨爵士北上，渡过无尽之海，前往洛丹伦。部落在Second War中战败后，泰瑞纳斯·米奈希尔二世国王与联盟出资重建暴风城。石匠行会用光洁的白石重新筑起城市，运河穿行于各个城区之间。"},{t="分裂的宫廷",b="然而，白石之下的王国却动荡不安。贵族与石匠行会因工钱发生争执，争端让王国债台高筑，难以为继。公会的工人奋起暴动。他们被逐出了自己亲手建造的城市。\n\n随后，瓦里安·乌瑞恩国王在前往一场峰会的途中失踪。为免恐慌蔓延，王冠传给了他的儿子，王子安度因·乌瑞恩国王。他年仅十岁。如今，伯瓦尔·弗塔根公爵以摄政王兼军队统帅的身份执政。而站在他身旁的，是王室顾问女伯爵卡特拉娜·普瑞斯托。"},{t="Grand Alliance的心脏",b="洛丹伦被Scourge攻陷后，暴风城成为人类最为倚重的城市。虔诚的信徒聚集在光明大教堂。而在英雄谷，高耸的雕像纪念着Sons of 洛萨。他们穿过黑暗之门后，便再也没有出现在世人眼前。"},{t="石匠工会的去向",b="石匠们在会长艾德温·范克里夫的领导下，于西部荒野重新集结。他们在那里组成了迪菲亚潜行者，如今，这群蒙着红色面巾的匪徒正扼住王国农田的命脉。那些曾筑起暴风城白墙的工匠立下誓言，要让贵族为每一块石头付出代价。"},{t="宫廷中的朋友",b="迪菲亚潜行者在暴风要塞内找到了帮手。贵族的葛瑞格·莱斯科瓦勋爵暗中与他们往来，泄露王国的计划，同时仍与那些欺骗石匠的贵族同席议事。"},{t="要塞中的阴影",b="女伯爵卡特拉娜·普瑞斯托一直在暗中左右贵族的决策。她煽动贵族与石匠之间的冲突，无视西部荒野和赤脊山等地居民点请求军事援助的呼声。她还向伯瓦尔·弗塔根公爵进谗言，让暴风城的军团按兵不动、彼此分裂，而城墙外的动乱正威胁着王位。"}},faq={{q="谁在统治暴风城？",a="十岁的王子安度因·乌瑞恩国王戴着暴风城的王冠，伯瓦尔·弗塔根公爵则以摄政王的身份治理王国，统率军队。瓦里安·乌瑞恩国王仍下落不明，伯瓦尔依赖王室顾问女伯爵卡特拉娜·普瑞斯托的建议。",al={"现任国王","谁是国王","谁统治暴风城","暴风城国王"}},{q="瓦里安·乌瑞恩国王发生了什么事？",a="瓦里安国王乘船前往塞拉摩参加外交峰会时离奇失踪。为了维持稳定，他失踪的消息被隐瞒下来，但传言仍在街巷与乡间流传。",al={"瓦里安在哪","失踪的国王","瓦里安失踪","瓦里安·乌瑞恩失踪"}},{q="这座城市为什么要重建？由谁重建？",a="兽人部落在第一次兽人战争期间将原来的城市付之一炬。第二次兽人战争结束后，洛丹伦联盟出资重建，工匠大师艾德温·范克里夫率领石匠行会，用白石重新筑起了这座都城。",al={"谁重建了暴风城","石匠工会","新暴风城","城市重建"}},{q="石匠工会为什么要反抗王室？",a="贵族在扩充暴风城军队时背负了沉重债务，随后拒绝向石匠行会支付承诺的工钱。艾德温·范克里夫要求支付报酬时，贵族们解散了公会。工人们发起暴动，随后被逐出城市。",al={"迪菲亚潜行者起源","迪菲亚潜行者为何愤怒","石匠工会骚乱"}},{q="英雄谷的巨型雕像是谁？",a="英雄谷纪念着洛萨之子：图拉扬将军、游侠队长奥蕾莉亚·风行者、大法师卡德加、库德兰·蛮锤，以及达纳斯·托尔贝恩。这些雕像纪念着那些穿过黑暗之门、前往德拉诺封闭裂隙以保护艾泽拉斯的英雄。",al={"入口处的雕像","英雄谷雕像","洛萨之子雕像"}},{q="暴风城如何与铁炉堡相连？",a="矿道地铁是一条连接暴风城与铁炉堡的地下铁路。大工匠格尔宾·梅卡托克应国王麦格尼·铜须的请求修建了这条铁路，让两座都城能够迅速开展贸易，并在战争中相互增援。",al={"矿道地铁","前往铁炉堡的列车","如何前往铁炉堡"}},{q="为什么暴风城不派兵援助西部荒野和赤脊山？",a="在女伯爵卡特拉娜·普瑞斯托的引导下，王廷声称，暴风城无法从城墙和附近边境抽调兵力。王国财政吃紧，政治内斗又让贵族陷入瘫痪，各地城镇只能依靠当地民兵自保。",al={"暴风城军队缺失","为什么不援助西部荒野","拒绝增援"}}},fx={["9beefbfb"]={q="暴风城是什么地方？",a="暴风城是人类暴风王国的首都，也是艾泽拉斯现存最宏伟的人类堡垒。这座城市建于艾尔文森林以北的海岸，是大联盟的心脏、主要港口和文化中心。它从第一次兽人战争的灰烬中重建，坚固的石墙庇护着工匠、学者、士兵和难民，他们将这座城市视为人类坚韧不屈的象征。",al={"关于暴风城","暴风城首都","暴风城是什么"}},edb1c1aa={q="暴风城过去发生过什么？",a="这个王国最初由阿拉索血脉的后裔于一千多年前建立，在与豺狼人和丛林巨魔的冲突中繁荣了数个世纪。然而，在第一次兽人战争期间，兽人部落围攻了这座首都。莱恩乌瑞恩国王惨遭杀害后，城市被攻破、洗劫，最终付之一炬。安杜因·洛萨爵士带领幸存的难民渡海北上，前往洛丹伦，直到第二次大战结束后才返回故土，收复家园并着手重建。",al={"暴风城历史","暴风城的毁灭","暴风城 第一次兽人战争"}},d0a4b7c8={q="暴风城危险吗？",a="凭借宏伟的城门和警觉的城市卫兵，暴风城成为世上防御最严密的庇护所之一。然而，看不见的危险仍潜伏其中。附近的监狱曾发生暴力骚乱，邪教徒和盗贼在昏暗的运河边游荡，而迪菲亚潜行者煽动的政治动荡让贵族始终惴惴不安。虽然战火很少蔓延到城墙之内，腐败、叛国与隐秘的阴谋却在要塞和陋巷中悄然滋生。",al={"暴风城安全吗","暴风城的危险","暴风城面临的威胁"}},["163d181d"]={q="迪菲亚潜行者是什么组织？",a="迪菲亚潜行者是一个由亡命之徒、强盗、盗贼和海盗组成的残忍组织，公然威胁着王国的稳定。他们佩戴标志性的红色面罩，象征着为其事业流下的鲜血，因此很容易辨认。虽然他们主要在西部荒野、赤脊山和死亡矿井活动，但势力已直接渗入暴风城，他们的间谍和同情者在城中削弱王权，并在劳动民众之间挑起纷争。",al={"迪菲亚潜行者","迪菲亚潜行者是谁","迪菲亚帮派"}},b1d432aa={q="光明大教堂是什么地方？",a="光明大教堂高耸于教堂广场之上，是人类和大联盟最重要的精神中心。它在第二次大战之后由大主教阿隆索斯·法奥和时任主教的本尼迪塔斯主持重建，如今是圣光教会的所在地，也是白银之手骑士团的一处总部。圣骑士和牧师从各地赶来，在宏伟而宁静的厅堂中接受训练、寻求智慧并静心冥想。",al={"光明大教堂","暴风城大教堂","暴风城圣光教会"}},["3414b788"]={q="我是怎么来到暴风城的？",a="如果你从北郡启程，一路穿过艾尔文森林，大路便会带你穿过英雄谷，直抵首都坚固的城门。如果你来自丹莫罗或铁炉堡，那么你很可能乘坐了矿道地铁，这项侏儒工程奇迹穿行于群山之下，将矮人的堡垒与矮人区直接相连。来自艾泽拉斯更远地方的旅人，则在穿越南方诸王国的漫长跋涉后抵达暴风城门前，寻找人类最后的宏伟堡垒。",al={"怎么来到这里的","怎么抵达暴风城的","怎么到暴风城的"}},["68c43aeb"]={q="我在暴风城该做些什么？",a="暴风城是联盟的心脏，也是供你休息、训练和补充物资的庇护所。然而，在洁白闪耀的城墙之下，王国早已四分五裂。瓦里安·乌瑞恩国王离奇失踪，留下年幼的国王安度因和伯瓦尔·弗塔根公爵，在要塞中竭力应对瘫痪的政局。与此同时，西部荒野和赤脊山周边的边境地区饱受猖獗匪患之苦，急切地呼唤援助，而迪菲亚潜行者仍在暗中密谋。你来到这里，是为了磨炼技艺、向所属阵营的领袖报到，并为这个困境重重的王国挺身而战。",al={"为什么在这里","在这里做什么","在暴风城的目的是什么"}}},fp="14,142,19.590.0,15.532.0,27.258.0,21.287.1,17.236.1,19.351.2,30.238.0,35.216.0,38.251.1,48.261.1,50.272.0,40.223.0,65.267.0"}
P.entries["zone:stranglethorn"] = {n="荆棘谷",s="荆棘谷是一片未经驯服的茂密丛林，占据了东部王国南端，位于暮色森林以南。这片雨林曾是伟大的古拉巴什帝国的所在地，如今却散布着崩塌的巨魔遗迹、凶猛的野兽，以及由地精、海盗和士兵建立的互相竞争的营地。当地的巨魔部落、荆棘谷地精以及在此地争夺立足点的敌对派系，都在激烈地争夺该地区的控制权。",h="荆棘谷是一片未经驯服的茂密丛林，占据了东部王国南端，位于暮色森林以南。这片雨林曾是伟大的古拉巴什帝国的所在地，如今却散布着崩塌的巨魔遗迹、凶猛的野兽，以及由地精、海盗和士兵建立的互相竞争的营地。当地的巨魔部落、荆棘谷地精...",kw={"血帆海盗","藏宝海湾","格罗姆高","古拉巴什","库尔森","奈辛瓦里","里维加兹","荆棘谷","荆棘谷地精","祖尔格拉布"},ang={["class:Hunter"]="北部的河岸是著名的大型狩猎猎人赫米特·奈辛瓦里的住所，他向神枪手们发出挑战，考验他们在追踪丛林中最凶猛的迅猛龙、豹子和鳄鱼时的勇气。",["faction:Alliance"]="暴风城历史上为征服和安抚这片丛林所做的努力使王国背负了沉重的债务，如今其利益只能由反抗军营地中疲于奔命的叛变者来捍卫。",["faction:Horde"]="格罗姆高营地为部落提供了南方大陆上一个不可或缺的战略据点，直接由来自杜隆塔尔和幽暗城的飞艇提供补给。",["profession:Herbalism"]="潮湿的树冠孕育了珍贵的植物，使得河岸和海岸线成为采集野钢花、枯叶草、金棘草和紫莲花的理想狩猎场。",["race:Troll"]="荆棘谷是丛林巨魔的祖源之地，其古老的古拉巴什帝国在崇拜夺灵者哈卡后因内战而灭亡，迫使暗矛等部落跨越了海洋。"},sec={{t="帝国的遗迹",b="几千年来，这片山谷一直由强大的古拉巴什帝国从其首都祖尔格拉布进行统治。当激进的祭司召唤了夺灵者哈卡，导致该地区陷入灾难性的内战时，这一统治便瓦解了。尽管赞达拉介入并镇压了鲜血之神的起义，但帝国已支离破碎，无法修复。如今，丛林被交战的继承派系所淹没——最著名的是西北部的血顶和东部的裂颅者——双方都在狂热地屠杀外来者，以夺回他们的祖居之地。"},{t="海盗与投机者",b="在古老的遗迹陷入沉寂的地方，商业贪婪填补了空白。南端坐落着藏宝海湾，这是一个由热砂港建立的繁忙避风港，由大财主里维加兹领导的黑水海盗运营。该港口是南方商业和海运的主要枢纽，尽管它一直受到沿岸驻扎的敌对血帆海盗的围攻。在内陆深处，荆棘谷地精正大肆剥削丛林中的木材，并在山丘中开采稀有的歌唱水晶。"},{t="充满纷争的荒野",b="荆棘谷是世界上最动荡的边境地区之一。部落在西海岸掌控着格罗姆高营地，通过地精飞艇与杜隆塔尔和提瑞斯法林地相连；而联盟的忠诚者则在反抗军营地开展行动，追踪叛变的库尔森上校。在茂密的树叶间，传奇猎人赫米特·奈辛瓦里领导着大胆的大型狩猎探险队，吸引着流浪者们与潜行的豹子、巨大的猿猴以及敌方士兵进行危险的遭遇战。"},{t="丛林中的疯狂",b="北荆棘谷的威胁并非全是野兽。曾是一名受暴风城派遣的功勋指挥官的库尔森上校，在灌木丛中陷入疯狂，并建立了一个残暴的雇佣兵堡垒。事实上，库尔森的心智是受到了“心灵之眼”的诅咒，这是一件由附近的莫什奥格食人魔山中的食人魔术师迈佐斯所持有的神器，它驱使这支探险队陷入了彻底的疯狂，并促使他手下的士兵成立了分裂的反抗军营地。"}},faq={{q="谁在控制荆棘谷？",a="没有任何单一势力统治着这片山谷。丛林被血顶和裂颅者等敌对的丛林巨魔部落、库尔森的营地等流氓营地、雇佣兵性质的荆棘谷地精，以及零星分布的部落和联盟军事哨所瓜分。最大的城市定居点是中立的地精港口藏宝海湾，由大财主里维加兹和黑水海盗统治。",al={"谁拥有荆棘谷","谁统治荆棘谷","荆棘谷阵营"}},{q="什么是藏宝海湾？",a="藏宝海湾是一座建在荆棘谷海角南面悬崖上的庞大港口城市。它最初是一个被称为黑水湾的人类定居点，后来被巨魔占领，最终被热砂港所掌控。如今，大财主里维加兹和舰队指挥官卡拉·海角将其作为连接旅行者与无尽之海对岸棘齿城的中立贸易港口进行运营。",al={"什么是藏宝海湾","藏宝海湾港口","谁管理藏宝海湾"}},{q="库尔森上校为何叛变？",a="库尔森上校代表暴风城领导了一支深入丛林的探险队，但他的心智受到了迈佐斯的控制，这是一个持有名为“心灵之眼”强大圣物的食人魔术师。库尔森变得越来越反复无常和专横，迫使多伦上尉等忠诚的士兵脱离队伍并组建了反抗军营地来阻止他。",al={"为什么库尔森是邪恶的","库尔森发生了什么","库尔森背景故事"}},{q="什么是祖尔格拉布？",a="祖尔格拉布是古拉巴什帝国那座古老且遍布神庙的首都，坐落在北荆棘谷。它是十五个世纪前终结帝国的内战中心，当时激进的祭司召唤了鲜血之神夺灵者哈卡。尽管这里早已被藤蔓和废墟所吞没，但黑暗的仪式仍在威胁着它的大厅。",al={"什么是祖尔格拉布","祖尔格拉布历史","古拉巴什首都"}},{q="什么是海潮之石？",a="海潮之石是一件来自古拉巴什历史的传奇圣物，由一名巨魔战士在海岸上发现。它赋予持有者支配水元素和召唤元素的能力，如同强大的法师一般，因此持有者被称为“潮汐使者”。然而，它带有诅咒，会导致持有者从物理层面缓慢消失，最终使每一任持有者都走向大海并销声匿迹。",al={"海潮之石","潮汐使者传说","古拉巴什海潮之石"}},{q="我该如何前往荆棘谷？",a="旅行者可以从暮色森林越过河流边界向南走进北荆棘谷。部落维持着直接连接格罗姆高营地与杜隆塔尔和提瑞斯法林地的飞艇塔。来自卡利姆多的旅行者也可以搭乘往返于贫瘠之地的棘齿城与藏宝海湾之间的定期商船。",al={"如何前往荆棘谷","前往荆棘谷的方法","荆棘谷旅行"}}},fp="18,166,18.455.0,22.346.0,22.414.0,25.340.1,32.270.0,18.322.0,32.268.1,18.294.0,32.328.0,38.256.0"}
P.entries["zone:swampofsorrows"] = {n="悲伤沼泽",s="悲伤沼泽是一片阴暗、咸涩的湿地，坐落在逆风小径和干旱的诅咒之地之间。这里曾经是古老的黑色沼泽的北部区域，其盐分结块的泥沼中栖息着危险的野生生物、绿龙人，以及沉没在泪水之池下方的阿塔哈卡神庙废墟。虽然部落在斯通纳德维持着一座加固的要塞，但联盟在沼泽中没有任何避难所，这使得这片荒野大部分处于未开发状态。",h="悲伤沼泽是一片阴暗、咸涩的湿地，坐落在逆风小径和干旱的诅咒之地之间。这里曾经是古老的黑色沼泽的北部区域，其盐分结块的泥沼中栖息着危险的野生生物、绿龙人，以及沉没在泪水之池下方的阿塔哈卡神庙废墟。虽然部落在斯通纳德维持着一...",kw={"黑色沼泽","破碎者","避难营","失落者","泪水之池","忧伤湿地","斯通纳德","沉没的神庙","悲伤沼泽","阿塔哈卡神庙"},ang={["faction:Alliance"]="没有前哨站作为后盾，穿越沼泽是一次孤立且充满敌意的冒险，需要从夜色镇或守望堡做好充分的准备。",["faction:Horde"]="斯通纳德是你在这片大陆南部重要的前进据点，拥有通往卡加斯、烈焰峰、格罗姆高营地、藏宝海湾以及河林中的洛格玛的直达双足飞龙航线。",["profession:Blacksmithing"]="强大的冒险者可以在沼泽北部和南部边缘的山岩间采集铁矿、金矿、秘银矿和真银矿。",["profession:Herbalism"]="沼泽是艾泽拉斯为数不多盛产盲目草的地方之一，此外还有大量生长的活根草、枯叶草和荆棘藻。",["race:Troll"]="沉没的阿塔哈卡神庙废墟是一个严峻的提醒，警示着那段导致古拉巴什帝国分裂并招致龙王愤怒的黑暗血魔法。"},sec={{t="被淹没的历史",b="在兽人部落到来之前很久，这些沼泽地就构成了被称为黑色沼泽的巨大湿地的北半部。在古拉巴什帝国分崩离析后，狂热的阿塔莱巨魔逃入泥沼，建造了阿塔哈卡神庙，企图召唤他们嗜血的洛阿神——“夺灵者”哈卡。伊瑟拉察觉到了这场灾难，于是释放了自己的力量，将这座被诅咒的金字塔淹没在泪水之池的水底。伊兰尼库斯率领的绿龙军团守卫被派驻于此，警惕地看守着这座沉没的建筑。当后来黑暗之门的灾难将南部的沼泽烧灼成诅咒之地时，这片北部的沼泽便获得了它现在这个悲伤的名字。"},{t="前哨站与破碎者流亡者",b="斯通纳德是沼泽中主要的文明立足点。该前哨站最初建立于第一次战争期间，与现已废弃的洛格玛和Kyross定居点并存，后来在萨尔的领导下重建，作为部落在东部王国最南端的补给站。在斯通纳德的木栅栏之外，一些奇怪的漫游者在沼泽中游荡。一群滞留在艾泽拉斯的德莱尼流浪者屈服于思乡之情和疯狂，退化成了野蛮的失落者。然而，一小群神智清醒的破碎者流亡者在避难营坚持了下来，他们保持警惕，但愿意与旅行者和平交易。"},{t="沉没的泥沼",b="在沼泽中生存需要时刻警惕那些掠食性的野生生物。深不见底的泥沼中隐藏着伺机扑咬的鳄鱼、剧毒蜘蛛、潜行的沼泽美洲豹，以及身上覆盖着沼泽碎屑的游荡沼泽兽。沿海洞穴和芦苇海滩上爬满了凶残的鱼人，而含盐的潮水不断向内陆蔓延，将腐烂的圆木包裹在厚厚的盐壳中。再往东是忧伤湿地，那里好战的精英龙人严密守卫着通往沉没的神庙的入口，攻击任何靠近他们警戒范围的人。"}},faq={{q="如何到达悲伤沼泽？",a="最常见的陆路路线是从暮色森林的夜色镇向东出发，穿过危险的逆风小径闹鬼峡谷，直下进入沼泽。或者，来自南方的旅行者可以沿着诅咒之地出来的主路向北走。",al={"如何前往悲伤沼泽","悲伤沼泽路线","如何到达斯通纳德"}},{q="为什么阿塔哈卡神庙在水下？",a="几个世纪前，阿塔莱祭司试图在艾泽拉斯召唤“夺灵者”哈卡。绿龙军团的龙王伊瑟拉发现了他们邪恶的血祭，为了避免灾难，将整个神庙淹没在泥沼中，并留下绿龙人守卫着这些沉没的大厅。",al={"为什么沉没的神庙会沉没","是谁淹没了神庙","沉没的神庙背景故事"}},{q="斯通纳德是什么？",a="斯通纳德是兽人部落在第一次战争期间穿过黑暗之门后建立的第一批定居点之一。虽然在战斗中遭受了破坏，但最近在萨尔的命令下被收复并重建，以巩固部落在诅咒之地附近的后勤保障。",al={"斯通纳德历史","沼泽中的兽人基地","谁建造了斯通纳德"}},{q="这里有联盟的定居点吗？",a="没有。联盟在悲伤沼泽没有城镇、卫兵或飞行点。在此区域活动的联盟冒险者必须以西部的暮色森林夜色镇或南部的诅咒之地守望堡作为基地。",al={"悲伤沼泽的联盟基地","悲伤沼泽的联盟飞行点","联盟营地在哪里"}},{q="沼泽里那些奇怪的变异类人生物是谁？",a="他们是黑暗之门崩溃后滞留在艾泽拉斯的德莱尼人。由于与他们的世界隔绝，大多数人因绝望而发疯，变成了充满敌意的失落者。一小群神智清醒的破碎者流亡者在西北部的避难营避难，选择了中立生存，而非盲目的狂怒。",al={"谁是失落者","避难营是什么","沼泽里的德莱尼人"}},{q="忧伤湿地是什么地方？",a="忧伤湿地是泪水之池正东面的一片茂密沼泽地。它是精英绿龙人和幼龙的巡逻区，它们会暴力驱逐凡人，以保卫沉没的神庙的秘密。",al={"悲伤沼泽的龙类区域","忧伤湿地的龙","悲伤沼泽的绿龙人"}}},fp="16,249,17.556.0,26.487.0,16.475.0,36.188.0,44.259.0,16.248.0,40.179.0,51.307.0,19.185.0"}
P.entries["zone:tanaris"] = {n="塔纳利斯",s="塔纳利斯是一片广袤、炎热的沙漠，横跨卡利姆多南部，以起伏的沙丘和灼人的热浪而闻名。沙漠中心坐落着加基森，这是一个由热砂港地精运营的中立贸易前哨站。在繁华的定居点之外，沙丘中隐藏着充满敌意的沙怒巨魔、危险的其拉虫巢，以及青铜龙军团的隐秘领地。",h="塔纳利斯是一片广袤、炎热的沙漠，横跨卡利姆多南部，以起伏的沙丘和灼人的热浪而闻名。沙漠中心坐落着加基森，这是一个由热砂港地精运营的中立贸易前哨站。在繁华的定居点之外，沙丘中隐藏着充满敌意的沙怒巨魔、危险的其拉虫巢，以及青...",kw={"时光之穴","沙漠","海盗","加基森","诺兹多姆","沙怒","其拉虫人","热砂港","塔纳利斯","奥丹姆","祖尔法拉克"},ang={["faction:Alliance"]="由于尘泥沼泽和菲拉斯之间没有主要的联盟据点，位于中立加基森的联盟飞行管理员成为了穿越卡利姆多南部的关键中转站。",["faction:Horde"]="加基森为部落侦察兵提供了一个便利的贸易枢纽，将乱风岗和莫沙彻营地的路线直接连接到远南地区虫群肆虐的荒野。",["profession:Herbalism"]="干燥的热浪滋养着变幻沙丘中难以捉摸的火焰花，而阴凉的废墟和潮湿的绿洲则为珍贵的紫莲花提供了庇护所。",["profession:Mining"]="围绕着沙丘的干旱悬崖和岩石露头蕴藏着丰富的秘银、真银、铁矿和金矿，在更深处还有零星的瑟银矿脉。",["race:Troll"]="看到祖尔法拉克的沙怒巨魔，巨魔们可以直观地审视他们古老的同族，这些同族在沙漠的与世隔绝中演变成了一种残酷的文化。"},sec={{t="沙丘之海",b="塔纳利斯是一片荒芜、被烈日灼烤的荒野。在祖尔法拉克的城墙内，强悍的沙怒巨魔守卫着他们与世隔绝的领地。如今，这片沙漠遍布鬣狗、蛇颈龙和蝎子，而干裂的土地之下盘根错节地蜿蜒着地下隧道。"},{t="地精企业",b="由于塔纳利斯在地理位置上是大陆范围内最接近地精故乡科赞的地方，热砂港在此建立了一个繁荣的企业。从围墙环绕的加基森绿洲到沿海的热砂港码头，地精们维持着严格的中立政策，无论联盟还是部落的钱币他们都来者不拒。他们的和平由身强力壮的保镖维持，尽管像南海海盗这样的流氓势力经常骚扰海岸沿线的航运和挖掘点。"},{t="远古之谜与日益增长的威胁",b="流沙掩盖着比凡人帝国古老得多的力量。在东部边缘坐落着时光之穴，那是诺兹多姆及其青铜龙军团的祖居之地，偶尔能看到他们的巨龙在沙漠的热浪中翱翔。向南望去，巨大的石门标志着泰坦建筑群奥丹姆的所在。然而，一种更黑暗的危险正从大裂口和腐化之巢等地下巢穴中蠢蠢欲动，那里不断爬出的其拉虫群已经开始在沙地上四处蔓延。"}},faq={{q="我该如何前往塔纳利斯？",a="旅行者可以从千针石林徒步前往闪光平原。在盐碱平原南端的悬崖上开凿出一条山口，直接通向沙漠，带你立即进入加基森的城墙视野内。此外，还有一艘船从河林镇的爆破引线港出发，驶向东海岸的热砂港。",al={"如何前往塔纳利斯","前往塔纳利斯","塔纳利斯入口"}},{q="为什么加基森对两个阵营都保持中立？",a="加基森由热砂港管理，该组织唯一的忠诚对象就是利益。为了最大化商业利润并保护穿越沙漠的贸易路线，地精们强制执行严格的中立政策，雇佣保镖来教训那些蠢到在城墙内挑起阵营争斗的人。",al={"加基森为什么是中立的","部落和联盟能去加基森吗","地精中立加基森"}},{q="什么是祖尔法拉克？",a="祖尔法拉克是沙怒巨魔加固过的沙漠之都。沙怒部族长期与世隔绝地生活在沙漠中，变得对所有外来者充满敌意，他们守护着圣池和神秘的神龛，防止冒险者入侵。",al={"什么是祖尔法拉克","谁住在祖尔法拉克","沙怒巨魔城市"}},{q="沙漠中筑巢的虫型生物是什么？",a="这些昆虫般的野兽是其拉虫人，一种可怕的群体性掘地生物，它们建造了如大裂口和腐化之巢这样巨大的巢穴。它们在塔纳利斯的出现让高级勘探员菲兹杜瑟等观察者感到不安，令人回想起流沙之战时期的远古恐怖。",al={"塔纳利斯的虫子是什么","塔纳利斯虫巢","塔纳利斯的其拉虫人"}},{q="南部的巨大石门后面是什么？",a="守卫之谷中的不朽之门标志着奥丹姆的入口，这是一座传说中的泰坦研究设施和据点。入口至今依然紧闭，由巨大的石像守卫着，并受到好奇的学者和地精从远处的监视。",al={"塔纳利斯南部的巨门","奥丹姆遗迹之门","泰坦之门塔纳利斯"}},{q="谁居住在时光之穴内？",a="时光之穴是青铜龙军团及其龙王诺兹多姆的祖居巢穴。在这隐秘而蜿蜒的深处，永恒的巨龙监视着历史的流动，偶尔会在南部沙丘的高空进行巡逻。",al={"时光之穴背景故事","时光之穴里有什么","塔纳利斯的巨龙"}}},fp="7,203,14.233.0,17.333.0,35.335.0,27.288.0,42.224.0,19.175.0,56.255.0,52.219.0,38.232.0"}
P.entries["zone:teldrassil"] = {n="泰达希尔",s="泰达希尔，意为“大地的王冠”，是一株矗立在卡利姆多西北海岸外的巨大世界之树。它由德鲁伊们在第三次战争后培育而成，其巨大的枝干支撑着整片暮色荒野以及暗夜精灵的首都达纳苏斯。然而在它宁静、月光笼罩的树冠之下，一股潜滋暗长的腐蚀力量已开始躁动。",h="泰达希尔，意为“大地的王冠”，是一株矗立在卡利姆多西北海岸外的巨大世界之树。它由德鲁伊们在第三次战争后培育而成，其巨大的枝干支撑着整片暮色荒野以及暗夜精灵的首都达纳苏斯。然而在它宁静、月光笼罩的树冠之下，一股潜滋暗长的腐...",kw={"上古议会","大地之冠","达纳苏斯","多兰纳尔","范达尔·鹿盔","鲁瑟兰村","幽影谷","泰达希尔","世界之树"},ang={["class:Druid"]="由于玛法里奥被困在翡翠梦境中，大德鲁伊范达尔·鹿盔在此领导着塞纳里奥议会，尽管许多德鲁伊担心泰达希尔是在仓促之中培育出来的。",["faction:Alliance"]="泰达希尔是联盟在卡利姆多最北端的堡垒，作为达纳苏斯与内陆王国之间海军通信和贸易的枢纽。",["profession:Herbalism"]="这里完全没有矿物和矿石，但大树翠绿的树冠弥补了这一点，使之成为宁神花、银叶草和地根草采集者的天堂。",["race:NightElf"]="这棵巨大的树是你的人民在海加尔山遭到破坏后的新起点，但守护巨龙祝福的缺失使得保卫它成为了一项紧迫的职责。"},sec={{t="海上的树冠",b="泰达希尔不仅是一棵树，它还是一个高耸在迷雾之海上的生态系统。其巨大的枝干支撑着起伏的丘陵、晨露汇聚而成的河流、雾气缭绕的湖泊以及茂密的古老林地。在它的西侧坐落着卡多雷的宏伟首都达纳苏斯。在它那如丰碑般的树干底部则是鲁瑟兰村，它通过一扇神秘的传送门与上方的树冠相连，是岛上的主要港口。"},{t="守护巨龙的拒绝",b="随着第三次战争中诺达希尔的牺牲，以及珊多玛法里奥·怒风在翡翠梦境中的神秘失踪，大德鲁伊范达尔·鹿盔说服了上古议会培育了一棵替代之树。鹿盔希望能以此让卡多雷恢复他们失去的永恒寿命。然而，诺兹多姆和守护巨龙们认为这种行为过于傲慢，并拒绝给予祝福。由于缺乏这至关重要的守护力量，泰达希尔的生长出现了一些非自然的缺陷。"},{t="潜滋暗长的病痛",b="尽管外表宏伟，但这株新生世界之树却隐藏着一种恶疾。当地的野生生物变得极具攻击性：温顺的熊怪部落陷入了疯狂，扭曲的格雷尔在兽穴中繁衍，邪恶的萨特如同在地狱石一般，在阴影中进行着黑暗仪式。而在下方的黑海岸沿岸，海巨人、礁鲨和海龟纷纷搁浅，逃离这株大树周围被污染的水域。自然学家和哨兵们现在正焦急地在枝干间奔波，试图找出那股正缓慢扼杀他们新家园的阴影。"}},faq={{q="为什么要种植泰达希尔？",a="在第三次战争末期诺达希尔遭到破坏后，暗夜精灵失去了永恒寿命。大德鲁伊范达尔·鹿盔推动上古议会和塞纳里奥议会的德鲁伊们在海上种植了一株新的世界之树，旨在恢复他们族人失去的东西。",al={"为什么要种植","谁种植了泰达希尔","泰达希尔的起源"}},{q="为什么泰达希尔没有恢复暗夜精灵的永恒寿命？",a="诺达希尔最初之所以能赋予永恒，是因为“永恒者”诺兹多姆祝福了它。当泰达希尔被培育出来时，诺兹多姆认为暗夜精灵的这种欲望过于傲慢，因此拒绝将他的祝福给予这棵新树。",al={"永恒寿命","为什么没有永恒","诺兹多姆的祝福"}},{q="怎样离开泰达希尔？",a="旅行者必须穿过达纳苏斯，前往神殿花园中的粉色传送门，它会将你传送到底部树干的鲁瑟兰村。从鲁瑟兰村出发，除了可用的角鹰兽航线外，还有船只航行穿过海洋前往黑海岸的奥伯丁。",al={"如何离开","离开大树","泰达希尔的船"}},{q="为什么泰达希尔没有采矿矿点？",a="整个区域位于巨大的世界之树的活体枝干和木材之上，而非天然的大陆岩石上。由于没有石质的地下地壳，因此不会形成金属矿脉或矿藏，不过这里盛产大量的草药。",al={"铜矿在哪里","没有矿石","泰达希尔采矿"}},{q="是什么导致熊怪和野兽变得疯狂？",a="一股邪恶的气息已经开始渗入泰达希尔那未经祝福的根系。病痛污染了当地的水源和植物，驱使温顺的树木生物和蓟皮熊怪部落陷入疯狂的攻击性状态，而残留的萨特则在积极培养这种污染。",al={"堕落的熊怪","蓟皮熊怪疯狂","什么是腐蚀"}},{q="什么是幽影谷？",a="幽影谷是位于泰达希尔东侧枝干上的一处受保护的隐蔽山谷，环绕着巨树奥达希尔。这是一个宁静的圣所，年轻的暗夜精灵在前往外面的世界闯荡之前，会在这里开始他们的训练。",al={"幽影谷","出生区域","奥达希尔区域"}}},fx={["11a6d5e5"]={q="泰达希尔是什么地方？",a="泰达希尔是一棵巨大的世界之树，生长在卡利姆多西北海岸外的一座岛屿上。它庞大的树干从迷雾之海中拔地而起，伸展出广阔无比的枝桠，托起树冠上遍布湖泊、河流的整片森林国度，以及首都达纳苏斯。",al={"这是什么地方","关于泰达希尔","泰达希尔介绍"}},["313cd5a2"]={q="泰达希尔发生过什么？",a="第三次大战结束、海加尔山的诺达希尔遭到重创后，德鲁伊玛法里奥·怒风失踪了。在他不在的这段时间里，大德鲁伊范达尔·鹿盔说服古树议会培育一棵新的世界之树，弥补失去的一切。虽然新树成功长成，一股悄然蔓延的腐化却已开始侵染它的枝桠。",al={"泰达希尔历史","泰达希尔是如何诞生的","泰达希尔发生的事件"}},c5e34e84={q="谁居住在泰达希尔，又是谁在管理这里？",a="泰达希尔是暗夜精灵一族的庇护所，也是他们如今的家园。女祭司泰兰德·语风和大德鲁伊范达尔·鹿盔在首都达纳苏斯引领族人的信仰与政务，艾露恩姐妹会、塞纳里奥德鲁伊和守卫林间聚落的哨兵战士则为他们提供支持。",al={"谁领导泰达希尔","泰达希尔领袖","谁住在这里"}},b86e706e={q="泰达希尔危险吗？",a="虽然有哨兵保护，泰达希尔却正变得越来越危险。一种黑暗的病症令当地野兽和熊怪陷入疯狂，而邪恶的萨特、嗜血的鹰身人和肆虐的林精，则威胁着巡逻大道之外的聚落。",al={"这里安全吗","泰达希尔的威胁","泰达希尔的危险"}},["2863bed2"]={q="为什么叫泰达希尔？",a="在暗夜精灵的达纳苏斯语言中，泰达希尔的字面意思是“大地之冠”。这个名字彰显了它作为宏伟世界之树的使命：承载并庇护他们的文明。",al={"泰达希尔是什么意思","泰达希尔名字的含义"}},["514d23b0"]={q="范达尔·鹿盔是谁？",a="范达尔·鹿盔是一位大德鲁伊，在玛法里奥·怒风进入翡翠梦境并失踪后，接掌了暗夜精灵德鲁伊的领导权。范达尔热忱、固执而强硬，曾力主种下泰达希尔，也经常在政见上与女祭司泰兰德·语风发生冲突。",al={"大德鲁伊是谁","范达尔·鹿盔的故事","鹿盔"}},["52c333ac"]={q="泰兰德·语风是谁？",a="泰兰德·语风是女神艾露恩的高阶女祭司，也是暗夜精灵一族的最高领袖。她引领族人走过了漫长的守望和第三次大战，历经一万年，如今在达纳苏斯的月神殿领导他们。",al={"泰兰德是谁","女祭司泰兰德","谁领导暗夜精灵"}},["29b1e9e4"]={q="我是怎么来到泰达希尔的？",a="如果你是暗夜精灵，这棵庞大的世界之树就是你族人的新家园。为了击败燃烧军团，卡多雷在海加尔山顶牺牲了诺达希尔和古老的永生之力，随后迁居到卡利姆多西北海岸之外。大德鲁伊范达尔·鹿盔和古树议会在迷雾之海中培育了泰达希尔，为你的种族提供新的庇护所，而你的旅程便从它苍翠枝桠间的幽影谷开始。如果你从外地来到这里，那么你很可能从黑海岸乘船抵达树根处的鲁瑟兰村港口，再踏入发光的传送门，直接前往树冠。",al={"怎么来到泰达希尔的","怎么来到这里的","为什么从这里开始"}},["8381279f"]={q="我在泰达希尔该做些什么？",a="你肩负着守护这棵年轻世界之树的使命，并要查明扰乱其枝桠的黑暗病症。尽管森林郁郁葱葱，一股邪恶的腐化却正在扎根：林精变得充满攻击性，瘤背部族原本温和的熊怪逐渐陷入疯狂，卑劣的萨特则潜伏在地狱石等阴暗的林丛中。你从幽影谷出发，援助多兰纳尔等聚落，必须帮助哨兵和德鲁伊恢复平衡。你将补充神圣月亮井的井水、清除受到腐化的害兽，并了解自己族人的历史，然后前往首都达纳苏斯，再渡海踏上卡利姆多大陆。",al={"在泰达希尔做什么","为什么在这里","在这里的使命是什么"}}},fp="10,168,21.379.0,26.466.0,17.410.1,25.260.0,52.182.0,28.253.0,44.210.0,52.248.0,19.205.0"}
P.entries["zone:thousandneedles"] = {n="千针石林",s="千针石林是位于卡利姆多南部的一片广袤峡谷，布满了陡峭的砂岩石柱和被烈日炙烤的盐碱滩。牛头人部族依靠高耸台地之上的定居点来躲避凶猛的半人马部族，而侏儒和地精技师们则在闪光平原干涸的海床上驾驶高速火箭车飞驰。",h="千针石林是位于卡利姆多南部的一片广袤峡谷，布满了陡峭的砂岩石柱和被烈日炙烤的盐碱滩。牛头人部族依靠高耸台地之上的定居点来躲避凶猛的半人马部族，而侏儒和地精技师们则在闪光平原干涸的海床上驾驶高速火箭车飞驰。",kw={"峭壁卫兵图林·长角","黑云峰","菲兹尔·铜栓","乱风岗","升降梯","图腾部族","克拉维尔·浓须","沙漠赛道","普兹克","闪光平原","千针石林"},ang={["faction:Horde"]="升降梯将贫瘠之地与你位于乱风岗的据点连接起来，作为抵御半人马部族和叛乱牛头人的战略南部边界。",["profession:Engineering"]="盐碱滩是技师们的朝圣之地，他们来到沙漠赛道研究火箭燃料、车辆零件和高速推进技术。",["race:Gnome"]="位于闪光平原的沙漠赛道是你所在阵营展示侏儒工程学的精确与优雅，并超越劣质地精装置的最佳机会。",["race:Tauren"]="乱风岗不仅提醒着你的族人当初为了逃避半人马的屠杀而攀登到了怎样的高度，也成为了抵御黑云峰那些背信弃义的图腾部族的阵地。"},sec={{t="石之林",b="在大分裂彻底粉碎古卡利姆多之前，这片土地曾是一条郁郁葱葱的河谷，内陆水道在此汇流并奔向大海。大灾变撕裂了这块大陆，将河床抬升至水位线以上，并改变了河流的走向，最终只留下了干燥的岩石和砂岩尖塔。如今，几十根细长的圆柱形石柱从峡谷底部拔地而起，宛如一片石化的森林。牛头人们在峰顶定居，并在山峰间架设起摇摇欲坠的绳桥，以此建立起避开下方阴影笼罩的峡谷中游荡的敌对半人马劫掠者的村庄。"},{t="台地上的危机",b="在针状的尖塔之上，生活远非平静。在乱风岗，效忠于部落的牛头人不仅要面对来自风巢的捕食者风蛇和双足飞龙，还要对抗他们那背信弃义的族人：盘踞在黑云峰的激进图腾部族。峭壁卫兵图林·长角负责监督高原的防御工作，并寻找勇士打击图腾部族的煽动者，以确保连接山峰的脆弱桥梁安全。在北部，巨大的升降梯利用机械绞盘将旅客从南贫瘠之地运送下来，但穿越峡谷底部仍然是一场致命的赌博。"},{t="沙漠赛道",b="向东南方望去，峡谷的岩壁逐渐退去，露出了闪光平原，那是一片位于海平面以下的巨大干涸盐碱滩。在这片严酷、耀眼的白色荒原上，侏儒和地精在沙漠赛道周围维持着一种微妙的中立关系。敌对工程师普兹克和菲兹尔·铜栓驾驶着试验性火箭车在坚硬的盐地上竞速，以此决出哪个种族拥有更高的科技优势。这个维修站吸引了恶棍、像克拉维尔·浓须那样的诈骗犯，以及在此捕猎那些徘徊在炙热盆地中的顽强蝎子、海龟和蛇颈龙的猎人们。"}},faq={{q="千针石林是如何得名的？",a="该地区得名于从峡谷底部突出的数十座巨大的圆柱形砂岩尖塔。它们最初是在大分裂之前由湍急的河水冲刷而成，如今这些地质塔楼看起来就像一片巨大的针林。",al={"为什么叫千针石林","石柱起源","尖塔背景"}},{q="如何从贫瘠之地进入千针石林？",a="旅客可以搭乘升降梯，这是一座由位于贫瘠之地南部的部落卫兵运营的巨大双轿厢电梯。从边缘跳下去是致命的，所以必须耐心等待平台的到来。联盟旅客也可以从西部的菲拉斯经萨兰纳尔徒步进入。",al={"如何前往千针石林","升降梯入口","千针石林电梯"}},{q="为什么牛头人住在台地上？",a="半人马战团曾一度将游牧的牛头人逼近灭绝的边缘。在难以企及的石柱顶端建立乱风岗这样的哨所，使他们免受地面袭击。他们使用木制吊桥将台地连接起来，从而能够在那些捕食者和劫掠者上方进行高空通行。",al={"为什么牛头人在石柱上","乱风岗历史","牛头人高地"}},{q="什么是沙漠赛道？",a="沙漠赛道是闪光平原盐碱滩上的一个工程试验场。侏儒和地精技师们驾驶着试验性火箭赛车在平坦的盐床上飞驰，以解决他们之间关于哪个种族能制造出最精良机械的长期竞争。",al={"盐碱滩赛道","侏儒地精竞速","火箭车赛道"}},{q="图腾部族在峡谷中有哪些势力？",a="图腾部族占据了黑云峰，那是一群直接与乱风岗对峙的强化尖塔。与誓忠部落的其他牛头人部族不同，图腾部族不仅积极攻击其他牛头人，还密谋夺取对这些台地的统治权。",al={"千针石林的图腾部族","黑云峰牛头人","邪恶牛头人"}},{q="什么是闪光平原？",a="闪光平原是峡谷台地以东一片广阔的干涸湖床。这里的盐壳形成于大分裂后古代内陆海蒸发之时。炙热的高温、耀眼的白色盐滩以及凶猛的捕食者使其成为一片荒凉的沙漠，主要用于高速车辆测试。",al={"盐碱滩","白色沙漠","东部沙漠"}}},fx={d1fb42e2={q="千针石林是什么地方？",a="千针石林是一道广阔干旱的峡谷，将卡利姆多中部与南部隔开。峡谷底部遍布高耸的砂岩石柱，宛如一片石化森林直插云霄，石柱上方由纤细的绳索和木桥相连。峡谷东侧延伸为闪光平原，一片刺眼的白色盐碱地。",al={"这是什么地方","关于千针石林","介绍一下千针石林"}},["98fcff4e"]={q="这里为什么全是峡谷和石柱？",a="远古时期，在大分裂之前，这里曾是一道葱郁的河谷，由从菲拉斯向东奔流、注入内海的河水冲刷而成。世界破碎时，灾变将河床抬高并改变了河流的流向。土地失去水源后逐渐干涸，只留下高耸的砂岩石柱和干裂的盐床。",al={"为什么有这么多石峰","千针石林是怎么形成的","为什么有砂岩石柱"}},["05d5c74f"]={q="千针石林危险吗？",a="这里相当危险。野蛮的加拉克半人马成群巡逻峡谷底部，掠食性的秃鹫、蝎子和离群 鹰身人 则出没于峭壁之间。穿梭于高耸石峰之间的绳桥也危机四伏，猛禽经常俯冲袭击毫无防备的旅人，或损坏桥梁。",al={"千针石林有多危险","这里有什么危险","这里安全吗"}},["1b8e8bea"]={q="部落为什么派我来千针石林？",a="部落在此维持重要据点，以帮助遭受持续袭击的当地牛头人部族。乱风岗是连接贫瘠之地与南方沙漠的重要据点，部落需要勇敢的勇士击退劫掠成性的半人马，并平息内部威胁。",al={"部落在千针石林的任务","我为什么以部落身份来到这里","部落来这里做什么"}},a7c3b539={q="这里是牛头人的土地吗？",a="是的。千针石林荒芜的峡谷和高耸的台地，世世代代都是多个牛头人部族的祖居地。不过，在部落到来之前，凶残的半人马部族曾将他们逼至生存边缘。",al={"牛头人拥有千针石林吗","牛头人的领地","这是舒哈洛人的土地吗"}},fef8bf7c={q="乱风岗是什么地方？",a="乱风岗是部落在千针石林的主要据点。它建在高耸于谷底之上的巨大台地上，设有木制升降梯、飞行塔，以及通往附近石峰的悬索桥网络。",al={"乱风岗","什么是乱风岗","乱风村"}},["6ac472b0"]={q="加拉克半人马是什么人？他们为什么要攻击我们？",a="加拉克部族是当地的半人马，他们声称峡谷底部归其所有。和所有半人马一样，他们领地意识极强，四处游牧且凶狠残暴。他们会追杀所有经过峡谷的旅人，并企图彻底铲除牛头人聚居地。",al={"加拉克半人马","半人马为什么攻击","加拉克部族"}},["9f0b1de8"]={q="他们为什么憎恨牛头人？",a="牛头人与半人马之间的仇恨由来已久，难以化解。几代以来，半人马在卡利姆多的平原上四处游荡，以猎杀牛头人为乐，还发动残酷且无端的战争，迫使平和的部族不断逃亡。",al={"半人马为什么憎恨牛头人","半人马与牛头人的世仇","半人马的仇恨"}},["0eee4587"]={q="地精和侏儒为什么在沙漠里赛车？",a="闪光平原平坦开阔的盐地是测试高速引擎的理想场地。侏儒和地精在这里建起沙漠赛道，试图一劳永逸地解决由来已久的争论：究竟哪个种族的工程技术更胜一筹。",al={"为什么赛车","地精侏儒赛车","火箭车之争"}},e421f132={q="黑云峰和那些秘密信件是怎么回事？",a="黑云峰是邪枝部族在升降梯以东台地上的重兵把守的据点。在那里发现的秘密信件揭露了邪枝首领阿纳克·邪枝与某个未知黑暗势力的秘密联系，暗示他们怀有远超普通部族纷争的叛逆野心。",al={"黑云峰的信件","邪枝信件","黑云峰之谜"}},["7b560411"]={q="邪枝部族在谋划什么？",a="邪枝部族从根本上反对凯恩·血蹄的领导，以及加入部落带来的文化变迁。他们企图推翻凯恩，削弱部落的权威，甚至与邪恶势力勾结、召唤复仇实体，以巩固自己的统治。",al={"邪枝的计划","邪枝想要什么","邪枝阴谋"}},["853c4dd1"]={q="风巢是什么地方？我们为什么要收集双足飞龙蛋？",a="风巢是千针石林野生双足飞龙的祖传巢穴。乱风岗的牛头人会攀上这些高处，收集可孵化的双足飞龙蛋，悉心饲养并训练它们，让它们成为部落忠诚的飞行坐骑。",al={"风巢的双足飞龙","为什么收集双足飞龙蛋","风巢的蛋"}},dc3189d8={q="我怎么会来到千针石林？",a="大多数旅人从北方而来，沿贫瘠之地向南行进，经过陶拉祖营地，最终抵达陡峭的悬崖边缘，再乘坐牛头人建造的巨大升降梯直达峡谷底部。冒险者也可以从菲拉斯的茂密森林向东跋涉，徒步进入西侧峡谷；而敢于冒险的人则能穿越尘泥沼泽的险地，或乘船进入塞拉摩，再从有争议的通道穿行而来。从塔纳利斯的沙漠向北长途跋涉，也能直接抵达闪光平原广阔的盐碱地。",al={"我怎么来到这里","怎么去千针石林","前往千针石林"}},["16801326"]={q="我在千针石林该做些什么？",a="你在此地的目的取决于你的效忠对象和志向。部落勇士受命协助乱风岗：击退游荡在峡谷底部的加拉克半人马，监视 鹰身人 巢穴，从风巢收集双足飞龙蛋，并对付盘踞在黑云峰之巅的叛逆邪枝部族。对于没有结盟的流浪者和联盟旅人来说，这片壮阔的土地是穿越卡利姆多中部与南部的危险陆路要道，通向闪光平原；地精和侏儒的冒险家会在那里出高价收购零件、燃料，并寻求帮助，以延续他们永无休止的火箭车之争。",al={"我为什么在这里","我在这里的目的是什么","在千针石林做什么"}}},fp="16,179,17.529.0,18.553.0,18.535.0,38.222.0,59.251.0,43.279.0,27.248.0,45.235.0,30.284.0"}
P.entries["zone:thunderbluff"] = {n="雷霆崖",s="雷霆崖是牛头人宏伟的首都，坐落在莫高雷草原上方饱经风霜的红岩平顶山上。在得到新部落的援助并联合了各个游牧部落之后，大酋长凯恩·血蹄建立了这座城市，它成为了他的人民在文化、精神和商业上的中心。这座城市通过摇曳的绳桥和木制升降梯连接，为牛头人提供了躲避半人马掠夺者的安全场所，也是卡利姆多各地旅行者的一片宁静避难所。",h="雷霆崖是牛头人宏伟的首都，坐落在莫高雷草原上方饱经风霜的红岩平顶山上。在得到新部落的援助并联合了各个游牧部落之后，大酋长凯恩·血蹄建立了这座城市，它成为了他的人民在文化、精神和商业上的中心。这座城市通过摇曳的绳桥和木制升...",kw={"凯恩·血蹄","长者高地","升降梯","哈缪尔·符文图腾","猎人高地","玛加萨·野性图腾","莫高雷","预见之池","灵魂高地","雷霆崖"},ang={["class:Druid"]="长者高地是部落最高级的自然魔法圣地，由大德鲁伊哈缪尔·符文图腾领导，他是数千年来第一位接受教导的牛头人德鲁伊。",["class:Shaman"]="灵魂高地和地下的预见之池提供了一个宁静的枢纽，在那里，元素之灵和牛头人祖先的灵魂受到崇敬并被倾听。",["faction:Horde"]="比起奥格瑞玛严酷的城墙，雷霆崖更加宁静和具有灵性，它是新部落在卡利姆多南部影响力的田园基石。",["race:Tauren"]="雷霆崖代表了在大酋长凯恩·血蹄的领导下，你们的人民在历经几代游牧漂泊和半人马骚扰后，艰难赢得的团结与重生。"},sec={{t="永久的避风港",b="无数代以来，牛头人一直作为游牧民族在卡利姆多各地漂泊，为了生存，他们不得不与贪婪的半人马部落进行残酷的斗争。那个绝望的时代在第三次战争期间终结了，当时凯恩·血蹄与大酋长萨尔联合起来。兽人和牛头人共同击退了半人马的进攻，并保卫了莫高雷肥沃的草原。为了保护他们的未来，凯恩带领联盟部落来到了这些天然石垒的庇护所，并建立了雷霆崖，这是牛头人几个世纪以来拥有的第一个统一、永久的家园。"},{t="云端之城",b="雷霆崖横跨几座由悬挂绳桥连接的高耸平顶山，将自然建筑与牛头人的实用主义完美地融合在一起。中央平顶山设有繁忙的市场、银行、旅店和高耸的风骑士栖息地，而三座专业化的平顶山则横跨深渊向外延伸。猎人高地供城市的侦察兵和追踪者使用；长者高地接待着传说守护者和在大德鲁伊哈缪尔·符文图腾领导下的塞纳里奥议会；而灵魂高地则专供精神交流，为萨满祭司、牧师以及被称为预见之池的神秘地下洞穴提供了庇护。"},{t="不安的团结",b="虽然凯恩·血蹄在几乎所有部落中都享有极高的威望，但管理一个刚刚定居且引以为傲的民族并非没有摩擦。值得注意的是，由精明且言辞尖刻的年长巫婆玛加萨·野性图腾领导的恐怖图腾部族，在长者高地上保持着令人不安的存在感。玛加萨公开质疑凯恩的调和手段以及对部落异族盟友的忠诚。尽管在大酋长警惕的目光下和平得以维持，但在平原上方的议会之火中，意识形态的分歧仍在低语。"}},faq={{q="谁统治着雷霆崖？",a="大酋长凯恩·血蹄统治着雷霆崖，并领导着统一的牛头人部落。凯恩因其智慧、耐心和强大的力量而受到尊敬，他在与萨尔的部落结盟并将半人马赶出莫高雷后建立了这座城市。",al={"雷霆崖领袖","谁在掌权","雷霆崖大酋长","凯恩"}},{q="如何前往雷霆崖？",a="步行或骑乘科多兽抵达的访客必须乘坐位于中央平顶山西南部和东北部的巨大木制平台升降梯。此外，城市还设有风骑士栖息地，提供通往卡利姆多各地的飞行路线。",al={"雷霆崖升降梯","如何进入","雷霆崖入口","如何上去"}},{q="为什么牛头人要在高耸的平顶山上而不是地面上建造城市？",a="数个世纪的游牧生活以好战的半人马部落不断的打游击战为特征。莫高雷平顶山的悬崖提供了天然的防御，保护了牛头人的住所、铁匠和神圣的长者免受地面伏击，使他们能够永久地安居乐业。",al={"为什么选择平顶山","为什么在悬崖上","雷霆崖悬崖","牛头人高地"}},{q="这座城市有哪些不同的高地？",a="这座城市横跨一座中央平顶山（分为下层、中层和高层），周围环绕着三座外围平顶山。猎人高地专供战士、猎人和追踪小屋使用。长者高地是德鲁伊、智者和恐怖图腾阵营的家园。灵魂高地设有大地之母的神龛、萨满祭司、牧师和法师的训练师，以及洞穴状的预见之池。",al={"雷霆崖区域","什么是高地","雷霆崖街区"}},{q="什么是预见之池？",a="预见之池是隐藏在灵魂高地下方的神圣地下洞穴。牛头人先知、灵魂行者和奥术修行者聚集在这些宁静、雾气缭绕的水域中，与元素交流并解读有关他们人民未来的预兆。",al={"预见之池","灵魂高地洞穴","雷霆崖洞穴"}},{q="玛加萨·野性图腾是谁？",a="玛加萨·野性图腾是强大的恐怖图腾氏族的女族长和年长巫婆。虽然她居住在长者高地上，表面上参与凯恩的议会，但她极其保守，不信任外人，并悄悄地挑战血蹄部族对部落采取的温和立场。",al={"玛加萨","年长巫婆","恐怖图腾首领是谁"}}},fx={["6fa5b073"]={q="雷霆崖是什么地方？",a="雷霆崖是牛头人的首都，高踞于莫高雷北部劲风吹拂的台地之上。大酋长凯恩·血蹄与萨尔的部落一同击退半人马后建立了这座城市，为世代游牧的族人提供了安全、长久的庇护所。",al={"这是什么城市","雷霆崖介绍","雷霆崖城市"}},fc90632b={q="凯恩·血蹄是国王吗？",a="不是。凯恩·血蹄的头衔是联合牛头人各部族的大酋长。牛头人社会不加冕君王；凯恩的统治依靠他数十年来展现的智慧、力量以及由此赢得的深厚敬意，而非世袭王族的神授权力。",al={"凯恩·血蹄国王","凯恩是国王吗","牛头人国王"}},["047fa056"]={q="凯恩·血蹄听命于萨尔吗？",a="萨尔是部落的大酋长，但他与凯恩之间的纽带建立在相互尊重和盟约之上，而非严苛的臣属关系。凯恩出于感激和共同的愿景，带领族人宣誓加入部落，成为萨尔最信任的顾问之一，也是与他平等的盟友。",al={"凯恩听命于萨尔吗","萨尔是凯恩的上司吗","凯恩与萨尔"}},["85c1a10f"]={q="牛头人为什么加入部落？",a="在贫瘠之地各处，半人马掠夺者曾将游牧的牛头人逼到灭绝的边缘。当大酋长萨尔和兽人登陆卡利姆多时，他们帮助凯恩的族人打破半人马的围困，确保了莫高雷的安全，在两个民族之间缔结了牢不可破的纽带。",al={"为什么加入部落","牛头人与部落的盟约","牛头人如何加入部落"}},["3180b5ca"]={q="恐怖图腾部族是怎么回事？",a="恐怖图腾是一个凶悍好斗的氏族，由年迈的老妪玛加萨领导。与爱好和平的血蹄不同，他们对外来者深怀戒心，并公开质疑凯恩的和平领导方针，认为牛头人应当征服卡利姆多，驱逐其他种族。",al={"恐怖图腾部族","恐怖图腾是谁","恐怖图腾牛头人"}},ca8246e8={q="恐怖图腾是凯恩的敌人吗？",a="表面上，他们仍是统一的牛头人国度的一部分，玛加萨甚至就住在长者高地。然而暗地里，激烈的政治争斗始终未息，玛加萨不断策划阴谋，认定只有自己才拥有统治牛头人的正确远见。",al={"恐怖图腾是否邪恶","恐怖图腾反对凯恩","玛加萨与凯恩之争"}},["54829977"]={q="雷霆崖危险吗？",a="城内有英勇的卫兵维持秩序，保护居民免受下方平原上游荡的野兽和野猪人侵扰。对访客而言，眼前最大的危险是陡峭的落差——在台地边缘或木桥上稍有失足，就会丧命。",al={"雷霆崖是否安全","雷霆崖的威胁","这里的危险"}},["7db56847"]={q="我是怎么来到雷霆崖的？",a="如果你是年轻的牛头人，你的旅程始于南方红云台地上受到庇护的草原，途经血蹄村，最终来到这里。道路通往这些高耸台地的脚下，巨大的木制绳索升降梯会将旅人送上数百英尺的高空。而那些从卡利姆多各地远道而来的访客，往往乘坐双足飞龙，抵达崖顶中央的双足飞龙栖木。",al={"如何来到这里","如何来到雷霆崖","如何前往雷霆崖"}},["347b5cac"]={q="我在雷霆崖该做些什么？",a="雷霆崖是团结在一起的牛头人各部族的精神与文化中心。在这里，你可以向聚集在各处高地的资深萨满祭司、德鲁伊、猎人和战士寻求进阶训练。大酋长凯恩·血蹄和部族长老也仰赖有能力的勇士，保护莫高雷免受挥之不去的威胁——包括四处劫掠的半人马、步步侵占的荆棘谷地精、鹰身人和反叛的野猪人——随后再派你东行，迎接部落更广阔天地中的考验。",al={"在雷霆崖该做什么","为何来到这里","在这里的使命"}}},fp="13,326,17.466.0,20.453.0,12.391.1,24.277.0,35.194.0,61.212.0,41.395.0,29.239.0,25.233.0"}
P.entries["zone:tirisfal"] = {n="提瑞斯法林地",s="提瑞斯法林地是洛丹伦北部那片令人心悸的领土，如今是希尔瓦娜斯·风行者女士和被遗忘者的核心领地。在枯萎的天空和腐朽的枝桠之下，坐落着废弃的庄园、沉寂的墓穴，以及地底深处庞大的首都幽暗城。这里被毫无心智的天灾军团和狂热的血色十字军所包围，是一个充满危险的国度，拥有自由意志的亡灵在此艰难求生。",h="提瑞斯法林地是洛丹伦北部那片令人心悸的领土，如今是希尔瓦娜斯·风行者女士和被遗忘者的核心领地。在枯萎的天空和腐朽的枝桠之下，坐落着废弃的庄园、沉寂的墓穴，以及地底深处庞大的首都幽暗城。这里被毫无心智的天灾军团和狂热的血色...",kw={"阿加曼德","巴尼尔","布瑞尔","丧钟镇","被遗忘者","林地","洛丹伦","血色十字军","希尔瓦娜斯","提瑞斯法","幽暗城"},ang={["class:Priest"]="法奥之墓——白银之手创始人阿隆索斯·法奥大主教的陵墓——等具有历史意义的神圣之地也坐落于此，但它们已被死亡扭曲，并在狂热者和暗影牧师之间反复争夺。",["faction:Alliance"]="对于联盟的幸存国家来说，提瑞斯法是洛丹伦陷落的悲剧纪念碑，充满了曾经信仰相同的兄弟姐妹们那遭到亵渎的墓穴。",["faction:Horde"]="提瑞斯法是部落在东部王国北部的关键堡垒，它巩固了与被遗忘者的外交关系，同时抵御人类极端分子和天灾军团的侵袭。",["race:Undead"]="这是你双重的祖居之地：你生前所建立的王国，以及你在死后作为被遗忘者、在希尔瓦娜斯女士统治下必须誓死捍卫的危险避难所。"},sec={{t="暮色中的土地",b="提瑞斯法林地曾是人类文明繁荣的摇篮，但在巫妖王的瘟疫诅咒下已然凋零。阳光难得穿透昏暗的迷雾，给枯萎的树林、荒废的南瓜地以及冰冷的海岸丘陵笼罩上了一层病态的苍白。尽管阿加曼德磨坊和巴尼尔农场等古老的农庄遗迹尚存，但它们曾经的主人大多已被扫入乱葬岗，或是化作了不安的亡者。尽管饱受摧残，但这片土地依然展现出一种黑暗的韧性，以布瑞尔这样的城镇和丧钟镇那与世隔绝的避难所为基点，让新觉醒的被遗忘者学习如何忍受他们的第二人生。"},{t="双线战争",b="虽然希尔瓦娜斯女士声称她从地下的洛丹伦废墟统治着该地区，但被遗忘者依然在四面受敌。残余的天灾爪牙依然在空谷、田野和破败的墓穴中横行，完全效忠于诺森德的冰封王座。在东方，狂热的血色十字军将提瑞斯法北部作为其主要堡垒，并以血色修道院为大本营。他们疯狂地致力于消灭每一个亡灵生物——无论是生者还是死者——他们的哨站和巡逻队不断地对被遗忘者的侦察兵和平民旅客进行游击作战。"},{t="远古的余音",b="在人类王国加冕第一位君主很久之前，这片林地就承载着古老的遗产。高等精灵流亡者曾试图在此定居，但深埋于地下的暗影能量使他们发疯，促使他们向北迁徙。在随后的几个世纪里，被称为提瑞斯法议会的秘密人类法师组织选择了这些阴影笼罩的林地，以赋予孤独的守护者力量，守护艾泽拉斯免受恶魔入侵。"}},faq={{q="为什么天空是绿色的，土地在腐烂？",a="在第三次战争期间，阿尔萨斯王子和天灾军团向洛丹伦王国散布了亡灵瘟疫。这种魔法毒素不仅毒害了居民，还毒害了土壤、树木和水源，使林地陷入了永恒、诡异且病态的腐烂状态。",al={"为什么提瑞斯法枯萎了","提瑞斯法发生了什么","为什么提瑞斯法正在死亡"}},{q="这里的被遗忘者和天灾军团有什么区别？",a="被遗忘者是在海加尔山之战后摆脱了巫妖王心灵控制的亡灵，他们选择追随希尔瓦娜斯·风行者女士，拥有自己的自由意志。而那些在农场和废墟中游荡的天灾军团，依然是受制于巫妖王命令的无心智奴隶。",al={"被遗忘者与天灾军团","为什么僵尸攻击亡灵","所有的亡灵都是邪恶的吗"}},{q="那些攻击旅客的红甲士兵是谁？",a="他们属于血色十字军，这是一个由前白银之手骑士团成员和幸存者组成的极端分裂组织。他们坚信所有亡灵都是不可救赎的畸形生物，必须用刀剑和火焰来净化。他们怀着狂热的仇恨，处决了包括无心智的爪牙和拥有自由意志的被遗忘者在内的所有亡灵。",al={"血色十字军","红色人类","修道院的人类"}},{q="提瑞斯法这个名字从何而来？",a="这个名字比任何人类王国都要古老，其真正的起源已湮没在历史中。它最广为人知的是源于提瑞斯法议会，这是一个秘密的法师组织，赋予了守护者保护艾泽拉斯免受恶魔侵扰的力量。",al={"提瑞斯法的含义","提瑞斯法的起源"}},{q="新觉醒的被遗忘者从哪里开始他们的旅程？",a="新觉醒的被遗忘者从丧钟镇内的灰影墓穴中走出，这是一个位于提瑞斯法西南部的隐秘城镇。在那里，管理者和执行者会评估复活的死者是否具备服务黑暗女王所需的理智和忠诚。",al={"亡灵新手区域","丧钟镇在哪里","被遗忘者新手出生地"}},{q="旅客如何离开提瑞斯法前往其他大陆？",a="布瑞尔以南的山坡上，就在洛丹伦废墟外，坐落着一座巨大的地精经营的飞艇塔。这些飞艇提供穿越海洋的定期直达航线，分别前往卡利姆多的奥格瑞玛和荆棘谷的格罗姆高营地。",al={"提瑞斯法飞艇","如何前往奥格瑞玛","如何前往荆棘谷"}}},fx={["6c272224"]={q="提瑞斯法林地是什么地方？",a="提瑞斯法林地是被遗忘者位于洛丹伦北部海岸的故土。这里曾是一个强盛的人类王国富饶而宁静的核心地带，却在第三次战争期间遭天灾军团的亡灵瘟疫蹂躏。如今，受污染的树林和永无止境的绿色阴霾笼罩着群山，洛丹伦首都的废墟映衬其间，周围则盘踞着敌对的狂热分子、野化猛兽和残存的亡灵。",al={"提瑞斯法是什么地方","介绍一下提瑞斯法林地","提瑞斯法地区背景"}},["342b65f9"]={q="这里一直都是亡灵的土地吗？",a="不是。数千年来，提瑞斯法一直是人类文明的摇篮，也是洛丹伦王国繁荣的中心。在泰瑞纳斯·米奈希尔国王统治下，宁静的农庄、兴旺的磨坊和小村落蓬勃发展。第三次战争期间，阿尔萨斯王子和诅咒神教带着瘟疫席卷而来，这一时代就此惨烈终结，居民被变成亡灵奴隶，直到希尔瓦娜斯将他们解放。",al={"提瑞斯法一直都是亡灵之地吗","以前这里住着谁","瘟疫之前的提瑞斯法"}},["4790468d"]={q="谁生活在提瑞斯法林地，或由谁统治这里？",a="被遗忘者以幽暗城为据点，在希尔瓦娜斯·风行者女王的统治下宣称拥有提瑞斯法林地。然而，他们的控制权始终受到挑战。狂热的血色十字军在东北方掌控着防御工事和宏伟的修道院；毫无心智的天灾军团则在废弃农场间游荡。在东部边境的亡灵壁垒，被遗忘者与银色黎明并肩协作，遏制瘟疫之地的恐怖威胁。",al={"谁统治提瑞斯法","谁控制提瑞斯法林地","提瑞斯法的阵营"}},["97ffdb73"]={q="提瑞斯法林地危险吗？",a="极其危险。离开被遗忘者据点的围墙后，你会遭遇毫无心智的天灾军团残部、凶残的豺狼人、巨型蛛类，以及受瘟疫污染的凶猛野兽。更可怕的是血色十字军的狂热分子，他们一发现亡灵就会将其处决。遥远的东边是西瘟疫之地，那里的怪物比提瑞斯法林地的任何生物都要致命，足以将毫无防备的人撕成碎片。",al={"提瑞斯法有多危险","提瑞斯法的威胁","这里安全吗"}},["30e6283a"]={q="谁在布瑞尔当家？",a="执政官塞弗伦负责布瑞尔的民政管理，统筹城镇重建和日常生计。军事权力和战术行动，尤其是对附近血色十字军的战役，则由执行官塞加德指挥。",al={"布瑞尔的首领","谁领导布瑞尔","布瑞尔的负责人"}},["3fc3649e"]={q="执政官塞弗伦向谁负责？",a="塞弗伦效忠于黑暗女王希尔瓦娜斯·风行者。作为布瑞尔的执政官，他代表被遗忘者王室在此地区行使民政权力，并与幽暗城的王室执行官及皇家药剂师协会直接协作。",al={"塞弗伦的上司","塞弗伦向谁汇报","布瑞尔的领导关系"}},["381a9b46"]={q="女妖之王在哪里？",a="希尔瓦娜斯·风行者女士居住在幽暗城的皇家区，那里位于首都废墟深处、布瑞尔正南方。她在王座厅指挥被遗忘者对抗天灾军团和血色十字军。",al={"希尔瓦娜斯在哪里","寻找希尔瓦娜斯","女妖之王的位置"}},e7993821={q="布瑞尔是什么地方？",a="布瑞尔是提瑞斯法林地中部主要的被遗忘者城镇，坐落在首都以北的十字路口沿线。这里曾是巴罗夫家族领地上的一处生者聚居地，第三次战争后被重建，为新近苏醒的亡灵提供休憩、交易和集结之所，然后再踏上前往世界各地的旅途。",al={"布瑞尔介绍","布瑞尔是什么样的城镇","布瑞尔背景"}},["529e09c8"]={q="以前这里有人类居住吗？",a="有。布瑞尔曾是洛丹伦王国境内一处宁静的人类社区。克尔苏加德策划的早期瘟疫实验以这里为中心，导致大量居民丧生，并留下巨大的公共墓穴——那时阿尔萨斯王子还没有前来调查。",al={"以前有人类住在布瑞尔吗","布瑞尔的生者历史","以前住在布瑞尔的人"}},["7b7ff5e2"]={q="恐惧之末旅店是什么地方？",a="恐惧之末旅店是布瑞尔的中央集会厅和旅店。这里提供庇护、令人作呕的酒饮，以及在外面阴森林地中奔波后的喘息之机。在阴暗的角落里，被遗忘者会关押俘虏的敌人——比如血色十字军的狂热分子——以供药剂师进行邪恶的药剂试验。",al={"恐惧之末旅店","布瑞尔旅店","恐惧之末是什么地方"}},["0d8014ee"]={q="阿加曼德磨坊是怎么回事？",a="阿加曼德磨坊曾是提瑞斯法林地最富有、产量最高的农庄，以面粉和谷物闻名。瘟疫袭来时，整座庄园沦陷，惨遭屠戮。如今，这里已成为一片腐朽的废墟，点缀着风车，遍布残留的天灾亡灵。",al={"阿加曼德磨坊背景","阿加曼德磨坊发生了什么","阿加曼德磨坊"}},["001d4abe"]={q="阿加曼德家族是什么人？",a="阿加曼德家族是一个富有的贵族人类世家，他们开辟了广阔的磨坊，并在提瑞斯法各地拥有产业，包括布瑞尔。第三次战争期间，财富也未能拯救他们；家族惨遭天灾军团灭门，复活的族长们至今仍在庄园里游荡。",al={"阿加曼德家族","谁住在阿加曼德磨坊"}},eeb96a2c={q="它们也是亡灵，为什么还要攻击我们？",a="阿加曼德磨坊里的亡灵从未恢复自由意志。与摆脱了巫妖王精神控制的被遗忘者不同，这些生物仍是毫无心智的天灾奴仆，被迫摧毁任何闯入其领地的生者或反叛亡灵。",al={"阿加曼德家族为什么攻击我们","阿加曼德的亡灵为何敌对","为什么要和其他亡灵战斗"}},a357af07={q="离开提瑞斯法之后，接下来该去哪里？",a="大多数被遗忘者会向南穿过山口，前往银松森林，协助巩固南部边境，并对抗达拉然的特工和腐皮豺狼人。此外，布瑞尔南面的飞艇可以载你前往奥格瑞玛，或跨海抵达格罗姆高营地。",al={"离开提瑞斯法后去哪里","提瑞斯法之后的下一个地区","提瑞斯法林地之后"}},["50336b90"]={q="幽暗城是什么地方？",a="幽暗城是被遗忘者庞大的地下首都，建在破碎的洛丹伦废墟之下古老的下水道、墓穴和地下墓室中。它既是希尔瓦娜斯女王的要塞，也是被遗忘者在艾泽拉斯各地行动的指挥中心。",al={"幽暗城是什么地方","幽暗城背景","关于幽暗城"}},ddddba9f={q="接下来要去银松森林吗？",a="是的。沿着提瑞斯法林地南面的道路前行，就能直接进入银松森林。那里是你继续为被遗忘者效力的自然去处，你将在那里对抗洛丹伦南部边境日益加剧的威胁。",al={"接下来去银松森林","接下来去银松森林吗","银松森林边境"}},["789ead4d"]={q="我是怎么来到提瑞斯法林地的？",a="如果你是新近复生的被遗忘者，那么你在洛丹伦沦陷于天灾军团之手时死去，并被埋葬在这里。巫妖王的控制被打破后，你恢复了自由意志，并从丧钟镇这处僻静山谷的坟墓中爬了出来。如果你属于部落的其他种族，很可能是乘坐飞艇来到这里的。飞艇塔位于布瑞尔和幽暗城之间，可将这片被污染的土地与奥格瑞玛和格罗姆高营地直接连通。",al={"我是怎么来到这里的","怎么来到提瑞斯法林地","我是怎么到这里的"}},["89135166"]={q="我在提瑞斯法林地应该做什么？",a="你的目标是帮助被遗忘者巩固他们对洛丹伦这片受污染腹地脆弱的控制。从丧钟镇的墓穴出发，前往布瑞尔镇，你必须清除盘踞在废弃农场的无意识天灾军团，铲除从北方逼近的血色十字军狂热信徒，并猎杀在腐朽树林中游荡的染疫野兽。这样做能证明你对希尔瓦娜斯女王的价值，也能让你为她在旧城废墟下日益壮大的王国效力做好准备。",al={"我在这里该做什么","为什么在提瑞斯法","我在这里的目标是什么"}}},fp="15,338,18.442.0,19.456.0,26.372.0,42.269.0,65.287.0,53.289.0,39.222.0,53.244.0,53.247.0"}
P.entries["zone:undercity"] = {n="幽暗城",s="洛丹伦废墟的王城深处，坐落着幽暗城，这是被遗忘者黑暗的要塞。这座城市最初由天灾军团在古老的皇家墓穴和地牢中挖掘而成，后来被希尔瓦娜斯·风行者女王夺取，并被改造成了一座固若金汤的地下避难所。如今，这里是被遗忘者的权力中心，也是部落在东部王国北部的关键据点。",h="洛丹伦废墟的王城深处，坐落着幽暗城，这是被遗忘者黑暗的要塞。这座城市最初由天灾军团在古老的皇家墓穴和地牢中挖掘而成，后来被希尔瓦娜斯·风行者女王夺取，并被改造成了一座固若金汤的地下避难所。如今，这里是被遗忘者的权力中心，...",kw={"apothecarium","阿尔萨斯","被遗忘者","洛丹伦","天灾军团","希尔瓦娜斯","泰瑞纳斯","提瑞斯法","幽暗城","瓦里玛萨斯"},ang={["faction:Horde"]="作为部落在东部王国的主要立足点，幽暗城保障了直达杜隆塔尔和格罗姆高营地的飞艇航线。",["race:Human"]="在你覆灭的祖国土地下，坐落着洛丹伦皇家墓穴的阴森扭曲之物，那里被你曾经族人的行尸走肉所占据。",["race:Orc"]="就在这些地牢的深处，传奇大酋长奥格瑞姆·毁灭之锤曾被洛丹伦联盟囚禁，随后才完成了他那场历史性的逃脱。",["race:Undead"]="幽暗城是你的主权避难所和家园，是在打破巫妖王对你心智的铁腕控制后，由你们亲手开凿而成的。"},sec={{t="从皇家墓穴到天灾要塞",b="在瘟疫席卷洛丹伦很久之前，皇宫下方的地下墓穴、地牢和下水道就被统称为幽暗城。这里关押着贵族的陵墓、王国最深处的监狱——前任大酋长奥格瑞姆·毁灭之锤在逃脱前曾被关押于此——以及王国最贫困的居民。当阿尔萨斯·米奈希尔在20 ADP谋杀泰瑞纳斯国王并摧毁首都时，这位王子命令他的亡灵仆从挖掘并扩建这些地下通道，将其建成了一座天灾统治下的坚固要塞。"},{t="被遗忘者的崛起",b="天灾军团从未见证过他们黑暗之都的完工。在海加尔山之战后，当巫妖王的实力减弱时，希尔瓦娜斯·风行者摆脱了蜂巢思维的控制，并带走了数千名亡灵。她诱使阿尔萨斯陷入埋伏，并将他赶回了诺森德。在经历了针对天灾残党、恐惧魔王和人类抵抗军的激烈三方内战后，希尔瓦娜斯占据了这座未完工的地下墓穴。她将她的人民命名为被遗忘者，并监督了数年的劳动，完成了这座庞大的地下城市。"},{t="被诅咒的建筑",b="幽暗城呈同心圆布局，分为若干功能区。其核心是贸易区，通过巨大的升降梯与上方的废墟连接。环绕在它周围的是军事区、盗贼区、法师区和充满毒气的药剂师区，皇家药剂师学会就在那里利用满是绿色粘液的运河酿造致命的瘟疫。更深处是皇家区，希尔瓦娜斯女王与她的恐惧魔王指挥官瓦里玛萨斯在此坐镇，周围守卫着无数高大的憎恶。"}},faq={{q="在亡灵占领之前，幽暗城是什么样子的？",a="在洛丹伦皇宫下方，坐落着古代人类王室的墓穴，以及城市的地牢建筑群和巨大的下水道网络。这里曾关押过战俘，包括奥格瑞姆·毁灭之锤，还有生活在地下阴影中的赤贫平民。在洗劫首都后，阿尔萨斯王子开始将这些地下墓穴改造成天灾要塞，随后被希尔瓦娜斯夺取。",al={"幽暗城起源","幽暗城最初是什么","洛丹伦下水道历史"}},{q="为什么城市建在地下而不是地面上？",a="洛丹伦的地面城市在第三次战争中完全沦为废墟，使其难以抵御血色十字军、天灾军团和联盟幸存者的攻击。地下隧道提供了天然的防御工事、阻塞点和隐秘性，使得被遗忘者能够完成天灾军团最初的建设，并在不为人知的情况下繁荣发展。",al={"为什么住地下","为什么不重建洛丹伦","为什么幽暗城在废墟之下"}},{q="谁统治着幽暗城？",a="这座城市由希尔瓦娜斯·风行者女王，即女妖之王和被遗忘者女王统治。她从皇家区进行管辖，并由被遗忘者皇家卫兵和她征服的恐惧魔王副官瓦里玛萨斯守卫。",al={"幽暗城的领袖是谁","幽暗城统治者","谁管理幽暗城"}},{q="废墟上方的泰瑞纳斯国王纪念碑是做什么用的？",a="在城市主要升降梯的上方，矗立着一座为被杀害的泰瑞纳斯·米奈希尔二世国王建造的石质纪念碑。里面并没有他的遗体，因为他的尸体在克尔苏加德复活时被火化，骨灰也被丢弃了。幸存的联盟人类在废墟中勇敢地雕刻了这座纪念碑，以便让人们铭记洛丹伦最后一位真正国王的记忆。",al={"泰瑞纳斯国王陵墓","洛丹伦王座大厅之墓","谁建造了幽暗城上方的墓穴"}},{q="洛丹伦王座大厅里那些奇怪的声音是什么？",a="在幽暗城升降梯上方的废墟王座大厅中，过去的幽灵回声依然挥之不去。站在中央的访客可以听到模糊的幻听：阿尔萨斯归来时庆祝的钟声和落下的玫瑰花瓣，先知麦迪文的警告，以及泰瑞纳斯国王与他弑父逆子之间最后的对话。",al={"王座大厅的幽灵声","王座大厅的低语","洛丹伦王座大厅的声音"}},{q="为什么被遗忘者允许其他部落成员进入这里？",a="被遗忘者与萨尔大酋长的部落结成了权宜联盟以求生存，因为他们周围环绕着充满敌意的血色狂热者和天灾军团。尽管有生命的部落种族会觉得这里的毒雾和炼金河流令人窒息，但为了促进外交和军事联系，使者和旅行者仍被允许进入。",al={"为什么兽人在幽暗城","幽暗城的部落","为什么幽暗城是部落的一部分"}}},fx={a590d153={q="幽暗城是什么？",a="幽暗城是被遗忘者的地下首都，直接建在提瑞斯法林地中破碎的旧城废墟下方。它由古老的皇家墓穴、下水道和地下墓穴开凿而成。在内战期间，阿尔萨斯王子曾将其扩建为天灾军团的要塞，后来希尔瓦娜斯·风行者女王和她麾下的叛离亡灵夺取了这里。如今，它是自由意志亡灵的坚固庇护所，城中纵横着有毒污泥，并由守卫严密防范所有生者闯入。",al={"幽暗城是什么","介绍幽暗城","幽暗城背景"}},c51b16b2={q="洛丹伦的老国王遭遇了什么？",a="泰瑞纳斯·米奈希尔二世国王在这座城市正上方的王座厅里被自己的儿子阿尔萨斯王子杀害。阿尔萨斯从诺森德归来时已被符文剑霜之哀伤腐化，他杀死了父亲，并将天灾军团释放到王国各处。后来，死亡骑士盗走了泰瑞纳斯的骨灰，用以复活克尔苏加德，只留下纪念碑，以及你如今仍能在废弃王座附近看到的干涸血迹。",al={"泰瑞纳斯国王的结局","泰瑞纳斯国王遭遇了什么","谁杀了泰瑞纳斯国王"}},c11144c7={q="阿尔萨斯是谁？",a="阿尔萨斯·米奈希尔是洛丹伦的王储，也是一位声名卓著的白银之手圣骑士。为了阻止席卷故土的亡灵瘟疫，他的征讨逐渐变得冷酷而偏执。在诺森德，他夺取了被诅咒的符文剑霜之哀伤，灵魂被其吞噬，成为巫妖王令人畏惧的勇士。他回到故乡后屠杀了父亲，夷平了洛丹伦，最终又返回北方，与冰封王座融为一体。",al={"阿尔萨斯是谁","阿尔萨斯王子的背景","阿尔萨斯·米奈希尔"}},["7f6bbd49"]={q="希尔瓦娜斯·风行者是谁？",a="希尔瓦娜斯·风行者女王曾是银月城英勇的游侠将军，在第三次战争期间抵御天灾军团，保卫奎尔萨拉斯。她战死后，阿尔萨斯从她的尸体中抽出灵魂，将她扭曲成女妖加以折磨。巫妖王的控制减弱后，她挣脱束缚，夺回肉身，并集结其他独立的亡灵，建立了被遗忘者。如今，她在皇家区统治着他们，成为女妖之王。",al={"女妖之王是谁","希尔瓦娜斯背景","希尔瓦娜斯是谁"}},["2a8de90f"]={q="希尔瓦娜斯为什么被称为黑暗女王？",a="被遗忘者尊称希尔瓦娜斯为黑暗女王，因为她将他们从巫妖王无意识的奴役中解放出来，并在艾泽拉斯其他地方都想将他们彻底灭绝时给予他们庇护。这个称号与女妖之王的头衔一样受人敬仰，既体现了她掌控死亡的幽暗力量，也体现了她的亡灵臣民对她坚定不移的忠诚。",al={"为什么叫黑暗女王","希尔瓦娜斯的黑暗女王头衔","黑暗女王的含义"}},["84f18f47"]={q="被遗忘者为什么属于部落？",a="被敌对的血色十字军、穷追不舍的天灾军团和复仇心切的联盟残部包围，被遗忘者无法独自在洛丹伦生存。希尔瓦娜斯女王越过大海联系了大酋长萨尔，缔结了一项务实的互利同盟。部落因此在东部王国获得了至关重要的军事据点，而被遗忘者则在为生存而战的过程中获得了必需的援军和政治合法性。",al={"被遗忘者为何加入部落","亡灵加入部落","被遗忘者、部落与联盟"}},["71200045"]={q="天灾军团是什么？它们还在附近吗？",a="天灾军团是由燃烧军团创造、受巫妖王统治的庞大无意识亡灵军队，巫妖王在诺森德指挥它们。尽管被遗忘者夺回了幽暗城和提瑞斯法林地，天灾军团仍是迫在眉睫的致命威胁。在克尔苏加德的指挥下，它们的军团仍盘踞在附近的瘟疫之地，并侵扰林地各处废弃的农庄和墓穴。",al={"天灾军团还在附近吗","天灾军团是什么","洛丹伦的天灾军团"}},["501548ab"]={q="巫妖王现在在哪里？",a="巫妖王居住在遥远的诺森德冰封荒原之上的冰封王座。瘟疫之地内战结束后，阿尔萨斯王子逃离洛丹伦，去保护力量日渐衰弱的主人。他登上冰川，与巫妖王的精魂合二为一，成为一个令人恐惧的存在。从那座极地堡垒中，他冰冷的目光仍注视着艾泽拉斯。",al={"巫妖王在哪里","巫妖王的位置","阿尔萨斯现在在哪里"}},["4cc7f971"]={q="血色十字军是什么人？",a="血色十字军是一个由洛丹伦防线废墟中诞生的人类狂热组织。他们被对亡灵的正义仇恨蒙蔽双眼，无法区分无意识的天灾军团与拥有自由意志的被遗忘者。他们认为任何沾染亡灵气息的人，以及任何容忍他们的生者异乡人，都是只配被送上火刑架的邪恶怪物。他们在提瑞斯法林地的主要据点是血色修道院。",al={"血色十字军是什么人","血色十字军成员","血色十字军背景"}},["271820ed"]={q="幽暗城危险吗？",a="那里极其危险，尤其是对生者而言。炼金废料和有毒污泥的沟渠流经城市街道，毒气弥漫在宽阔的大厅中，让血肉之躯难以安全呼吸。铺砌街区的下方是遭到侵扰的下水道，更深处则是隐秘的实验场所，那里每天都有人策划黑暗炼金实验和冷酷的暗杀行动。",al={"幽暗城安全吗","幽暗城的危险","幽暗城有哪些危险"}},["2539a3c3"]={q="我是怎么来到幽暗城的？",a="作为被遗忘者，你在丧钟镇死而复生，并在提瑞斯法林地证明忠诚之后，自然会沿着道路经过布瑞尔，来到旧城破碎的废墟下方。如果你来自卡利姆多或遥远的地方，很可能是乘坐停靠在首都外飞艇塔的部落飞艇抵达，或是跋涉穿过受污染的乡野。幽暗城是部落在洛丹伦北部的主要据点，在古老王宫的地下墓穴下方为你提供庇护和使命。",al={"我是怎么来到这里的","怎么到达幽暗城","如何前往幽暗城"}},b63c4cf2={q="我在幽暗城应该做什么？",a="你来到这里，是为了帮助被遗忘者，并集结部落的力量，对抗洛丹伦周边的威胁。在城内层层环绕的城区中，你可以向职业训练师请教、购买补给，并咨询皇家药剂师协会的黑暗研究者。除了经营自己的专业，你还要接受希尔瓦娜斯·风行者女王及其副官的任务。被遗忘者要在多条战线上作战：清剿无意识天灾军团的残余势力，击退狂热的血色十字军，并为拥有自由意志的亡灵守住栖身之地。",al={"我在这里做什么","我在幽暗城该做什么","我为什么在这里"}}},fp="9,304,36.483.0,20.506.0,26.483.0,54.383.0,60.340.0,24.216.0,51.333.0,57.328.0,51.322.0"}
P.entries["zone:ungoro"] = {n="安戈洛环形山",s="安戈洛环形山是一片下陷的原始丛林，坐落在塔纳利斯和希利苏斯干旱的荒原之间。这里栖息着游荡的恐龙和活体元素，中心还矗立着一座火山。这座葱郁的火山口内遍布着古老的泰坦遗迹和能量水晶，其起源至今仍是一个巨大的谜团。",h="安戈洛环形山是一片下陷的原始丛林，坐落在塔纳利斯和希利苏斯干旱的荒原之间。这里栖息着游荡的恐龙和活体元素，中心还矗立着一座火山。这座葱郁的火山口内遍布着古老的泰坦遗迹和能量水晶，其起源至今仍是一个巨大的谜团。",kw={"魔暴龙","火羽山","众神之地","拉卡里","马绍尔营地","能量水晶","托尔瓦·寻路者","安戈洛","安戈洛环形山"},ang={["class:Druid"]="塞纳里奥议会的德鲁伊们研究安戈洛与世隔绝的生态系统，并采集其肥沃的土壤来培育魔草，试图理解维持这片火山口的纯净、未受驯化的生命力。",["faction:Alliance"]="联盟的博物学家聚集在马绍尔营地的威利德·马绍尔和J.D.科利身边，争分夺秒地破译泰坦水晶塔，同时保护达纳苏斯的研究人员采集土壤样本。",["faction:Horde"]="部落冒险者经常经由塔纳利斯到达这里，对抗传说中的魔暴龙以考验自己的实力，并协助雷霆崖的草药师利用安戈洛的原始泥土培育魔草。",["profession:Herbalism"]="盆地中丰富的水分滋养了稀有的植物，使其成为卡利姆多为数不多的几个盲目草、梦叶草和黄金参在火山斜坡上与火焰花共同繁茂的地方之一。",["profession:Mining"]="陡峭的环形山壁和火羽山的岩架上遍布着秘银矿脉和富瑟银矿脉，使该地区成为获取高端矿石的首选目的地。"},sec={{t="众神之地",b="安戈洛环形山夹在广阔的沙漠之间，违背了卡利姆多南部的地理特征。记载流沙之战的古老暗夜精灵文献指出，虫族其拉曾被阻挡在环形山的边缘，无法进入他们口中所谓的“众神之地”。学者们推测，在塑造卡利姆多期间，这座火山口曾作为泰坦的试验场或古代居所。石塔耸立在山脊上，发出阵阵嗡鸣，蓝色、红色、绿色和黄色的水晶体从原始的土地中破土而出。"},{t="野蛮的生态系统",b="安戈洛环形山内没有城市、城镇或土著类人生物社会。相反，生命以一种未受驯化的原始状态繁衍。顶级的魔暴龙在恐惧小道的平原上潜行，捕食性的血瓣花在沼泽地中发动攻击，软泥怪在拉卡里的焦油坑中爬行。在环形山的中心，火羽山拔地而起，这座活跃的火山峰上挤满了由名为“烈焰奔腾者”的实体所领导的敌对火元素。对于探险家和剥皮者来说，这片盆地拥有无与伦比的自然财富——包括令人垂涎的魔暴龙皮——前提是你能在食物链中幸存下来。"},{t="马绍尔营地",b="在环形山内的文明存在几乎仅限于马绍尔营地，这是一个位于北部悬崖上的高处营地。在威利德·马绍尔的带领下，一支由科学家、博物学家和寻宝者组成的探险队曾试图整理这片盆地的宝藏，却遭到了怪物般的野生动物的重创，被迫退守高地。如今，该营地已成为勇敢的旅行者们的前哨站，他们在那里研究环形山神秘的能量水晶、绘制火山活动图，并警惕地监视着从南部山脊入侵的希利苏斯虫群。"}},faq={{q="如何进入安戈洛环形山？",a="旅行者可以通过通向环形山壁的自然坡道进入：一条位于塔纳利斯西南角靠近灌木谷的地方，另一条从东北部的希利苏斯进入。虽然鲁莽的冒险者有时会从悬崖上跳下，但如果没有魔法协助，坠落是致命的。北部的马绍尔营地提供前往加基森和塞纳里奥要塞的飞行点。",al={"如何进入安戈洛","安戈洛入口","如何前往安戈洛环形山"}},{q="彩色能量水晶有什么用？",a="丛林地面上散布着红色、蓝色、绿色和黄色的能量水晶。在马绍尔营地的侏儒研究员J.D.科利的指导下，探险者可以破译在北部、东部和西部水晶塔上使用这些水晶的说明。在相应的水晶塔上组合特定的颜色，可以利用潜在的泰坦能量来制作防御或恢复性的护符。",al={"安戈洛水晶","安戈洛红蓝绿黄水晶","能量水晶塔"}},{q="为什么安戈洛被沙漠包围却依然葱郁？",a="学者们认为安戈洛非自然的活力是人为的，源于塑造世界的泰坦。泰坦导管、来自火羽山的温暖火山地热活动，以及古老的能量流滋养了一个与世隔绝、超速发展的生态系统，使其能够抵御邻近的塔纳利斯和希利苏斯的干旱环境。",al={"为什么安戈洛是丛林","安戈洛与沙漠的关联","安戈洛如何生长植物"}},{q="为什么其拉虫人称这里为“众神之地”？",a="根据从流沙之战翻译来的石板记载，虫群在环形山的入口处停止了前进。翻译此记录的地质学家拉克斯班将这个名字与泰坦曾居住在环形山的理论联系了起来，并推测阿曼苏尔本人是否曾经守护过众神之地。",al={"众神之地含义","其拉虫人与安戈洛","为什么希利苏斯虫群无法占领安戈洛"}},{q="安戈洛的泥土有什么用？",a="在环形山盆地各处都有肥沃、强效的泥土堆。采集后，这种泥土可以与瑟利斯种子放入常青袋中，以培育魔草，这是一种受到雷霆崖、达纳苏斯和塞纳里奥议会的研究人员热切追捧的神秘草药。",al={"安戈洛土壤样本","安戈洛的泥土有什么用","魔草土壤"}},{q="这里有类人生物定居点或地下城吗？",a="安戈洛环形山拥有一个供58到60级左右玩家进入的地下城——塑造者之台，但没有原生的类人生物社会。唯一长久存在的定居点是马绍尔营地，这是一个位于北缘的小型探险前哨站。除了隐居的猎人或迷路的探险者外，火山口的其他地方完全处于原始状态。",al={"安戈洛地下城","谁住在安戈洛","安戈洛的类人生物"}}},fp="14,269,13.410.0,18.462.0,16.490.0,35.282.0,45.336.0,56.270.0,51.330.0,30.235.0,52.287.0"}
P.entries["zone:wailing"] = {n="哀嚎洞穴",s="在贫瘠之地干旱的甜水绿洲之下，坐落着哀嚎洞穴，这是一个由地下泉水和裂隙组成的迷宫，因被困蒸汽发出的诡异呼啸声而得名。最初这里是一次高尚的德鲁伊尝试，旨在复苏卡利姆多被太阳炙烤的稀树草原，但最终却沦为一个扭曲、充满毒素的地下世界。如今洞穴内满是扭曲的野兽和堕落的信徒，他们被一种深层、非自然的梦魇所腐蚀。",h="在贫瘠之地干旱的甜水绿洲之下，坐落着哀嚎洞穴，这是一个由地下泉水和裂隙组成的迷宫，因被困蒸汽发出的诡异呼啸声而得名。最初这里是一次高尚的德鲁伊尝试，旨在复苏卡利姆多被太阳炙烤的稀树草原，但最终却沦为一个扭曲、充满毒素的地...",kw={"变异","尖牙德鲁伊","翡翠梦魇","安娜科德拉","考布莱恩","皮萨斯","瑟芬迪斯","甜水绿洲","穆坦努斯","纳拉雷克斯","永生者"},ang={["class:Druid"]="对于塞纳里奥传统的德鲁伊和走牛头人道路的修行者来说，这些洞穴是一个关于翡翠梦境危险的悲剧警示，也是净化他们堕落兄弟——尖牙德鲁伊的庄严职责。",["race:NightElf"]="纳拉雷克斯曾是暗夜精灵德鲁伊中备受尊敬的人物，他被翡翠梦魇腐化的悲剧，对他远在海对岸的族人来说是一场痛苦的灾难。",["race:Tauren"]="扭曲的水域威胁着维持贫瘠之地生命的脆弱绿洲，使得净化泉水对莫高雷和十字路口的部落人民至关重要。"},sec={{t="高尚愿景的腐化",b="暗夜精灵德鲁伊纳拉雷克斯最初发现了这个广阔的水系，并制定了一个雄心勃勃的计划：通过开启一条直通翡翠梦境的通道，他可以将原始的生命精华引入地下泉水，将干涸的贫瘠之地变回繁茂的绿洲天堂。在洞穴深处，在忠诚侍僧的守护下，纳拉雷克斯进入了与梦境的交流中。可悲的是，这位德鲁伊沉睡的意识触碰到的并非纯净的生命力，而是翡翠梦魇。那肆虐的腐化瞬间攫住了他，将他那本意良好的通道变成了一个向地下水道倾泻毒液与疯狂的阀门。"},{t="尖牙德鲁伊",b="当梦魇的黑暗能量从纳拉雷克斯无助的身躯中辐射开来时，他的学生们屈服于疯狂。他们背弃了塞纳里奥议会的宁静智慧，组建了狂热的尖牙德鲁伊。这些教派领袖——安娜科德拉、考布莱恩、皮萨斯和瑟芬迪斯——化身为爬行动物，与其对抗洞穴的变异，不如说他们拥抱了这种毒性突变。他们积极保护沉睡的主人免受任何外界干扰，坚信这种扭曲的生长才是大自然的真正进化。"},{t="梦魇的实体化",b="打破尖牙德鲁伊的控制并不能自动拯救纳拉雷克斯。当他剩余未受腐化的门徒在Dreamer's Rock开始仪式，试图轻唤他从恍惚中醒来时，这位沉睡精灵的潜意识剧烈挣扎，排出了他内心深处最可怕的恐惧。随之喷薄而出的生物——一只巨大、扭曲的鱼人，名叫吞噬者穆坦努斯——便是纳拉雷克斯最可怕梦魇的物理化身。只有消灭这个怪物，通往梦魇的渠道才能被切断，纳拉雷克斯才能苏醒、化为禽鸟形态，从这被污染的洞穴中飞离。"}},faq={{q="为什么叫哀嚎洞穴？",a="洞穴因隧道中传出的凄凉哀嚎声而得名。这些声音是由于地下蒸汽喷口和高压风流穿过石灰岩狭窄裂隙时自然产生的。",al={"为什么叫哀嚎洞穴","名称由来","为什么会哀嚎"}},{q="洞穴里的野兽为何会变得“变异”？",a="当纳拉雷克斯陷入翡翠梦魇的控制时，被污染的梦境能量直接渗入了地下泉水。饮用并生活在这些被污染的水域中，导致自然的迅猛龙、鳄鱼和毒蛇变成了非自然的“变异”物种。",al={"变异腐化","迅猛龙为什么变异","变异野兽起源"}},{q="谁是尖牙德鲁伊？",a="他们曾是纳拉雷克斯虔诚的暗夜精灵和牛头人侍僧。随着他一同被梦魇腐化，他们的心智崩溃，将德鲁伊技艺扭曲为对毒蛇和毒液的崇拜，并采用了考布莱恩、皮萨斯和安娜科德拉这样的称号。",al={"尖牙德鲁伊","尖牙德鲁伊背景","瑟芬迪斯是谁"}},{q="为什么最终首领是一只名叫穆坦努斯的巨型鱼人？",a="穆坦努斯是在尝试唤醒纳拉雷克斯的过程中出现的。随着仪式的展开，它的本质及其与沉睡德鲁伊的联系便会揭晓。",al={"穆坦努斯为什么是鱼人","穆坦努斯是什么","最终首领背景"}},{q="击败穆坦努斯后会发生什么？",a="门徒唤醒纳拉雷克斯的尝试在战斗结束后继续进行。仪式结束时，这位德鲁伊的命运便会揭晓。",al={"唤醒纳拉雷克斯","纳拉雷克斯的结局","纳拉雷克斯发生了什么"}},{q="谁住在洞穴入口上方的洞穴里？",a="在洞穴那形似骷髅的岩石眼眶里，驻扎着塞纳里奥议会的忠诚成员，包括纳尔帕克和厄布鲁。他们寻求勇敢的旅者收集变异皮，并在腐化彻底吞噬贫瘠之地前将其净化。",al={"入口上方的洞穴","蛇骷髅眼眶非玩家角色","纳尔帕克和厄布鲁是谁"}}},fx={["8502642f"]={q="这里由谁掌管？",a="纳拉雷克斯被困在洞穴深处，陷入受腐化影响的沉睡之中，而洞穴的日常事务则由尖牙德鲁伊掌管。他们由瑟芬迪斯领导。瑟芬迪斯曾是纳拉雷克斯最出色的学生，如今却召集了扭曲的同胞，企图将这片土地改造成他们自己的畸变乐园。考布莱恩、皮萨斯和安娜科德拉等其他尖牙领主也与他并肩行事。",al={"谁领导哀嚎洞穴","哀嚎洞穴的首领","哀嚎洞穴的首领是谁"}},["32be29c8"]={q="什么是翡翠梦境？它与这座洞穴有什么联系？",a="翡翠梦境是一个广阔的灵界，映照着未经触碰、野性未驯的艾泽拉斯。它由绿龙军团守护，德鲁伊可以进入其中。纳拉雷克斯相信，自己能够将梦境中纯净且具有复苏之力的能量引入哀嚎洞穴的地下含水层，让贫瘠之地重新长满茂盛的植物。然而，当他尝试汲取这股力量时，却被翡翠梦魇缠住，将扭曲的自然投射到了现实中的洞穴里。",al={"翡翠梦境的联系","哀嚎洞穴与翡翠梦境","纳拉雷克斯与翡翠梦境"}},["38e519c2"]={q="为什么大家都这么担心这个地方？",a="洞穴中的地下泉水滋养着主要绿洲，为贫瘠之地各处的生命提供水源。如果翡翠梦魇的污秽继续不受遏制地渗入水道，侵蚀洞穴动植物的扭曲变异与疯狂便可能蔓延至整个地区，让这片土地化为一场挥之不去的噩梦。",al={"为什么担心哀嚎洞穴","哀嚎洞穴对贫瘠之地的威胁","哀嚎洞穴有多危险"}},["81917ac6"]={q="我是怎么来到哀嚎洞穴的？",a="你从十字路口向南前往甜水绿洲，沿途听说贫瘠之地出现了怪异野兽，受污染的水也在不断扩散。绿意葱茏的植被与科卡尔半人马营地后方，岩石中凿出了一座巨大的骷髅形洞穴。你可能是响应雷霆崖的求援，或是为了棘齿城地精想要的奇异精华，也可能受到骷髅眼窝上方营地中门徒的吸引。穿过蜿蜒的裂隙和嘶鸣的地下间歇泉后，你便深入了下方呻吟般的幽暗深处。",al={"我是怎么到这里的","怎么去哀嚎洞穴","我是从哪里来的"}},["28a012f3"]={q="我在哀嚎洞穴里应该做什么？",a="你来到这里，是为了净化这处地下泉水遭受的腐化。暗夜精灵德鲁伊纳拉雷克斯试图让贫瘠之地重焕生机，却陷入了噩梦般的沉睡，洞穴中的生物因此变得扭曲，他的门徒也沦为充满毒性的尖牙德鲁伊。你必须追猎四位尖牙领主——安娜科德拉、考布莱恩、皮萨斯和瑟芬迪斯，瓦解他们的控制，然后帮助幸存的门徒唤醒纳拉雷克斯，以免他狂热的噩梦彻底吞噬绿洲。",al={"我在这里的目标是什么","我为什么在哀嚎洞穴","我在这里做什么"}},["3386ab3f"]={q="哀嚎洞穴是什么？",a="哀嚎洞穴是一片广阔的地下洞穴网络，位于贫瘠之地干旱的土地下方，靠近甜水绿洲。洞穴中的天然地下泉水在大地深处流淌数里，为散布在这片区域的稀有地表绿洲供水。暗夜精灵德鲁伊纳拉雷克斯发现了这里，原本打算将其作为一项宏大自然复苏计划的核心。然而，一场悲剧性的灾难降临洞中的德鲁伊后，这里反而成了危险腐化的中心。",al={"哀嚎洞穴是什么","哀嚎洞穴概况","关于哀嚎洞穴"}},e070a543={q="那里住着什么？",a="洞穴中充斥着异变的野生生物和叛离的德鲁伊。纳拉雷克斯被腐化的追随者——尖牙德鲁伊——与变异蛇类、软泥怪、迅猛龙和鳄鱼共同占据了洞穴隧道。副本入口外的潮湿通道中潜伏着野兽、软泥怪，甚至还有流亡者；而被腐化的德鲁伊则守卫着内室，保护他们沉睡的主人。",al={"哀嚎洞穴里有什么人","哀嚎洞穴的生物","哀嚎洞穴的居民"}},["49d47201"]={q="部落为什么派我来这里？",a="当地野兽的奇异变异，以及从甜水绿洲涌出的邪恶能量，威胁着整个贫瘠之地。部落和雷霆崖的塞纳里奥德鲁伊无法容忍失控的黑暗力量在十字路口附近污染土地和水道。你被派来调查此事，铲除尖牙德鲁伊的叛变首领，并帮助平息日益扩大的危险。",al={"我为什么在哀嚎洞穴","部落在哀嚎洞穴的任务","为什么派我去哀嚎洞穴"}},d445bb78={q="这是贫瘠之地更大危机的一部分吗？",a="是的。这些洞穴下方的地下水道为贫瘠之地各处地表绿洲供水。梦魇之力对洞穴水源的腐化已经开始向周围蔓延，导致迅猛龙和鳄鱼等野生生物发生变异，并使甜水绿洲成为奇异变异生物的滋生地。",al={"贫瘠之地的绿洲问题","贫瘠之地的变异腐化","哀嚎洞穴是否影响贫瘠之地"}},["038fd1cf"]={q="变异生物正在扩散到洞穴外吗？",a="它们已经扩散出来了。地下泉水直接流入甜水绿洲等地表绿洲，将异常生长和变异生物带到了开阔的草原上。你可以从洞外水域钓到变异鱼等奇异生物，而且具有攻击性的变异掠食者也越来越频繁地袭击往返于绿洲和十字路口的旅人。",al={"变异生物正在扩散吗","贫瘠之地的变异野兽","洞外的变异鱼"}}},fp="15,278,31.501.0,22.495.0,24.481.1,37.218.0,50.226.0,31.267.0,51.127.1,39.123.1,52.229.0"}
P.entries["zone:warsonggulch"] = {n="战歌峡谷",s="战歌峡谷是一片位于灰谷和贫瘠之地交界处的森林峡谷，也是部落和联盟之间永不停歇的战场。战歌氏族的兽人们在那里为部落砍伐灰谷的木材，而银翼要塞的暗夜精灵们则奋力将他们赶出这片神圣的森林。各个种族的战士都前来贡献刀剑或法术，双方都在突袭对方的据点以夺取其旗帜。",h="战歌峡谷是一片位于灰谷和贫瘠之地交界处的森林峡谷，也是部落和联盟之间永不停歇的战场。战歌氏族的兽人们在那里为部落砍伐灰谷的木材，而银翼要塞的暗夜精灵们则奋力将他们赶出这片神圣的森林。各个种族的战士都前来贡献刀剑或法术，双...",kw={"战歌峡谷","战场","战歌氏族","银翼要塞","战歌伐木场","旗帜","木材","灰谷","葛罗·地狱吼"},ang={["faction:Alliance"]="联盟士兵在这里为他们的暗夜精灵盟友而战，他们的神圣森林正因战歌氏族的斧头而一棵接一棵地倒下。",["faction:Horde"]="每一根离开战歌伐木场的原木都能在卡利姆多的某个地方筑起一道部落城墙；守住峡谷就是维持部落的建设。",["race:NightElf"]="这些树林见证了卡多雷足迹一万年。每一个被赶出峡谷的兽人都意味着收复了一片灰谷。",["race:Orc"]="战歌氏族是葛罗·地狱吼的直属部队，峡谷是他的战士们依然赢得名声的地方，他们手持斧头对抗着银翼要塞。"},sec={{t="木材与鲜血",b="部落用木材在卡利姆多建立了新家园，而其中大部分木材都来自灰谷。自部落登陆以来，葛罗·地狱吼的战士——战歌氏族就一直在砍伐这片森林。他们位于峡谷尽头的战歌伐木场为部落的营地和城墙提供了补给。对于暗夜精灵来说，每一棵被砍伐的树木都伤害了他们守护了一万年的森林，他们也没有忘记葛罗的战士曾在这片树林中杀死了塞纳留斯。"},{t="先遣骑兵与哨兵",b="部落在这里的战士是战歌氏族，由贫瘠之地北缘的莫尔杉营地提供补给，凯尔姆·哈古斯在那里负责他们的武装和补给。与他们对抗的是银翼要塞的银翼要塞，这是一群发誓要将所有入侵者赶出灰谷的暗夜精灵战士，由银翼树林的艾蒂尔·月火负责补给。双方的盟友都涌向峡谷：矮人和人类站在银翼要塞一边，牛头人、巨魔和被遗忘者站在战歌氏族一边。"},{t="争夺战旗",b="双方在峡谷的一端各拥有一座据点，部落是战歌伐木场，暗夜精灵是银翼要塞，并且双方都将各自的战旗存放在那里。这场战斗是一场突袭竞赛：战士们冲入敌方的据点，夺取其旗帜并飞奔回自己的据点，同时防守者会追击他们。每一面带回家的旗帜都是对敌人自尊心的一次打击，夺取旗帜最多的一方将获得当天的胜利。"}},faq={{q="什么是战歌峡谷？",a="战歌峡谷是位于灰谷和贫瘠之地之间的一片森林峡谷中的战场。部落的战歌氏族和暗夜精灵的银翼要塞在那里为部落在灰谷的采伐活动而战，双方都在努力夺取对方的旗帜。",al={"什么是战歌峡谷","战歌峡谷战场","战歌峡谷"}},{q="部落为什么要参加战歌峡谷的战斗？",a="部落需要灰谷的木材来建造和维持其在卡利姆多的家园。战歌氏族在峡谷的伐木场是其主要来源之一，战歌氏族负责保卫它，以便部落的营地和城墙能够不断建立。",al={"部落争夺战歌峡谷","兽人为什么要砍伐灰谷","战歌氏族的目的"}},{q="暗夜精灵为什么要参加战歌峡谷的战斗？",a="对于暗夜精灵来说，灰谷是他们守护了一万年的神圣森林，而战歌氏族曾经在那里杀死了半神塞纳留斯。银翼要塞奋力阻止采伐并将兽人赶出他们的树林，而联盟的其他成员也与他们站在一起。",al={"联盟争夺战歌峡谷","哨兵为什么要战斗","银翼要塞的目的"}},{q="战歌氏族是谁？",a="战歌氏族是部落在战歌峡谷的战士，来自曾经由葛罗·地狱吼领导的战歌氏族。他们由位于贫瘠之地北部的莫尔杉营地提供补给，凯尔姆·哈古斯在那里为他们提供装备。",al={"战歌氏族","战歌氏族战士","凯尔姆·哈古斯"}},{q="银翼要塞是谁？",a="银翼要塞是银翼要塞的暗夜精灵战士，发誓要将部落赶出灰谷。银翼树林的艾蒂尔·月火为在峡谷中与他们并肩作战的联盟勇士提供补给。",al={"银翼要塞","艾蒂尔·月火"}},{q="如何在战歌峡谷的战斗中获胜？",a="双方在各自的据点中各持有一面旗帜。战士们突袭敌方的基地，夺取其旗帜并将其带回自己的基地，同时保卫自己的旗帜，带回最多旗帜的一方获胜。",al={"战歌峡谷目标","战歌峡谷夺旗","如何赢得战歌峡谷"}}},fp="13,291,16.424.0,23.488.0,28.315.0,22.226.0,42.201.0,46.259.0,30.223.0,33.216.0,39.193.0"}
P.entries["zone:westernplaguelands"] = {n="西瘟疫之地",s="西瘟疫之地曾是洛丹伦北部肥沃的农业粮仓，如今却在有毒的迷雾和亡灵军团的压迫下窒息。虽然克尔苏加德的大熔炉毁掉了该地区的农场和城镇，但这片土地依然顽强地保留着生命。银色黎明、联盟、被遗忘者和血色十字军都在这片被蹂躏的田野上展开了绝望的抗争。",h="西瘟疫之地曾是洛丹伦北部肥沃的农业粮仓，如今却在有毒的迷雾和亡灵军团的压迫下窒息。虽然克尔苏加德的大熔炉毁掉了该地区的农场和城镇，但这片土地依然顽强地保留着生命。银色黎明、联盟、被遗忘者和血色十字军都在这片被蹂躏的田野上...",kw={"安多哈尔","亡灵壁垒","凯尔达隆","大熔炉","寒风营地","壁炉谷","玛登霍尔德城堡","通灵学院","乌瑟尔之墓","西瘟疫之地"},ang={["class:Paladin"]="洛丹伦被亵渎的田野是对圣洁战士的严峻考验，这里既有通往乌瑟尔之墓的朝圣之路，也有针对通灵学院和壁炉谷腐化狂热者的正义之战。",["faction:Alliance"]="寒风营地是联盟的前哨驻地，指挥官阿斯兰·斯托瓦尔在那里指挥部队干扰瘟疫大熔炉，并为洛丹伦陨落的城市复仇。",["faction:Horde"]="亡灵壁垒标志着被遗忘者主权的前线；从这里，部落向东推进，以消灭天灾指挥官，并对抗沿脆弱侧翼活动的血色十字军狂热者。",["profession:Herbalism"]="挥之不去的污染使得该地区成为少数几种罕见且危险的植物，如瘟疫花和阿尔萨斯之泪，能够在受瘟疫影响的松树林中扎根的地方之一。"},sec={{t="洛丹伦的粮仓",b="在第三次战争之前，这片土地是一条从提瑞斯法林地向东延伸至达隆米尔湖的青翠农田走廊。壁炉谷通过玛登霍尔德城堡进行北部管理，而广阔的安多哈尔城镇则负责整个王国的粮食储存和出口。这一关键的农业地位使得该地区成为了克尔苏加德的主要目标。通过直接在安多哈尔的粮食运输中引入亡灵瘟疫，The Cult of the Damned将洛丹伦的生命源泉变成了它的毁灭之源。"},{t="处于围困中的土地",b="为了永久污染这片土地，天灾军团在最大的几个农业区竖起了四座巨大的瘟疫大熔炉：费尔斯通农场、达尔松之泪、嚎哭鬼屋和盖罗恩农场。今天，可怕的熔炉领主们守护着这些有害的大缸，向大气中喷射毒雾。周围的树木因肿瘤般的生长而扭曲，被瘟疫感染的野生动物在灌木丛中横行。在达隆米尔湖的凯尔达隆下方，黑暗院长加丁在通灵学院内训练死灵法师，加剧了亡灵的威胁。"},{t="分裂的阵营",b="尽管天灾军团无处不在，几个阵营仍在此保持着艰难的立足点。血色十字军控制着北部的壁炉谷要塞，以狂热的态度清洗任何他们认为被玷污的事物。在南部，联盟部队以寒风营地为基地，而被遗忘者则在亡灵壁垒防御着他们的边界。中立的银色黎明负责调解并指挥对抗亡灵大熔炉的战斗，他们援助两个阵营的勇士，并守护着乌瑟尔之墓——这是该地区最后一片真正神圣的土地。"}},faq={{q="为什么瘟疫对该地区的打击如此严重？",a="安多哈尔是洛丹伦北部的农业运输枢纽。克尔苏加德蓄意针对该地区的供应，感染了粮仓，并在四个主要农场安装了巨大的瘟疫大熔炉，以便通过全国的粮食运输迅速传播亡灵瘟疫。",al={"西瘟疫之地为何受瘟疫侵袭","安多哈尔发生了什么","为何此处有大熔炉"}},{q="谁控制着北部的壁炉谷？",a="壁炉谷及其要塞玛登霍尔德城堡由血色十字军统治。虽然最初是洛丹伦的地区行政中心，但这群狂热者现在会处决任何接近他们边界的外来者，对所有非十字军成员都持怀疑态度。",al={"壁炉谷的阵营","谁住在玛登霍尔德城堡","壁炉谷友好吗"}},{q="联盟和部落玩家在哪里可以找到安全的哨所？",a="联盟在靠近奥特兰克山脉的南部边界维护着寒风营地，提供飞行管理员和银色黎明盟友。部落则从提瑞斯法林地进入，在西部边界的亡灵壁垒开展行动。",al={"飞行点在哪里","西瘟疫之地的部落营地","西瘟疫之地的联盟营地"}},{q="农田里的瘟疫大熔炉有什么用途？",a="这些大熔炉由诅咒神教在费尔斯通农场、达尔松之泪、嚎哭鬼屋和盖罗恩农场竖立，持续向空气和土壤中喷射瘟疫蒸汽。银色黎明的特工会招募冒险者去击杀熔炉领主，并对这些有毒的混合物进行反向工程。",al={"大熔炉是什么","大熔炉的用途","费尔斯通大熔炉"}},{q="什么是通灵学院，它位于何处？",a="通灵学院是一所由天灾军团和诅咒神教经营的地下死灵法术学院。它隐藏在凯尔达隆的废墟之下，那是一座位于达隆米尔湖东南水域的岛屿要塞。",al={"通灵学院的位置","通灵学院在哪里","凯尔达隆地下城"}},{q="西瘟疫之地有任何未被腐蚀的地方吗？",a="位于该地区南缘悔恨岭上的乌瑟尔之墓依然完全神圣，未受瘟疫影响。它是为陨落的高阶统帅乌瑟尔和失落的白银之手骑士团而立的神圣纪念碑。",al={"西瘟疫之地的圣地","乌瑟尔之墓干净吗","乌瑟尔之墓安全吗"}}},fp="19,342,28.378.0,18.438.0,16.443.0,41.268.0,37.227.0,56.233.0,58.277.0,44.206.0,51.204.0"}
P.entries["zone:westfall"] = {n="西部荒野",s="西部荒野的农场毫无防护，迪菲亚潜行者控制着大片乡野。这片土地曾是暴风城的粮仓，如今却失去了王室的支持和军队的驻守，处境艰难。",h="西部荒野的农场毫无防护，迪菲亚潜行者控制着大片乡野。这片土地曾是暴风城的粮仓，如今却失去了王室的支持和军队的驻守，处境艰难。",kw={"死亡矿井","迪菲亚","收割傀儡","民兵","月溪镇","萨丁","哨兵岭","斯托曼","范克里夫","西部荒野"},ang={["class:Rogue"]="身为潜行者，你会发现一场暗战遍布西部荒野，SI:7的间谍在这里对抗迪菲亚潜行者中熟悉街头门道的斥候、盗贼和刺客。",["faction:Alliance"]="身为联盟的旅人，你能看到人民军如何守住哨兵岭。没有这支队伍，迪菲亚潜行者就会控制通往艾尔文森林的南部要道。",["profession:Cooking"]="身为厨师，你可以了解萨丁农场陷入困境的农户如何靠当地肉质粗硬的野兽维生，又如何教旅人烹制杂味炖肉。",["race:Human"]="身为人类，你能从西部荒野看到暴风城政治的腐朽。那些在尘土中忍饥挨饿的农民，曾辛勤劳作供养贵族，如今却被他们抛弃。"},sec={{t="被遗弃的土地",b="西部荒野的牧场和麦田曾养活了暴风城王国。Second War过后，王国财政日渐拮据，统治者也忽视了这片领土。暴风城将资源调往别处，撤走了驻军。土地就此荒芜。\n\n如今，荒芜的牧场、猛烈的海风、失控的收割傀儡和河爪豺狼人，让少数仍留在这里的农户艰难求生。"},{t="兄弟会的崛起",b="迪菲亚潜行者的到来加速了西部荒野的衰败。这些匪徒戴着红色面罩，追随一位乡间无人知晓其姓名的首领。他们将西部荒野变成据点，焚烧农田，向土壤撒盐，还占据了废弃的矿井。\n\n兄弟会盘踞在已成鬼镇的月溪镇，虽无统治之名，却掌控着大部分乡野。"},{t="人民民兵",b="贵族对西部荒野的困境置之不理，当地居民只得自行保卫家园。在哨兵岭，格里安·斯托曼组建了人民军，这支志愿部队坚守防线，抵御豺狼人和匪徒。暴风城既不派遣正规军，也不提供补给。\n\n这支民兵队依靠四处游历的冒险者击退迪菲亚潜行者，保护仅存的农场。"},{t="红色面罩下的石匠",b="艾德温·范克里夫领导着兄弟会。他曾是主持重建暴风城的公会首领，但贵族拒绝支付石匠们的工钱，随后的暴乱让他们被逐出城。他们来到西部荒野，戴上了红色面罩。如今焚烧农田的匪徒，正是当年亲手筑起王都城墙的工匠。"},{t="死亡矿井的阴谋",b="在月溪镇地下，艾德温·范克里夫将亡命之徒、地精和叛逃者聚集在死亡矿井废弃的金矿坑道里。兄弟会正在那里建造一艘庞大的铁甲战舰。他们打算让它沿海岸航行，炮轰暴风城。"}},faq={{q="为什么西部荒野有这么多荒废的农场？",a="驻军开销变得过于高昂后，暴风城撤走了军队，让西部荒野失去了保护。迪菲亚潜行者随后占据了大片乡野，赶走农户，焚烧农田，还改写了机械收割看守的程序，将它们变成致命的哨兵。",al={"荒废的农场","西部荒野为何衰落","为何荒芜"}},{q="为什么暴风城不派兵援助西部荒野？",a="王国的国库捉襟见肘，贵族优先应对其他地区的威胁。宫廷中的暗中操纵也悄然夺走了西部荒野本应得到的关注和补给，让居民只能自行保卫家园。",al={"为何没有暴风城军队","卫兵在哪里","暴风城的援助"}},{q="什么是人民民兵？",a="格里安·斯托曼在哨兵岭组建了人民军，保卫西部荒野。王室没有派兵前来，农民和定居者便联合起来，对抗迪菲亚潜行者和河爪豺狼人。",al={"人民民兵","哨兵岭民兵","格里安·斯托曼军队"}},{q="谁在西部荒野领导迪菲亚潜行者？",a="艾德温·范克里夫曾是石匠行会的会长，如今领导着迪菲亚潜行者。他曾主持暴风城的重建，后来，一场激烈的工钱纠纷以暴乱告终，他便带领工人来到西部荒野，将他们武装起来。",al={"迪菲亚首领","谁领导迪菲亚","范克里夫"}},{q="月溪镇里隐藏着什么？",a="月溪镇一座不起眼的谷仓下，藏着死亡矿井的入口。迪菲亚潜行者将这座废弃金矿改造成地下堡垒和造船厂，用于对暴风城的战争。",al={"月溪镇的秘密","死亡矿井里有什么","月溪镇矿井"}},{q="为什么机械稻草人会攻击人？",a="效忠迪菲亚潜行者的地精技师夺取了机械收割看守。这些机械原本用来照料庄稼、驱赶害虫。他们将其改装，用来巡逻田野，杀死闯入者。",al={"收割傀儡攻击","收割看守者","邪恶的稻草人"}}},fx={cd1e134e={q="西部荒野是什么地方？",a="西部荒野是暴风城王国西部饱受风吹的领土，位于艾尔文森林以西，向南延伸至海岸。这里曾是王国富饶的粮仓，起伏的丘陵和广阔的牧场养育了世世代代的暴风城居民。如今，由于王室疏于照管，又遭战乱蹂躏，这里已沦为荒芜的尘土平原、破败的农庄和亡命之徒的地盘。",al={"这是什么区域","西部荒野介绍","西部荒野背景"}},["44cadea7"]={q="这里为什么如此荒凉？",a="干旱、疏于治理和匪患相互叠加，使乡间人去地空。第二次战争后，暴风城将兵力集中到别处，让当地农庄失去了防卫。迪菲亚潜行者崛起后，他们驱赶农民，焚烧庄稼，还向田地撒盐。没有王室驻军保护，大多数居民不是逃离，就是饿死。",al={"西部荒野为何荒芜","为何如此荒凉","这里为何无人"}},["1a97e791"]={q="西部荒野一直都这么贫穷吗？",a="完全不是。世世代代以来，西部荒野都是暴风城引以为傲的农业腹地，以金色的麦田、肥沃的土壤，以及詹戈洛德和死亡矿井等储量丰富的金矿闻名。在战争与内乱使这里变得荒芜之前，这里的粮食供养着都城，矿产则充实着王室的宝库。",al={"西部荒野是否一直贫穷","西部荒野过去是否富裕","西部荒野的过去"}},["1d4a9481"]={q="迪菲亚潜行者是什么组织？",a="迪菲亚潜行者是一个庞大的犯罪组织，成员包括叛乱的石匠、盗贼、强盗和流亡者。在艾德温·范克里夫的领导下，他们占据了西部荒野废弃的农田与矿井，对暴风城王国发动了一场残酷的暗战，决意为拖欠的报酬和他们认定的背叛讨回公道。",al={"迪菲亚是谁","迪菲亚潜行者是什么组织","这些匪徒是谁"}},b6953315={q="迪菲亚为什么戴着红色面罩？",a="红色面罩是迪菲亚潜行者的标志，而面罩的材质代表着成员的等级。红色丝质面罩是较高阶成员的身份标识；哨兵瑞尔要求冒险者收集这些面罩，作为击杀他们的凭证。",al={"为何戴红色面罩","迪菲亚红色面罩","红色面罩的含义"}},["908b4fe1"]={q="迪菲亚在西部荒野想要什么？",a="他们将西部荒野视为自己独立掌控的据点和集结之地。通过控制金矿、夺取粮食补给并驱逐效忠王国的农民，他们得以避开暴风城的直接监视，秘密扩充兵力、制造机械，同时图谋颠覆王国。",al={"迪菲亚想要什么","迪菲亚在西部荒野的目标","迪菲亚为何在西部荒野"}},d384bc2d={q="为什么派我来西部荒野？",a="你被指引到这里，是因为暴风城的正规军拒绝或无力向西部荒野派兵，使这片领土濒临彻底落入匪徒之手的境地。艾尔文的官员将有能力的冒险者引向西方，支援那些苦苦挣扎、急需援助的当地居民。",al={"为何来到西部荒野","谁派我来西部荒野","为何派我来这里"}},d59f010f={q="格里安·斯托曼是谁？",a="格里安·斯托曼是白银之手的圣骑士，也是西部荒野本地人。他在第三次战争期间于洛丹伦作战，返乡后却发现故土已被匪徒占据，暴风城的军队也早已撤离。于是，他召集当地的守卫者，在哨兵岭建立了人民军。",al={"斯托曼是谁","格里安·斯托曼","谁领导哨兵岭"}},af1c3ddb={q="格里安·斯托曼真的掌管着西部荒野吗？",a="实际上，是的。尽管暴风城的少年国王在法理上拥有西部荒野，王室在这里却几乎毫无实权。斯托曼和他驻扎在哨兵岭的志愿民兵，是这片领土上仅存的、仍能履行防卫和执法职责的力量。",al={"谁统治西部荒野","斯托曼是否是领袖","谁在掌权"}},c01912f7={q="石匠行会遭遇了什么？",a="在会长艾德温·范克里夫的领导下，石匠行会在第一次战争后耗费数年重建暴风城。工程完工后，贵族却拒绝支付约定的报酬。和平请愿无果后，公会被强行解散，引发了愤怒的暴乱，石匠们也因此被迫流亡。",al={"石匠遭遇了什么","石匠行会的故事","石匠们是谁"}},ec2fd06e={q="暴风城真的拒绝付钱给石匠吗？",a="是的。贵族为扩大在其他地方的军事远征积累了惊人的债务，使王国濒临破产。在宫廷阴谋和贵族傲慢的影响下，贵族们只肯为浩大的工程支付区区小钱，断然拒绝按契约付清报酬。",al={"暴风城是否欺骗了石匠","贵族为何不付钱","石匠报酬纠纷"}},cf60f690={q="西部荒野为什么有这么多豺狼人？",a="河爪豺狼人越过边境迁徙而来，趁暴风城士兵缺席之机占据这里。更糟的是，迪菲亚潜行者主动雇用他们充当打手，将他们部署在各处丘陵和平原，伏击旅人，侵扰尚存的农庄。",al={"豺狼人为何在这里","西部荒野的河爪豺狼人","丹努文豺狼人"}},e40fa3bd={q="月溪镇是什么地方？",a="月溪镇曾是西部荒野南部最主要的集市和矿业城镇。它坐落在死亡矿井的古老入口上方，后来被迪菲亚潜行者彻底占领并清空，如今他们利用镇上空置的建筑，守卫地下据点的外围。",al={"月溪镇是什么地方","月溪镇背景","月溪镇介绍"}},["46f1c864"]={q="对迪菲亚的调查会通向何处？",a="你的调查揭露了这个组织藏在月溪镇下方死亡矿井中的秘密核心。在地下洞穴深处，艾德温·范克里夫正监督建造一艘巨大的铁甲战舰，打算从海上炮轰暴风城，而你也将直接攻向这位会长本人。",al={"迪菲亚任务线通向何处","迪菲亚故事如何结束","死亡矿井结局"}},["27471424"]={q="我是怎么来到西部荒野的？",a="你很可能受官员或哨兵岭友人的指派，从艾尔文森林沿路西行，跨过河上的桥梁来到这里。暴风城兵力捉襟见肘，无力抽调王室军队，格里安·斯托曼和当地农民急需能人相助的消息便传遍了邻近地区。无论你是响应求援而来，还是只是沿着国王大道寻找工作，你都踏入了一片几乎已被王国士兵遗弃的领土。",al={"如何来到这里","如何来到西部荒野","怎么会来到这里"}},["6324593c"]={q="我在西部荒野该做些什么？",a="你的首要任务是协助哨兵岭的人民军，击退正在扼杀这片土地的重重威胁。格里安·斯托曼需要志愿者清剿凶猛的野兽，摧毁在休耕农田间游荡的失控收割看守者，并击退河爪豺狼人。最重要的是，你要追查行踪隐秘的迪菲亚潜行者，找出他们的藏身之处，打破他们对西部荒野残存农庄的控制，让艰难度日的农户得以喘息。",al={"这里该做什么","在西部荒野做什么","为什么来这里"}}},fp="8,190,18.391.0,27.355.0,20.380.0,19.294.1,24.254.1,44.264.0,52.230.0,29.199.0,45.227.1,32.204.1,51.187.0"}
P.entries["zone:wetlands"] = {n="湿地",s="湿地是一片广阔、终年笼罩在迷雾中的沼泽，坐落在卡兹莫丹群山和巴拉丁海湾的海岸线之间。由于历史上饱受矮人战争和兽人入侵的蹂躏，它成为了铁炉堡和北方的洛丹伦诸国之间一片崎岖的缓冲区。米奈希尔港这座坚固的港口，是联盟在这片被龙喉兽人、鱼人和豺狼人肆虐的潮湿荒野中的主要生命线。",h="湿地是一片广阔、终年笼罩在迷雾中的沼泽，坐落在卡兹莫丹群山和巴拉丁海湾的海岸线之间。由于历史上饱受矮人战争和兽人入侵的蹂躏，它成为了铁炉堡和北方的洛丹伦诸国之间一片崎岖的缓冲区。米奈希尔港这座坚固的港口，是联盟在这片被龙...",kw={"巴拉丁海湾","龙喉氏族","丹奥加兹","丹莫德","格瑞姆巴托","米奈希尔港","萨多尔大桥","湿地"},ang={["faction:Alliance"]="米奈希尔港是联盟穿过无尽之海的主要深水门户，连接着东部王国与卡利姆多的远征前哨站。",["profession:Mining"]="瑟根石的山丘和洞穴深处蕴藏着丰富的矿脉，包括矮人矿工和工程师梦寐以求的稀有火岩矿石。",["race:Dwarf"]="对于矮人来说，湿地是一个苦乐参半的地方，这里铭记着丹莫德的陷落、格瑞姆巴托的古老悲剧，以及保卫麦格尼国王通往北方贸易路线的持续努力。"},sec={{t="水与废墟之地",b="湿地在巨石水坝高耸的悬崖下延伸开来，是一片寒冷、泥泞、终年笼罩在迷雾和阴沉灰暗天空下的广阔地带。这里曾经是矮人繁荣的定居点，如今却散布着沉没的石质废墟、潮湿的沼泽和险恶的泥潭。进入该地区的冒险者必须穿越狭窄的隘口，或是从洛克莫丹翻过丹奥加兹那道设有路障的峡谷，或是穿过萨多尔大桥的高耸拱门，从阿拉希高地进入。"},{t="格瑞姆巴托的伤痕",b="沼泽的东部边缘被格瑞姆巴托那阴沉的身影所笼罩，这里曾是蛮锤部族的据点。在三锤之战中被玷污后，它在第二次战争期间成为了龙喉氏族的坚固堡垒。当红龙军团从兽人的囚禁中挣脱出来后，它们炽热的复仇之火摧毁了兽人的军队，并将周围的山坡夷为平地。如今，红龙人守卫着龙喉大门以抵御一切入侵者，而龙喉氏族的残余势力则盘踞在零星的山间营地中，继续骚扰穿过沼泽的旅行者。"},{t="西海岸的港口",b="米奈希尔港坐落在巴拉丁海湾的边缘，是联盟在卡兹莫丹贸易和后勤的跳动心脏。这座坚固的港口以泰瑞纳斯·米奈希尔二世国王的名字命名，通过定期往返塞拉摩岛的运输船，以及经由南海镇前往奥伯丁的航线，将东部王国与遥远的卡利姆多连接起来。尽管它具有重要的战略军事意义，且拥有坚固的矮人建筑，但港口却时刻受到海岸鱼人、沼泽生物和那些专门掠夺穿行于礁石航道船只的海盗的威胁。"},{t="被围困的前线",b="湿地是一个多线作战的活跃战区。在极北之地，由术士邪恶的巴加拉斯领导的黑铁矮人炸毁了萨多尔大桥，并占领了丹莫德镇，切断了陆路补给线。与此同时，苔藓皮豺狼人在中央沼泽横行霸道，甚至威胁到了像绿色守卫者雷希耶尔这样的古老守护者。在流氓兽人小队、黑铁矮人渗透者和海岸沿线的受诅沉船之间，想要守住这片沼泽需要时刻保持警惕。"}},faq={{q="我该如何步行前往湿地？",a="联盟冒险者通常从洛克莫丹向北穿过丹奥加兹山口。部落旅行者从北方出发，可以越过阿拉希高地的萨多尔大桥。请务必小心，因为这两条通道都被龙喉兽人和黑铁矮人等敌对势力所控制。",al={"如何前往湿地","前往湿地的路径","跑向湿地"}},{q="米奈希尔港的船只去往哪里？",a="米奈希尔港的码头运营着两条前往卡利姆多的主要航线：一艘船停靠在希尔斯布莱德丘陵的南海镇，然后穿过无尽之海前往黑海岸的奥伯丁；另一艘则向南航行至尘泥沼泽的塞拉摩岛。",al={"米奈希尔港的船只","湿地的船去往何处"}},{q="格瑞姆巴托是什么，为什么有人守卫？",a="格瑞姆巴托是一座古老的矮人堡垒，在三锤之战后被遗弃，后来被龙喉氏族占据。第二次战争结束后，获得自由的红龙军团驱逐了兽人并封锁了这座大山。强大的红龙龙人守卫着龙喉大门，阻止任何人进入那座被诅咒的大厅。",al={"为什么格瑞姆巴托有龙","格瑞姆巴托的红龙","龙喉大门"}},{q="丹莫德发生了什么？",a="丹莫德曾是一座保卫萨多尔大桥的北部矮人据点。它最近遭到了由邪恶的巴加拉斯领导的黑铁矮人的袭击并被占领。幸存者在拉格·加玛森的带领下，在附近维持着一个处于交战状态的营地，并为夺回他们的城镇而战。",al={"谁摧毁了丹莫德","丹莫德废墟","丹莫德的黑铁矮人"}},{q="谁是绿色守卫者雷希耶尔？",a="雷希耶尔是一只居住在湿地绿带草地的古老沼泽兽。他寻求旅行者的帮助，以遏制侵略性的苔藓皮豺狼人的浪潮，并消灭患病的沼泽爬行者，从而让沼泽得以恢复。",al={"绿带草地","雷希耶尔与湿地","谁是绿色守卫者"}},{q="沼泽里所有的兽人是从哪里来的？",a="这些兽人属于龙喉氏族，他们在第二次战争期间最初在格瑞姆巴托加固了防御。在被获得自由的红龙军团摧毁后，幸存的兽人逃入了沼泽和山丘中，他们至今仍在那里发动袭击，骚扰公路和旅行者。",al={"为什么湿地有兽人","湿地的龙喉氏族","龙喉氏族在湿地"}}},fp="8,284,24.340.0,23.473.0,22.380.0,18.430.0,40.227.0,41.185.0,41.317.0,26.225.0,31.198.1,46.224.0"}
P.entries["zone:winterspring"] = {n="冬泉谷",s="冬泉谷是一片广阔且白雪皑皑的山谷，坐落在海加尔山东北方向的高处，正上方是月光林地和费伍德森林的魔法森林。这片地区以苦寒的天气、古老的上层精灵废墟以及游荡的顶级掠食者而闻名，其中坐落着中立的地精据点永望镇。这里依然是一片充满自然险境的土地，既庇护着蓝龙军团的残部，又要直面其南部高地上的恶魔腐化。",h="冬泉谷是一片广阔且白雪皑皑的山谷，坐落在海加尔山东北方向的高处，正上方是月光林地和费伍德森林的魔法森林。这片地区以苦寒的天气、古老的上层精灵废墟以及游荡的顶级掠食者而闻名，其中坐落着中立的地精据点永望镇。这里依然是一片充...",kw={"蓝龙","暗语峡谷","多诺瓦·雪山","永望镇","霜刃豹","冰盖草","凯斯利尔","麦索瑞尔","木喉","冬泉谷"},ang={["class:Druid"]="冬泉谷位于月光林地的高处，具有神圣的意义，这里是玛法里奥·怒风在第三次战争期间唤醒猛禽德鲁伊沉睡之地。",["faction:Alliance"]="联盟英雄们经常造访位于霜刀石的雷沃·霜翼，在严寒中不懈努力，只为赢得那久负盛名的冬泉霜刃豹坐骑的忠诚。",["profession:Herbalism"]="冬泉谷是冰盖草唯一的已知栖息地，这种极其重要的阿尔卑斯草药是高级炼金药剂配方中急需的原料，此外还有稀疏分布的山鼠草和罕见的黑莲花。",["profession:Mining"]="山谷中冰冷的岩脊和洞穴墙壁蕴藏着丰富的珍贵矿产，经常可以发现瑟银矿脉和富瑟银矿脉，以及罕见的真银矿石。",["race:NightElf"]="冬泉谷与精灵历史紧密相连，拥有猛禽德鲁伊沉睡了千年的兽穴、悲剧性的凯斯利尔废墟，以及在海加尔山之战中受损的诺达希尔裸露根须。"},sec={{t="永恒霜冻之地",b="冬泉谷坐落在高出周边荒野数千英尺的地方，终年笼罩在清冷的空气和无休止的暴风雪中。世界之树诺达希尔巨大的裸露根须如同高耸的木制拱门一样切开了积雪，这些根须在第三次战争的关键战役中被扭曲变形。虽然卡利姆多北部大部分地区以茂密的森林和温暖的气候为主，但冬泉谷却是一个拥有中海拔高山森林、岩石断崖和冰封湖泊的寂静之地，是强大的霜刃豹、奇美拉、雪人和厚皮冬泉熊的家园。"},{t="十字路口与前哨站",b="想要抵达这片高原，必须穿过木喉要塞中那些古老的雕凿通道，那里有未受腐化的熊怪把守，他们会严密审查任何从费伍德森林或月光林地经过的旅行者。在山谷的中心坐落着繁荣的贸易城镇永望镇，由热砂港管理。地精们敞开登记处欢迎联盟和部落的冒险者，这里成为了应对刺骨山寒的重要避风港，提供工程学、贸易和温暖的炉火。"},{t="古老的幽灵与蓝龙",b="在现代定居点出现前几个世纪，古老的精灵建造了湖畔城市凯斯利尔。在鲁莽的上层精灵法师打碎了被诅咒的辛玛洛水晶后，疯狂吞噬了他们，至今仍有不安的幻影在破碎的石柱和冰封的水域中徘徊。在更南边升起的是麦索瑞尔那洞窟纵横的高地，这是蓝龙军团在卡利姆多的传统据点。在这里，织法者玛里苟斯的子嗣们在守护者哈莱的监视下，看守着奥术流并对抗着当地的威胁。"},{t="峡谷中阴影的逼近",b="冬泉谷的宁静在其最南端的边界——暗语峡谷处被彻底打破。在那里，精英恶魔部队（第三次战争留下的残余军团）在崎岖的峡谷中爬行，阻挡着通往海加尔山顶峰的高处通路。与此同时，当地的冬泉熊怪已经屈服于污秽的腐化，这促使像多诺瓦·雪山这样的独立研究者在整个山谷的野生动物被吞噬之前，开始调查这种蔓延的污染。"}},faq={{q="我该如何前往冬泉谷？",a="旅行者必须穿过木喉要塞，这是一条位于费伍德森林东北部的地下隧道网。想要平安通过这些洞穴，需要赢得当地木喉熊怪的信任，否则他们会攻击任何被视为敌人的闯入者。一旦穿过东面的出口，冬泉谷的雪坡便会豁然开朗。",al={"前往冬泉谷","如何进入冬泉谷","冬泉谷入口","木喉要塞隧道"}},{q="谁管理着永望镇？",a="永望镇由地精贸易联合体热砂港管理。由于地精严格的利润导向和中立立场，只要访客不在镇内破坏和平，部落和联盟的旅行者都可以使用那里的飞行管理员、修理商、银行金库和贸易商品。",al={"谁控制永望镇","永望镇阵营","永望镇是否中立"}},{q="凯斯利尔湖中闹鬼的幽灵是什么？",a="它们是万年前居住在古城凯斯利尔的上层精灵暗夜精灵的灵魂。当他们的法师篡改了被窃的辛玛洛水晶后，水晶的破碎释放了一个灾难性的诅咒。几个世纪后，随后的高等精灵探险队也同样陷入了疯狂，注定要和他们的祖先一起在这片冰冷的废墟中徘徊。",al={"凯斯利尔湖幽灵","凯斯利尔废墟灵魂","凯斯利尔有哪些人"}},{q="为什么冬泉熊怪具有攻击性？",a="冬泉熊怪已经屈服于一种正在蔓延的、非自然的腐化，这种腐化导致他们的部族陷入了疯狂的敌对状态。虽然附近的木喉部族仍然保持着理智，但冬泉熊怪已经落入了黑暗的影响之下，这促使像多诺瓦·雪山这样的研究者去研究这些污染并清理他们的营地。",al={"为什么冬泉熊怪敌对","冬泉部族腐化","多诺瓦·雪山熊怪"}},{q="麦索瑞尔里住着什么？",a="麦索瑞尔是蓝龙军团在卡利姆多的主要巢穴和圣地。在它那洞穴纵横的尖塔深处，龙人、精英雏龙和古老的幼龙在守护者哈莱（守护巨龙玛里苟斯的配偶）的注视下，守护着强大的龙族遗物和奥术秘密。",al={"麦索瑞尔巨龙","什么是麦索瑞尔","冬泉谷蓝龙"}},{q="什么是暗语峡谷？",a="暗语峡谷是位于山谷最南端的一条危险峡谷，被第三次战争遗留下来的强大精英恶魔所占据。它是通往海加尔山高处的险峻小径上一道戒备森严的防线。",al={"暗语峡谷恶魔","暗语峡谷有什么","海加尔山之门冬泉谷"}},{q="我可以在这里训练或驯服霜刃豹吗？",a="在山谷最北端的霜刀石，暗夜精灵雷沃·霜翼负责照料当地的白豹。协助他获取补给并保护豹群的冒险者，或许能证明自己有资格学习饲养和骑乘霜刃豹的秘诀。",al={"霜刃豹坐骑","雷沃·霜翼霜刃豹","如何获得霜刃豹"}}},fp="12,328,26.408.0,23.361.0,26.385.0,31.374.0,29.250.0,30.220.0,45.324.0,43.293.0,28.244.0,26.191.0,39.225.0"}
P.entries["zone:zephras"] = {n="泽风岛",s="泽风岛是悬浮在风元素位面天空之墙内的一座浮空岛屿。它是天裔的祖居地和初始家园。由于岛屿维持运转的魔法正在不断消退，他们的社会正面临着生存危机。随着与周边天空位面的联系中断，岛上的居民正努力应对元素崩溃带来的威胁，同时还要接纳各处涌来的难民。",h="泽风岛是悬浮在风元素位面天空之墙内的一座浮空岛屿。它是天裔的祖居地和初始家园。由于岛屿维持运转的魔法正在不断消退，他们的社会正面临着生存危机。随着与周边天空位面的联系中断，岛上的居民正努力应对元素崩溃带来的威胁，同时还要...",kw={"空艇","安维拉斯","元素位面","希洛卡斯","天裔","天空之墙","瓦拉纳尔","风石","泽风"},ang={["class:Shaman"]="泽风岛直接存在于风元素位面中，展示了当平衡元素之地的灵魂突然消失时，会发生怎样的景象。",["race:Skyborne"]="泽风岛是你的祖居地和初始之地，尽管它残留的美景之下掩盖着地形崩塌与元素力量消退的紧迫危机。"},sec={{t="云端位面",b="泽风岛是一块漂浮在天空之墙无尽风暴中的孤立陆地。世世代代以来，天裔与当地的风元素共同生活在此，这些元素帮助维持着岛屿漂浮所需的魔法流。然而，几个世纪前，这些元素守护者完全消失了。失去了它们的存在与庇护，支撑着这片土地的潜伏附魔已开始缓慢失效，导致泽风岛逐渐分崩离析，失去稳定。"},{t="断绝的视界",b="泽风岛并不是天裔在元素位面中居住的唯一庇护所。被称为Anvilas和Siroccas的姊妹岛屿也漂浮在天空之墙中，但在元素消失后，它们之间的通讯就断绝了。近来，来自这些崩解中的邻近陆地的难民设法抵达了泽风岛寻求庇护，他们带来了严峻的消息：其他岛屿正在他们的脚下彻底瓦解。"},{t="艾泽拉斯的门户",b="随着自身土地的缓慢衰败，泽风岛的天裔开始将目光投向天空之墙边界之外的艾泽拉斯。从瓦拉纳尔的空艇码头出发，飞船现已开始冒险建立起通往凡人位面的罕见生命线。这些航行将这片空灵的疆域直接连接到了艾泽拉斯的几处地点，包括奥特兰克山脉中的达拉然外围，以及莫高雷的观天者台地。"}},faq={{q="泽风岛位于何处？",a="泽风岛位于风元素位面天空之墙内，而非艾泽拉斯的表面。它漂浮在这片空灵疆域的永恒云层与风流之中。",al={"泽风岛位置","泽风在哪","泽风位于哪个位面"}},{q="为什么泽风岛正在崩塌？",a="这座岛屿依靠曾经与天裔共存的本地风元素而存在。几个世纪前，这些元素消失了，导致锚定和保护这座飞行岛屿的魔法基石随时间推移缓慢减弱并走向衰败。",al={"为什么泽风正在崩溃","泽风岛毁灭","垂死的岛屿"}},{q="安维拉斯和希洛卡斯是什么？",a="它们是天空之墙中同样居住着天裔的邻近浮空岛。当元素消失时，泽风岛与两者都失去了联系，而逃亡的难民现在报告称，安维拉斯和希洛卡斯都已经彻底湮灭。",al={"安维拉斯","西罗卡斯","其他天裔岛屿"}},{q="人们如何往返于泽风岛与艾泽拉斯之间？",a="天裔在瓦拉纳尔定居点运营着空艇码头。飞船从这些码头起飞，穿越位面边界前往艾泽拉斯，停靠在奥特兰克山脉的达拉然附近，以及莫高雷的观天者台地。",al={"如何离开泽风","泽风空艇","前往艾泽拉斯"}},{q="天裔是什么？",a="天裔是居住在泽风岛及其姊妹天空位面的居民。他们在天空之墙生活了世世代代，如今却因其飞行家园的束缚魔法消退，面临着家园缓慢毁灭的境地。",al={"天裔种族","谁住在泽风"}},{q="除了天裔，还有谁住在泽风岛上？",a="除了和平的村庄和来访的难民，岛上还受到当地强盗、穴居的夜爪洞穴生物，以及栖息在尖啸者巢穴和夜爪洞穴等地带野兽的困扰。",al={"泽风居民","泽风上的敌人"}}},fx={["1fd88046"]={q="泽风岛是什么地方？",a="泽风岛是一块高悬于天空之墙——风元素位面中的浮空陆地。数千年前，逃离埃雷萨拉斯迫害的暗夜精灵流亡者与当地风之灵达成交易；风之灵将岛屿托举至高空，以庇护他们。泽风岛是他们后裔——天裔的祖先圣所。",al={"泽风是什么","泽风岛简介","泽风岛信息"}},["7ea7c85c"]={q="泽风岛发生过什么？",a="高等精灵的祖先脱离了埃雷萨拉斯托塞德林王子的血腥统治后，泽风岛便升入了天空之墙。数千年来，天裔一直与空气元素和谐共处，但数百年前，那些元素守护者毫无解释地消失了。失去持续不断的魔法后，固定岛屿的石柱开始腐朽；邻近岛屿崩塌后，难民纷纷逃至此地，而内部各派系也在争夺日益匮乏的资源。",al={"泽风岛历史","泽风岛发生了什么","泽风岛背景故事"}},["70a3c6ae"]={q="泽风岛危险吗？",a="是的。除了岛屿本身日渐失稳、可能从高空坠落的迫近威胁外，元素守护者的消失也让这片土地陷入混乱。土匪营地、敌对野兽的巢穴，以及高阶会、塑风者和奥拉凯斯之间紧张的派系冲突，都使得离开设防定居点后的旅途危机四伏。",al={"泽风岛危险吗","泽风岛的威胁","泽风岛的危险"}},b4875d06={q="这座岛相对于艾泽拉斯其他地区位于何处？",a="泽风岛并非位于艾泽拉斯的地表，而是在天空之墙中漂浮。天空之墙是由泰坦造物打造、用于囚禁混乱空气元素的独立位面。泽风岛与下方凡世之间唯一的实体通道，是停靠在瓦拉纳尔、穿越边界前往达拉然和莫高雷等地的特制飞艇。",al={"泽风岛在艾泽拉斯的哪里","泽风岛在艾泽拉斯吗","泽风岛相对于艾泽拉斯的位置"}},["2c89f95d"]={q="奥拉凯斯人是谁？",a="奥拉凯斯是泽风岛上争夺主导权的派系之一，与高阶会和塑风者并立。随着固定岛屿的晶塔逐渐失效，生存变得愈发艰难，奥拉凯斯人正积极争夺霸权，以及对岛上剩余神秘资源的控制权。",al={"奥拉凯斯人是什么","奥拉凯斯派系","奥拉凯斯是谁"}},["6e14d755"]={q="我最终会离开这座岛吗？",a="会。泽风岛是你的家园，也是你开始接受训练的地方；飞艇会从瓦拉纳尔的空港出发，穿越位面裂隙前往艾泽拉斯大陆，直达奥特兰克山脉的达拉然和莫高雷的观天者台地。",al={"我会离开泽风岛吗","离开泽风岛","我们能去艾泽拉斯吗"}},["19470e71"]={q="我是怎么来到泽风岛的？",a="你出生于天裔族群，也就是居住在天空之墙——空气元素位面——高空浮岛上的辛多雷。数千年前，你的祖先逃离了埃雷萨拉斯王子托塞德林的清洗行动，并与风之灵缔结契约，由它们将这片圣所托举至天空。其他同源岛屿，如 安维拉斯 和 西洛卡斯，或已崩塌，或已渐渐远离，而泽风岛自始至终都是你的家。你将在此与自己的族人一同踏上旅程。",al={"我是怎么来到这里的","我是怎么到达泽风岛的","我为什么在这里醒来","我来自哪里"}},["5dae6f41"]={q="我在泽风岛应该做些什么？",a="你的家园正在你脚下崩塌。数百年前，仁慈的空气元素消失了，维系泽风岛的奥术晶塔也日渐失去力量。来自崩塌的外岛的难民涌入，而包括高阶会、塑风者和奥拉凯斯在内的敌对派系仍在为所剩无几的资源争斗。你必须帮助族人，平息内部威胁与野兽，协助稳定失效的魔法，并最终寻找一条通往艾泽拉斯的道路，以免岛屿坠毁。",al={"我在这里应该做什么","我在这里的目标是什么","我在泽风岛上做什么","我为什么在这里"}}},fp="12,263,13.353.0,16.350.0,20.265.0,30.156.0,34.190.0,30.197.0,54.178.0,21.180.0,47.152.0"}
